(window.GIM_TS=window.GIM_TS||{})["Yevamot.2"]={"from":48,"a":[["\u0003ברננה\u0004 \u0005[ברינון,\u0006 בשמועה, בחשד\u0005]\u0006 בלבד — \u0003לא מפקינן\u0004 \u0005[אין אנו מוציאים],\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 — \u0003ברננה לא מפקינן\u0004 \u0005[ברינון אין מוציאים].\u0006","\u0003וכולם\u0004 (החכם, והמביא גט, והמעיד לאשה שמת בעלה, שאמרנו שלא ישאו את הנשים שגרמו להתירן), \u0003שהיו להם נשים\u0004 באותה שעה של דין או עדות \u0003ומתו\u0004 נשיהם אחר כך — \u0003מותרות\u0004 אותן נשים שהתירו \u0003לינשא להם,\u0004 שאין אנו חוששים שעוד בחיי אשתו נתן עיניו בזו.","\u0003וכולן,\u0004 כל הנשים הללו שאסרו לשאתן משום חשד, אם \u0003נישאו לאחרים, ונתגרשו או שנתאלמנו — מותרות לינשא להם,\u0004 לאלה שהיו קשורים בדרך כלשהי להתרתן. \u0003וכולן,\u0004 כל הנשים שאסרו עליהן להינשא מפני החשד — \u0003מותרות לבניהם או לאחיהם\u0004 של המתירים.","שנינו במשנה שכולם אם היו להם בזמן ההיתר נשים ומתו, יכולות הנשים שהותרו על ידם להינשא להם. ומדייקים: \u0003מתו — אין\u0004 \u0005[כן],\u0006 אבל אם \u0003נתגרשו\u0004 נשותיהם — \u0003לא,\u0004 מפני שיחשדוהו שנתן עיניו באשה האחרת ובגללה גירש את אשתו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הלל לרב אשי: והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 במפורש: \u0003אפילו נתגרשו\u0004 מותרות! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003הא דהואי\u0004 \u0005[זה\u0006 כ\u0005שהיתה]\u0006 \u0003קטטה\u0004 בין הבעל והאשה עוד בשעה שהתיר, ויש לחשוש שכבר אז נתן עיניו באחרת, \u0003הא\u0004 \u0005[זה]\u0006 ש\u0003לא הואי\u0004 \u0005[היתה]\u0006 \u0003קטטה\u0004 באותה שעה, ונתגרשו מסיבה אחרת.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הא והא\u0004 \u0005[זה וזה]\u0006 ש\u0003לא הואי\u0004 \u0005[היתה]\u0006 \u0003קטטה\u0004 תחילה, ורק לאחר מכן התקוטטו והתגרשו. \u0003ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה];\u0006 \u0003הא דארגיל\u0004 \u0005[זה\u0006 כ\u0005שהתחיל]\u0006 \u0003הוא\u0004 בקטטה, שיש מקום לחשוד שנתן עיניו באשה אחרת ולכן חיפש עילה לגרש את אשתו, \u0003הא דארגילה\u0004 \u0005[\u0006ו\u0005זה שהתחילה]\u0006 \u0003היא\u0004 בקטטה, שאז אין מקום לחשוד בו.","שנינו במשנה: \u0003וכולן שנישאו\u0004 לאחרים ונתגרשו או נתאלמנו — מותרות להינשא לאלה שגרמו להתירן מתחילה. \u0003קא סלקא דעתין\u0004 \u0005[עלה בדעתנו]\u0006 לומר ש\u0003מיתה\u0004 שנאמרה כאן (\"נתאלמנו\") מדברת גם על ענין \u0003מיתה\u0004 האמורה במשנה הקודמת (\"מת\" \"הרגתיו\" \"הרגנוהו\"), כלומר, שאותה אשה שהועד בה שמת בעלה או שנהרג, נישאה לאחר וגם הוא מת, \u0003ו\u0004כן \u0003גירושין\u0004 שנאמרו כאן (\"נתגרשו\") באו אחרי \u0003גירושין\u0004 של זה שהעיד על כשרות הגט,","ואם כן \u0003נימא מתניתין דלא\u0004 \u0005[\u0006האם \u0005נאמר שמשנתנו אינה]\u0006 \u0003כ\u0004שיטת \u0003רבי, דאי\u0004 \u0005[שאם]\u0006 \u0003כ\u0004שיטת \u0003רבי\u0004 היא, \u0003האמר\u0004 \u0005[הרי אמר]\u0006 רבי: \u0003בתרי זימני הויא\u0004 \u0005[בשתי פעמים הריהי]\u0006 \u0003חזקה,\u0004 וחזקה היא שאשה זו גורמת למיתת בעליה (שהרי בשתי פעמים נוצרת חזקה), ואשה כזו (\"קטלנית\") אין לשאתה, וכיון שאין משנתנו חוששת לכך — משמע שאינה כדעת רבי!","ודוחים: \u0003לא,\u0004 מכאן אין הוכחה, כי אפשר לומר ש\u0003מיתה\u0004 האמורה במשנתנו מתייחסת לנושא ה\u0003גירושין\u0004 האמורים במשנה הקודמת, \u0003וגירושין\u0004 האמורים כאן, ביחס ל\u0003מיתה\u0004 האמורה במשנה הקודמת היא שנאמרה. שמדובר באשה שקודם נתגרשה ואחר כך מת בעלה, או קודם מת בעלה ואחר כך נתגרשה.","שנינו במשנה: \u0003וכולן\u0004, כל הנשים האלה, \u0003מותרות לבניהם או לאחיהם\u0004 של העוסקים בהתרתה. ותוהים: \u0003מאי שנא מהא דתנן\u0004 \u0005[\u0006ב\u0005מה שונה\u0006 דבר זה \u0005מזו ששנינו\u0006 במשנה אחרת\u0005]:\u0006 \u0003הנטען מן האשה,\u0004 שחושדים בו שנאף עם אשה מסויימת ש\u0003אסור\u0004 לא רק בה אלא גם \u0003באמה ובבתה ובאחותה.\u0004 ואילו כאן אנו מתירים לבניו ולאחיו על אף החשד!","ומשיבים: יש מקום לחלק, \u0003נשי לגבי נשי שכיחן דאזלן\u0004 \u0005[נשים אצל נשים מצוי ש\u0006הן \u0005הולכות]\u0006 לישון זו אצל זו, ויש לחשוש שמא תבוא הקרובה (שהיה חשוד עליה) לישון אצל אשתו, ויתפתה שוב לעבירה ויעבור על איסור עריות של קרובת אשתו. ואילו \u0003גברי לגבי גברי לא שכיחן\u0004 \u0005[גברים אצל גברים אינם מצויים]\u0006 ואף אם נישאת לקרובו — לא יבוא החשוד לישון שם ואין איפוא מקום לחשש.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לומר טעם אחר: \u0003נשי דלא אסרן שכיבתן אהדדי\u0004 \u0005[נשים שאין שכיבתן אוסרת זו את זו]\u0006 שכן אם נואף אדם עם קרובת אשתו, אין אשתו נאסרת עליו בכך, ועל כן \u0003לא קפדי אהדדי\u0004 \u0005[אין\u0006 הנשים הללו \u0005מקפידות זו על זו]\u0006 ושמא לא תקפיד אשתו אם החשוד ממשיך לנאוף עם האשה שנחשד עליה. אבל \u0003גברי דאסרן שכיבתן אהדדי\u0004 \u0005[\u0006ה\u0005גברים שאוסרת שכיבתם זה על זה],\u0006 שאם איש אחר שוכב עם אשה הרי הוא אוסרה לבעלה, ולכן \u0003קפדי אהדדי\u0004 \u0005[מקפידים\u0006 הם \u0005זה על זה].\u0006","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אביו נמי\u0004 \u0005[גם כן]\u0006 יהא מותר לשאת אשה שהותרה על ידי הבן, ומדוע נאמר \"בניהם או אחיהם\", ולא אביהם? ומשיבים: ודאי גם אביו מותר, אלא בלשון \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 \u0003קאמר\u0004 \u0005[אמר]:\u0006 \u0003לא מבעיא\u0004 \u0005[נצרכה]\u0006 לומר ב\u0003אביו\u0004 של המתיר שודאי מותר לו לשאת את האשה שהותרה על ידי הבן, כיון שאין חוששים שמא ינאף עימה בנו, המתיר, כיון \u0003דבזיז בניה מיניה\u0004 \u0005[ש\u0006הרי \u0005מתבייש בנו ממנו],\u0006 \u0003אבל בנו\u0004 של המתיר, ש\u0003לא בזיז\u0004 \u0005[מתבייש]\u0006 \u0003אביו מיניה\u0004 \u0005[ממנו],\u0006 ולכך יש איפוא לחשוש שמא יבוא אביו, המתיר, וינאף עימה בעודה נשואה לבנו, ולכך \u0003אימא\u0004 \u0005[\u0006שמא \u0005תאמר]\u0006 ש\u0003לא\u0004 תוכל להינשא לבנו, שיש מקום לחשד, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין לחשוש לכך.","","היו \u0003ארבעה אחין, שנים מהם נשואים\u0004 ל\u0003שתי אחיות, ומתו הנשואים את האחיות — הרי אלו,\u0004 האחיות, \u0003חולצות ולא מתייבמות.\u0004 כיון ששתיהן זקוקות לייבום לכל אחד מן האחים הנותרים, הרי כל אחת מהן היא אחות זקוקתו של כל אח — ואסורה עליו מדברי סופרים. \u0003ואם\u0004 לא שאלו בבית דין אם הדבר מותר להם ו\u0003קדמו וכנסו — יוציאו,\u0004 שגזרו חכמים שיגרשו אותן. \u0003ר' אליעזר אומר,\u0004 מחלוקת היא בדבר: \u0003בית שמאי אומרים: יקיים, ובית הלל אומרים: יוציאו.\u0004","\u0003היתה אחת מהן\u0004 מן האחיות הללו \u0003אסורה על האחד איסור ערוה,\u0004 שהיא קרובת אשתו (כגון חמותו או אם חמותו) או קרובתו מצד אמו — הרי הוא \u0003אסור בה, ומותר באחותה.\u0004 שכיון שזו היא קרובתו ופטורה מלהתייבם על ידו, הרי שאינה זקוקה לו, ונמצא שהאחרת אינה עוד אחות זקוקתו, ויכול לייבמה בהיתר. \u0003ו\u0004אולם האח \u0003השני\u0004 שאיננו קרוב לאחת מהן — \u0003אסור בשתיהן,\u0004 שהרי כל אחת מהן היא אחות זקוקתו.","היתה אחת מן הנשים הללו אסורה לו ב\u0003איסור מצוה\u0004 או ב\u0003איסור קדושה —\u0004 אחותה \u0003חולצת ולא מתייבמת\u0004 משום אחות זקוקתו. שגם האחות שהיא איסור קדושה זקוקה לחליצה.","\u0003היתה אחת מהן אסורה על זה איסור ערוה, והשניה אסורה על זה\u0004 על האח השני \u0003איסור ערוה —\u0004 הרי \u0003האסורה לזה מותרת לזה, והאסורה לזה מותרת לזה.\u0004","\u0003וזו היא שאמרו\u0004 בתמצית: \u0003אחותה כשהיא יבמתה,\u0004 שאם נופלות לייבום אחיות שהן יבמות (גיסות) ואחת מהן אסורה לו משום ערוה — האחרת \u0003או חולצת או מתייבמת,\u0004 שהרי שוב אין כאן איסור אחות זקוקתו וכל אחד מהם יכול לחלוץ או לייבם את האחות השניה. מן ההלכה במשנה מדייקים: \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003יש זיקה,\u0004 כלומר, שעצם חובת הייבום יוצרת כעין קירבה משפחתית, ובשל כך דין אחות זקוקתו כדין אחות אשתו. \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003אין זיקה, מכדי הני, מתרי בתי קאתיין\u0004 \u0005[הרי\u0006 שתי הנשים \u0005הללו, משני בתים,\u0006 בעלים, \u0005הן באות]\u0006 שהרי הן שייכות כל אחת לבית בעל אחר, ושתיהן צריכות ייבום, ומדוע לא תתייבמנה? \u0003האי לייבם חדא והאי לייבם חדא\u0004 \u0005[זה ייבם אחת וזה ייבם אחת],\u0006 ומה בכך? אלא ודאי יש זיקה, ואסורות הן משום אחות זקוקתו.","","ודוחים: \u0003לעולם אימא לך\u0004 \u0005[אומר לך]\u0006 שלדעת תנא זה \u0003אין זיקה,\u0004 ולא מטעם זה הן אסורות, אלא \u0003ומשום דקסבר\u0004 \u0005[ש\u0006הוא \u0005סבור]:\u0006 \u0003אסור לבטל מצות יבמין,\u0004 כלומר, אסור להביא למצב בו תתבטל מצות הייבום. וכיצד: \u0003דלמא אדמייבם חד מיית אידך\u0004 \u0005[שמא עד שייבם\u0006 ה\u0005אחד\u0006 מהם \u0005ימות\u0006 ה\u0005אחר]\u0006 ואז יהיה רק אח אחד וגם השניה נופלת לפניו לייבום \u0003וקמבטל\u0004 \u0005[ומבטל]\u0006 ממנה \u0003מצות יבמין\u0004 כי כאשר נושא אחת מהן, ממילא מצות ייבום (ואף חליצה) בטילה מן השניה, מפני שנעשית אחות אשתו.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שזהו טעם המשנה \u0003תלתא נמי\u0004 \u0005[\u0006אם היו \u0005שלושה\u0006 אחים \u0005גם כן]\u0006 קיים חשש זה, ומדוע דיברה המשנה בארבעה אחים? הלא יכלה לדון בשלושה אחים ושנים מהם נשואים שתי אחיות, וגם אז קיים הטעם של ביטול מצות יבמים, שכשייבם אחת מהן לא יוכל לייבם השניה?","ומשיבים: אכן, לענין הלכה כך הוא, אלא בלשון \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 \u0003קאמרינן\u0004 \u0005[אומרים אנו],\u0006 וכך יש להבין: \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר \u0003תלתא\u0004 \u0005[\u0006ב\u0005שלושה\u0006 אחים\u0005]\u0006 ש\u0003ודאי בטלה מצות יבמין,\u0004 שכשמייבם השלישי אחת מהן ודאי מבטל מצות הייבום מן האחרת. \u0003אבל ארבעה,\u0004 שאין חשש שמא ימות אחד משני האחים שנותרו, כיון ש\u0003למיתה לא חיישינן\u0004 \u0005[אין אנו חוששים]\u0006 וכל אחד מהם רשאי לייבם, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבכל זאת יש לחשוש.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שאנחנו חוששים למיתתם של האחים הנותרים, מדוע שנה הלכה זו דווקא בארבעה אחים —"],["\u0003חמשה\u0004 אחים ששניים מהם נשואים שתי אחיות, ומתו, ונפלו נשיהם לפני שלושת האחים הנשארים, \u0003נמי\u0004 \u0005[גם כן]\u0006 יאמר כמו כן שיש לחשוש שמא ימותו שנים מן הנותרים ויפלו שתי הנשים לייבום לפני האחרון! ומשיבים: \u0003למיתה דתרי\u0004 \u0005[של שנים]\u0006 בתוך זמן קצר \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים].\u0006","\u0003אמר רבה בר רב הונא אמר רב:\u0004 היו \u0003שלש אחיות יבמות,\u0004 משלושה אחים שנשאו שלוש אחיות, \u0003שנפלו\u0004 לייבום \u0003לפני שני אחין יבמין\u0004 שני האחים הנותרים — \u0003זה,\u0004 אח אחד, \u0003חולץ לאחת\u0004 מהן \u0003ו\u0004אח \u0003זה חולץ לאחת, ו\u0004ה\u0003אמצעית,\u0004 כלומר, האחות השלישית — \u0003צריכה חליצה משניהם.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה: מדקאמרת\u0004 \u0005[מ\u0006מה \u0005שאתה אומר]\u0006 כי ה\u0003אמצעית צריכה חליצה משניהם\u0004 משמע כי \u0003קסברת\u0004 \u0005[סבור אתה]\u0006 ש\u0003יש זיקה,\u0004 ושהזיקה יוצרת כעין קירבת משפחה, \u0003והויא לה\u0004 \u0005[והרי היא]\u0006 חליצה זו שיחלוץ כל אחד מן האחים לאחות השלישית \u0003חליצה פסולה,\u0004 שכיון שאין מצות הייבום יכולה להתקיים בה משום אחות חלוצתו — אף החליצה אינה חליצה כשרה וגמורה, ואינה יכולה לבטל את הזיקה שהיתה לשני האחים, \u0003ו\u0004כלל הוא ש\u0003חליצה פסולה צריך לחזור על כל האחין,\u0004 שכל אחד מהם צריך לחלוץ, וזה הטעם שצריכים שני האחים הנותרים לחלוץ לאמצעית, אולם,","\u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003קמייתא נמי\u0004 \u0005[הראשונות גם כן]\u0006 צריכות חליצה מכל האחים, שהרי חליצת כולן היא חליצה פסולה, שאי אפשר לייבמן משום אחות זקוקתו!","ומשיבים: \u0003אי דנפול\u0004 \u0005[אם\u0006 כ\u0005שנפלו]\u0006 לפניהם שלוש האחיות \u0003בבת אחת — הכי נמי\u0004 \u0005[כך\u0006 הוא \u0005גם כן]\u0006 שהיו שניהם צריכים לחלוץ לשלוש האחיות ו\u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא לאופן \u0003דנפול\u0004 \u0005[\u0006כ\u0005שנפלו\u0006 לפניהם\u0005]\u0006 \u0003בזו אחר זו,\u0004 שמשנפלה השניה כבר חלצה הראשונה, ומשנפלה השלישית כבר חלצה השניה.","כיצד: מת אחד האחים ו\u0003נפלה חדא\u0004 \u0005[אחת]\u0006 לייבום ו\u0003חלץ לה ראובן\u0004 (כלומר, אחד האחים) חליצה גמורה, שהרי אם היה רוצה היה יכול לייבמה, ואחר כך מת אח אחר ו\u0003נפלה אידך\u0004 \u0005[\u0006ה\u0005אחרת]\u0006 לייבום ואז \u0003חלץ לה\u0004 אחיו \u0003שמעון,\u0004 וגם שמעון מתוך שהיה רשאי גם לייבם אותה לפי שאיננה עבורו קרובת משפחה כלל שהרי אחיו כבר חלץ לאחותה וניתק את כל הקשר שלה עם המשפחה, לכן משחלץ לה הרי זו חליצה כשירה,","ומשמת השלישי ו\u0003נפלה אידך\u0004 \u0005[\u0006ה\u0005אחרת,\u0006 השלישית\u0005],\u0006 כאשר \u0003חלץ לה האי\u0004 \u0005[זה]\u0006 האח הראשון — \u0003מפקע\u0004 \u0005[מפקיע]\u0006 את \u0003זיקתו\u0004 שלו, \u0003ו\u0004כאשר \u0003חלץ לה האי\u0004 \u0005[זה]\u0006 השני \u0003מפקע\u0004 \u0005[מפקיע]\u0006 את \u0003זיקתו,\u0004 ואין אחד יכול להפקיע בחליצתו את הזיקה שיש לאח השני, כיון שכאן אין חליצה גמורה, שהרי היא לשניהם אחות חלוצה.","ושואלים מצד אחר: הרי דברים אלה נאמרו בשם רב, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב: אין זיקה\u0004 (לעיל יבמות יז, ב), ואילו הלכה זו הוסברה לפי ההנחה שיש זיקה! ומשיבים: אכן, לשיטת רב עצמו אין צורך בכך, אלא \u0003לדברי האומר יש זיקה קאמר\u0004 \u0005[הוא שאמר],\u0006 והוא עצמו איננו סבור כן.","\u0003ושמואל אמר\u0004 ופסק באותה בעיה: \u0003אחד חולץ לכולן,\u0004 לכל האחיות, ודי בכך. ומקשים: \u0003מכדי שמעינן ליה\u0004 \u0005[הרי שמענו אותו]\u0006 את \u0003שמואל\u0004 ש\u0003אמר: חליצה מעליא בעינן\u0004 \u0005[מעולה,\u0006 שלימה, \u0005אנחנו צריכים]\u0006 וחליצה שיש בה פסול איננה מועילה לפטור גמור, ש\u0003אמר שמואל\u0004 :"],["\u0003חלץ לאחיות\u0004 שביניהן — \u0003לא נפטרו\u0004 ה\u0003צרות.\u0004 ונראה שהטעם הוא, שמאחר שאיננו יכול לייבם את האחיות, שהרי כל אחת מהן היא אחות זקוקתו, אף חליצתן היא חליצה פגומה, וחליצה פגומה אינה יכולה לפטור את צרותיהן. משמע שאף שמואל סבור שחליצה צריכה להיות חליצה מעולה, כלומר, רק באותם מקרים שבהם יכולה לחול מצות ייבום. ולענייננו, \u0003היכא דקיימא\u0004 \u0005[היכן שקיימת]\u0006 אפשרות של \u0003חליצה\u0004 של \u0003שמעון\u0004 (האח השני שלא חלץ כלל) לשניה וחליצתו תהיה \u0003חליצה כשרה,\u0004 האם נאמר כי \u0003חליץ\u0004 \u0005[יחלוץ]\u0006 \u0003לה ראובן\u0004 (האח שכבר חלץ לאחות אחת) וחליצתו לשניה היא עכשיו \u0003חליצה פסולה?\u0004","ומתרצים: אין להבין את דברי שמואל כמשמעם, אלא \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אחד חולץ לכולן\" נמי דקאמר\u0004 \u0005[גם כן שאומר]\u0006 שמואל — לגבי ה\u0003אמצעית\u0004 שאכן לאמצעית (האחות השלישית) חולץ אחד משניהם. ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"כולן\" קאמר\u0004 \u0005[אמר],\u0006 משמע שלכל האחיות חולץ! ומשיבים: \u0003כיון דרובה גביה\u0004 \u0005[כיון שהרוב אצלו]\u0006 שהרי האח שחלץ לאחות אחת חולץ גם לזו, \u0003קרי ליה\u0004 \u0005[קורא לו]\u0006 \u0003\"כולן\". ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003שמואל\u0004 כי \u0003חליצה מעליא\u0004 \u0005[מעולה]\u0006 \u0003בעינן\u0004 \u0005[אנו צריכים]\u0006 — \u0003הני מילי למיפטר\u0004 \u0005[דברים אלה\u0006 אמורים כדי \u0005לפטור]\u0006 את \u0003צרתה\u0004 בחליצה זו, \u0003אבל מפטרא נפשה\u0004 \u0005[לפטור\u0006 את \u0005עצמה] —\u0006 \u0003פטרה\u0004 \u0005[פוטרת]\u0006 אפילו בחליצה כזו. וכאן, כיון שאין צרות — אפילו חליצה של אח אחד לכולן מספקת.","כיון שהוזכרו דברי שמואל, דנים עתה \u0003גופא\u0004 \u0005[לגופו]\u0006 של ענין. \u0003אמר שמואל\u0004: היו שלושה אחים, ושניים מהם היו נשואים כל אחד לכמה נשים, ושתים מאלה היו אחיות, ואחר כך מתו שני האחים הנשואים, והנשים נפלו לפני היבם, אם \u0003חלץ לאחיות — לא נפטרו צרות,\u0004 אבל אם חלץ \u0003לצרות — נפטרו אחיות.\u0004 וכן אם נתן גט לאחת מן הנשים הללו, ואז אינו רשאי עוד ליבמה לפי תקנת חכמים, אם \u0003חלץ לבעלת הגט — לא נפטרה צרה\u0004 על ידי כך שכיון שאינו יכול ליבמה אף חליצתה פגומה ואין חליצה פגומה זו יכולה לפטור צרתה, ואם חלץ \u0003לצרה — נפטרה בעלת הגט.\u0004","וכן אם עשה באחת מאלה מאמר, אם \u0003חלץ לבעלת המאמר — לא נפטרה צרה,\u0004 שאף חליצתה של זו פגומה, שכיון שעשה בה מאמר (קדושין) אין קדושין אלה בטלים אלא בגט, שצריכה גט, בנוסף לחליצה, כדי לפוטרה, ולכן אין כוח חליצה זו מספיק כדי לפטור את הצרה. אבל אם חלץ \u0003לצרה — נפטרה בעלת מאמר\u0004 מחליצה, ויצטרך לתת לה גט.","ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה],\u0006 מדוע, אם חלץ \u0003לאחיות\u0004 ש\u0003לא נפטרו צרות\u0004 על ידי כך — \u0003דהויא לו\u0004 \u0005[ש\u0006הרי \u0005היא לו]\u0006 \u0003אחות אשה בזיקה,\u0004 וכיון שאינו רשאי ליבמה, אף אין חליצתה חליצה גמורה, אם כן כאשר \u0003חלץ לצרות נמי\u0004 \u0005[גם כן]\u0006 \u0003לא ליפטרו\u0004 \u0005[יפטרו]\u0006 ה\u0003אחיות, דהויא להו\u0004 \u0005[ש\u0006הרי \u0005הן]\u0006 \u0003צרות אחות אשה בזיקה.\u0004 שאם האשה אסורה עליו (משום קירבה של זיקה), הרי צרתה היא צרת אשה אסורה עליו וגם חליצתה חליצה פגומה! ומשיבים: \u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003שמואל\u0004 ש\u0003אין זיקה,\u0004 שאין קשר הזיקה יוצר קירבה כלל.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר שמואל\u0004 במפורש \u0003יש זיקה\u0004 (לעיל יבמות יח, ב)! ומשיבים: הלכה זו, \u0003לדברי האומר אין זיקה קאמר\u0004 \u0005[אמר],\u0006 אף שהוא עצמו אינו סבור כך.","ושואלים: אם לפי השיטה שאין זיקה אמר, \u0003אי הכי\u0004 \u0005[אם כך],\u0006 כאשר \u0003חלץ לאחיות אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא נפטרו\u0004 בכך ה\u0003צרות? בשלמא\u0004 \u0005[נניח]\u0006 שה\u0003צרה\u0004 של \u0003רחל,\u0004 כלומר, של האחות השניה \u0003לא תיפטר,\u0004 ש\u0003כיון\u0004 ש\u0003חלץ לה ללאה,\u0004 כלומר לאחות הראשונה, \u0003והדר חלץ\u0004 \u0005[וחוזר\u0006 אחר כך ו\u0005חולץ]\u0006 \u0003לרחל,\u0004 השניה, \u0003הויא לה\u0004 \u0005[הרי]\u0006 נמצא כי ה\u0003חליצה\u0004 של \u0003רחל\u0004 היא \u0003חליצה פסולה,\u0004 כיון שאיננו יכול לייבם את רחל זו משום שהיא אחות חלוצתו, וחליצה פסולה אינה פוטרת את צרתה, \u0003אלא\u0004 ה\u0003צרה\u0004 של \u0003לאה — תיפטר,\u0004 שאם אין זיקה הרי חליצתה של הראשונה היתה חליצה גמורה!","ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לא נפטרו צרות\" נמי דקאמר\u0004 \u0005[גם כן שאמר]\u0006 שמואל — הכוונה ל\u0003צרה\u0004 של \u0003רחל,\u0004 האחות השניה. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"צרות\" קאמר\u0004 \u0005[אמר]\u0006 בלשון רבים, ולא צרה! ומשיבים: \u0003צרות דעלמא\u0004 \u0005[צרות בכלל],\u0006 כלומר, זו היא הלכה כללית, ולכן אמר אותה בלשון רבים, ולא התכוון למקרה המסויים הזה שבו מדובר רק בצרה אחת.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש בדברי שמואל שלשון רבים שנקט בה אין כוונתו על שתי הנשים אלא על אחת מהן בלבד, יש קושי בפיסקה האחרת: \u0003\"חלץ לצרות נפטרו אחיות\",\u0004 אולם \u0003ו\u0004כי על ידי חליצה ל\u0003צרת רחל, מי מיפטרא\u0004 \u0005[האם\u0006 רחל \u0005נפטרת]?\u0006 \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אסור אדם בצרת קרובת חלוצתו,\u0004 וכיון שחלץ לאחות אחת, הרי צרת אחותה (\"צרת רחל\") היא צרת אחות חלוצתו, וכיון שאסור בה — חליצתה היא חליצה פגומה ואינה פוטרת אחרות!","ומשיבים: \u0003שמואל נמי\u0004 \u0005[גם כן]\u0006 \u0003התחיל ולא התחיל קאמר\u0004 \u0005[אמר].\u0006 וכך התכוון לומר: אם \u0003התחיל\u0004 את מעשה החליצה \u0003ב\u0004אחת מן ה\u0003אחיות — לא יגמור בצרות,\u0004 ולא יעשה חליצה שניה באחת מהן, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אסור אדם בצרת קרובת חלוצתו\u0004 וחליצת הצרה לא תפטור את האחות השניה, שחליצה גרועה היא. אבל אם \u0003התחיל בצרות — יגמור אף באחיות. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה אחרת\u0005]:\u0006 \u0003מותר אדם בקרובת צרת חלוצתו.\u0004 ולכן אם חלץ לצרת לאה, רחל שהיא אחות צרת חלוצתו מותרת לו, ויכול לחלוץ לה חליצה גמורה ותפטור את צרתה.","\u0003רב אשי אמר: לעולם\u0004 יש לפרש \u0003כדקאמרת\u0004 \u0005[כפי\u0006 \u0005שאמרת]\u0006 בתחילה, שטעמו של שמואל בהלכות אלה הוא לשיטתו שיש זיקה, והקושיה שהקשינו: מדוע יפטרו האחיות בחליצת הצרות, בעוד שכל אחת מהן היא צרת אחות אשתו בזיקה — אין זו קושיה, שכן יש לומר \u0003ומשום דלא אלימא\u0004 \u0005[שאין אלימה,\u0006 חזקה\u0005]\u0006 ה\u0003זיקה לשוייה\u0004 \u0005[\u0006כדי \u0005לעשות]\u0006 את ה\u0003צרה\u0004 שיהא דינה \u0003כערוה\u0004 ממש.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב אשי: חלץ לאחיות — לא נפטרו צרות.\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם חלץ \u0003לצרות — נפטרו אחיות. מאי טעמא\u0004 \u0005[\u0006ו\u0005מה טעם]\u0006 הדבר — \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דקסבר\u0004 \u0005[שסבור]\u0006 תנא זה ש\u0003יש זיקה\u0004 ולפיכך לא נפטרו הצרות בחליצת האחיות, אבל \u0003ולא אלימא\u0004 \u0005[אלימה,\u0006 חזקה\u0005]\u0006 ה\u0003זיקה לשוייה\u0004 \u0005[לעשות אותה]\u0006 את ה\u0003צרה כערוה,\u0004 וצרות קרובה בזיקה אינן נפטרות מייבום, ולכן כאשר חולץ להן נפטרות בכך האחיות.","\u0003אמר ר' אבא בר ממל:\u0004 מכאן אין ראיה, שאפשר לומר כי \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 \u0003מני\u0004 \u0005[\u0006כדעת \u0005מי\u0006 היא\u0005] —\u0006 כדעת \u0003בית שמאי היא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003בית שמאי מתירין הצרות לאחין\u0004 ואף אם היו אלה צרות קרובותיו ממש היו מותרות בייבום. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שאתה מפרש שזו כשיטת בית שמאי שהצרות מותרות, אם כן \u0003יבומי נמי תתייבם\u0004 \u0005[גם כן תתייבם],\u0006 ומדוע מדובר פה רק בחליצה ולא בייבום?","ומשיבים: הכוונה היתה לא כבית שמאי לגמרי, אלא \u0003כר' יוחנן בן נורי.\u0004 ש\u0003אמר: בואו נתקן להן לצרות שיהו חולצות ולא מתייבמות.\u0004 ותימנע מחלוקת בית שמאי ובית הלל. ומקשים: \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]:\u0006 \u0003לא הספיקו לגמור את הדבר\u0004 ולתקן כר' יוחנן בן נורי \u0003עד שנטרפה השעה\u0004 בגזירות השמד, ולא תיקנו תקנה זו בפועל! \u0003אמר רב נחמן בר יצחק: אחריו,\u0004 לאחר מכן, \u0003חזרו\u0004 חכמים אחרים \u0003ותקנו\u0004 כשיטתו.","כיון שהוזכר בדברי שמואל ענין בעלת גט ובעלת מאמר, מביאים כי \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]\u0006 שאלה זו:"],["\u0003בעלת הגט ובעלת\u0004 ה\u0003מאמר,\u0004 לאחת מהם נתן גט ובאחת מהן עשה מאמר, \u0003איזו מהן קודמת\u0004 לחליצה? האם נאמר כי \u0003בעלת הגט עדיפא, משום דאתחיל\u0004 \u0005[שהתחיל]\u0006 \u0003בה בחליצה,\u0004 שהרי הגט הוא התחלה של פטור האשה ממנו, ולכן ראוי להמשיך בחליצה, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003בעלת מאמר עדיפא, משום\u0004 ש\u0003קרובה לביאה,\u0004 לפי שהמאמר הוא כמו קידושין באשה אחרת, ונעשה, כרגיל, כהקדמה לייבום, ולכן מוטב שיעשה בה חליצה לפי שקשר הזיקה נתחזק על ידי המאמר.","\u0003אמר רב אשי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה שנחלקו חכמים בדינו של מי שעשה מאמר ביבמה אחת ואחר כך בצרתה, או שנתן גט לשתיהן, האם תופס המאמר או הגט השני. ושנינו: \u0003ומודה רבן גמליאל\u0004 במקרה שנתן לאחת מהן גט ועשה בשניה מאמר, או שעשה מאמר בראשונה ונתן גט לשניה, \u0003שיש גט אחר מאמר,\u0004 כלומר, הגט שנתן לאחר שעשה מאמר ביבמה אחרת תופס במידה מסויימת, ומועיל כדי לפסול את הראשונה עליו ולהיאסר בקרובות השנייה כשם שהוא אסור בקרובות הראשונה, \u0003ומאמר\u0004 בשניה תופס במידה מסויימת גם \u0003אחר\u0004 ה\u0003גט\u0004 שנתן לראשונה, וצריכה השניה גט למאמרו ונאסר בקרובותיה, ומעתה:","\u0003אי\u0004 \u0005[אם]\u0006 \u0003גט עדיף\u0004 ממאמר — ש\u0003לא ליהני\u0004 \u0005[יועיל]\u0006 ה\u0003מאמר אבתריה\u0004 \u0005[אחריו],\u0006 \u0003ו\u0004להיפך: \u0003אי\u0004 \u0005[אם]\u0006 \u0003מאמר עדיף\u0004 על גט — ש\u0003לא ליהני\u0004 \u0005[יועיל]\u0006 ה\u0003גט אבתריה\u0004 \u0005[אחריו],\u0006 \u0003אלא לאו שמע מינה כי הדדי נינהו\u0004 \u0005[האם לא תלמד מכאן\u0006 ששניהם \u0005זה כמו זה הם].\u0006 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]:\u0006 ואם כן — אין דין קדימה לבעלת גט או לבעלת מאמר.","\u0003אמר רב הונא אמר רב: שתי אחיות\u0004 שהיו \u0003יבמות\u0004 (נשואות לשני אחים) ומתו בעליהן, \u0003שנפלו לפני יבם אחד, חלץ ל\u0004זו שנפלה לפניו \u0003ראשונה — הותרה\u0004 להינשא לכל אדם, \u0003חלץ ל\u0004זו שנפלה לפניו \u0003שנייה — הותרה\u0004 גם היא להינשא לאחרים. והוא הדין אם חלץ בתחילה לשניה ואחר כך לראשונה.","אבל אם \u0003מתה\u0004 ה\u0003ראשונה\u0004 לפני שהספיק לחלוץ לה — \u0003מותר\u0004 היבם \u0003בשנייה,\u0004 שהרי אפילו אם היה נשוי ממש לראשונה, הרי מותר לאדם לשאת אחות אשתו אחר מותה. \u0003ואין צריך לומר\u0004 שאם \u0003מתה\u0004 ה\u0003שנייה\u0004 לפני שחלצה, \u0003שמותר בראשונה, משום דהויא\u0004 \u0005[שהיא]\u0006 עבורו בגדר של \u0003יבמה שהותרה\u0004 לו עם נפילתה, \u0003ונאסרה\u0004 לאחר מכן, כשנפלה לפניו האחות השניה לייבום ואסרה עליו את הראשונה משום אחות זקוקתו, \u0003וחזרה והותרה\u0004 על ידי מותה של השניה, ולכן — \u0003תחזור להיתירה הראשון\u0004 לגמרי.","\u0003ור' יוחנן אמר:\u0004 אם \u0003מתה\u0004 ה\u0003שנייה — מותר בראשונה,\u0004 כיון שבשעת נפילתה היתה ראויה לו. \u0003אבל\u0004 אם \u0003מתה\u0004 ה\u0003ראשונה — אסור בשנייה. מאי טעמא\u0004 \u0005[מה טעם]\u0006 אמר זאת — \u0003שכל יבמה שאין אני קורא בה בשעת נפילה,\u0004 כלומר, בשעה שמת בעלה, כשהיא נופלת לפני היבם, אם אי אפשר לקיים בה אז \u0003\"יבמה יבא עליה\",\u0004 משום שהיא אסורה עליו באותה שעה — \u0003הרי זו\u0004 נחשבת מאז לעולם \u0003כאשת אח שיש לה בנים, ואסורה\u0004 עליו. וכיון שהאחות השניה עם נפילתה היתה אסורה עליו משום אחות זקוקתו, שוב אין לה תקנה עבורו.","ושואלים: \u0003ו\u0004כי \u0003רב לית ליה האי סברא\u0004 \u0005[אין לו,\u0006 אינו מקבל, \u0005סברה זו]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב\u0004 עצמו כמעט באותה לשון: \u0003כל אשה שאין אני קורא בה בשעת נפילה \"יבמה יבא עליה\" — הרי היא כאשת אח שיש לו בנים, ואסורה?\u0004 ומשיבים: \u0003הני מילי היכא דקאי באפה\u0004 \u0005[דברים אלה\u0006 אמורים \u0005במקום שעומד בפניה]\u0006 ומונע אותה מביאה \u0003איסור אחות אשה\u0004 שהוא איסור \u0003דאורייתא\u0004 \u0005[של תורה],\u0006 כגון שהיתה היבמה אחות אשתו — הרי היא נאסרת עליו לעולם, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 הלא איסורה רק משום \u0003זיקה דרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003היא,\u0004 ואין הזיקה מעין זו יכולה לאוסרה עליו לעולם, ולכן אם מתה — השניה מותרת.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוסי בר חנינא לר' יוחנן,\u0004 שנינו: \u0003ארבעה אחין, שנים מהם נשואים\u0004 ל\u0003שתי אחיות, ומתו הנשואים את האחיות\u0004 — \u0003הרי\u0004 אחיות \u0003אלו חולצות ולא מתייבמות. ואמאי\u0004 \u0005[ומדוע]?\u0006 הלא יש להן היתר, \u0003ליקו חד מינייהו\u0004 \u0005[שיעמוד אחד מהם]\u0006 מן האחים, \u0003לחלוץ\u0004 \u0005[\u0006ו\u0005שיחלוץ]\u0006 \u0003לה לשנייה,\u0004 זו שמת בעלה מאוחר יותר, \u0003ו\u0004על ידי כך \u0003תיהוי\u0004 \u0005[תהיה]\u0006 ה\u0003ראשונה לגבי אידך\u0004 \u0005[\u0006האח \u0005האחר]\u0006 שלא עשה בה מעשה, \u0003כיבמה שהותרה\u0004 בשעת נפילה \u0003ונאסרה\u0004 אחר כך, כשמת בעל השניה, משום איסור זקוקתו, \u0003וחזרה והותרה\u0004 על ידי חליצת האחות, ועל כן \u0003תחזור להיתירה הראשון!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003אחיות איני יודע מי שנאן.\u0004 כלומר, אני מפקפק במשנה זו ואינני סבור שגירסתה נכונה, משום שאינני יכול למצוא לה הסבר לפי שום שיטה שהיא. ושואלים: מדוע ענה ר' יוחנן באופן מוחלט כל כך, \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 תירוץ אחר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חולצות\" נמי דקתני\u0004 \u0005[גם כן ששנה] —\u0006 הכוונה היא ש\u0003חולצת חדא\u0004 \u0005[אחת]!\u0006 ומשיבים: אי אפשר לתרץ כך, שהרי \u0003\"חולצות\"\u0004 בלשון רבים \u0003קתני\u0004 \u0005[שנה].\u0006","ושואלים: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 ר' יוחנן: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"חולצות\" — חולצות דעלמא\u0004 \u0005[בכלל],\u0006 שבמקרים הללו נשים אלה חולצות! ומשיבים: \u0003\"הרי אלו\" קתני\u0004 \u0005[שנה],\u0006 ההדגשה במלה \"אלו\" באה ללמד: אלו ולא אחרות, משמע שמדובר בשתיים אלה דווקא. ושואלים עוד: \u0003ולימא\u0004 \u0005[ושיאמר]:\u0006 שבמשנה מדובר במקרה מסויים \u0003דחליץ ליה\u0004 \u0005[שחלץ]\u0006 \u0003לראשונה ברישא\u0004 \u0005[בתחילה]\u0006 ולכן אין עוד היתר לשניה, שהרי לשיטתו היתר זה הוא רק כאשר חולץ לשניה תחילה! ומשיבים: גם כך אי אפשר לומר, כי \u0003\"חולצות\"\u0004"],["\u0003לכתחלה\u0004 הוא ש\u0003קתני\u0004 \u0005[\u0006ש\u0005שנה]\u0006 שנראה שאין דרך אחרת, וכך צריך לעשות. ושואלים עוד: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 כך: \u0003גזירה\u0004 היא זו שלא לחלוץ לשניה ולייבם את הראשונה, מתוך חשש \u0003דלמא קדים וחליץ\u0004 \u0005[שמא יקדם ויחלוץ]\u0006 \u0003לראשונה ברישא\u0004 \u0005[בתחילה]\u0006 ואז אסור לייבם את השניה, ולכן גזרו גם כשחלץ קודם לשניה! ומשיבים: \u0003\"ולא מתייבמות\" קתני\u0004 \u0005[שנה],\u0006 כלומר, \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003דין יבום הכא\u0004 \u0005[כאן]\u0006 \u0003כלל,\u0004 משמע אפילו בדיעבד כשחלץ לשניה אין בראשונה דין ייבום.","ושואלים: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 שהטעם הוא אחר: \u0003גזירה שמא\u0004 עד שיספיק לייבם את אשת האח הראשון שמת, \u0003ימות\u0004 האח השני, ותיפול לפניו אשתו של האח שהיא אחות זקוקתו, וכתוצאה מכך לא יוכל לייבם אף אחת מהן, \u0003ואסור לבטל מצות יבמין!\u0004 ומטעם זה אסרו לייבם כשנפלו שתי אחיות, ולא משום אחות זקוקתו! ומשיבים: \u0003ר' יוחנן למיתה לא חייש\u0004 \u0005[אינו חושש],\u0006 שלדעתו אין לגזור גזירות בשל חשש זה.","ושואלים: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 ר' יוחנן שמשנה זו בשיטת \u0003ר' אלעזר היא,\u0004 שיש לו שיטה אחרת בכלל, ש\u0003אמר: כיון שעמדה עליו\u0004 היבמה \u0003שעה אחת באיסור —\u0004 אפילו לאחר נפילתה \u0003נאסרה עליו עולמית.\u0004 ואפשר לפרש את המשנה כשיטת ר' אלעזר. ומשיבים: \u0003מדסיפא\u0004 \u0005[מ\u0006כיון \u0005ש\u0006ב\u0005סופה]\u0006 של אותה משנה מפורשת דעת \u0003ר' אלעזר,\u0004 משמע כי \u0003רישא לאו\u0004 \u0005[ראשה,\u0006 תחילתה, \u0005אינה]\u0006 כשיטת \u0003ר' אלעזר.\u0004 ולכן אינני יכול להסביר חלק זה כר' אלעזר.","ושואלים: \u0003ונימא ליה\u0004 \u0005[ושיאמר לו]\u0006 שכאן מדובר \u0003דנפול\u0004 \u0005[שנפלו\u0006 שתיהן\u0005]\u0006 \u0003בבת אחת,\u0004 שמתו שני האחים בבת אחת, \u0003ו\u0004על פי שיטת \u0003ר' יוסי הגלילי היא,\u0004 ש\u0003אמר: אפשר לצמצם,\u0004 כלומר, שני דברים שווים במידה אפשר לכוון שיהיו שווים במידתם בדיוק נמרץ, וכן שני מאורעות הבאים בזמן אחד, ניתן לכוון בדיוק מוחלט את בואם באותו זמן, ואף כאן יש לומר שמתו שני האחים בזמן אחד במדוייק! ומשיבים: \u0003לא סתם לן\u0004 \u0005[לנו]\u0006 ה\u0003תנא\u0004 שתהא סתם משנה \u0003כ\u0004שיטת \u0003ר' יוסי הגלילי.\u0004 כלומר, שיטתו זו לעולם איננה כתובה כסתם משנה אלא כדעת יחיד.","ושואלים: \u0003ולימא ליה\u0004 \u0005[ויאמר לו]\u0006 הסבר אחר, שאמנם מתו בזה אחר זה, אלא \u0003דלא ידעינן הי נפול ברישא\u0004 \u0005[שאין אנו יודעים איזו נפלה בתחילה\u0006 לייבום\u0005].\u0006","ומשיבים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 — \u0003היינו דקתני\u0004 \u0005[זה ששנינו]\u0006 בסוף המשנה שאם \u0003קדמו וכנסו יוציאו,\u0004 מדוע יוציאו? \u0003בשלמא\u0004 \u0005[נניח]\u0006 לגבי האח שייבם את ה\u0003ראשונה אמרינן ליה\u0004 \u0005[אומרים אנו לו]\u0006 למייבם \u0003מאן שריא לך\u0004 \u0005[מי התיר\u0006 אותה \u0005לך]?\u0006 שהרי היא אחות זקוקתך ולכן עליך להוציאה, \u0003אלא\u0004 זה שמייבם את ה\u0003שניה,\u0004 הלא \u0003אמר\u0004 (יכול לומר): \u0003חבראי\u0004 \u0005[חברי]\u0006 אחי, הוא אשר את ה\u0003שניה ייבם,\u0004 ואילו \u0003אנא\u0004 \u0005[אני]\u0006 את ה\u0003ראשונה\u0004 אני \u0003מייבם.\u0004 וכיון שהאח האחר כבר יבם את השניה — ממילא אין האחרת עוד אחות זקוקה, ובטל האיסור ממנו. ומדוע יוציאה ממנו!","ומסבירים: אכן, \u0003היינו דקאמר ליה\u0004 \u0005[זהו שאמר לו]\u0006 ר' יוחנן לר' יוסי בר חנינא: \u0003אחיות איני יודע מי שנאן,\u0004 שלפי השיקולים הללו איננו יכול ליישב את שיטת המשנה הזו כראוי.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003היתה אחת מהן אסורה על האחד איסור ערוה —\u0004 הרי הוא \u0003אסור בה, ומותר באחותה,\u0004 שכיון שפטור מלייבם את זו שהיא ערוה עליו, ממילא השניה אינה נחשבת כלל כאחות זקוקתו ומותרת להתייבם לו, \u0003ו\u0004אילו האח \u0003השני אסור בשתיהן,\u0004 שכיון שמותר בשתיהן, הרי כל אחת מהן אסורה עליו משום אחות זקוקתו. \u0003סלקא דעתין\u0004 \u0005[עלה על דעתנו]\u0006 לומר ש\u0003נפלה\u0004 לפניו זו שהיתה איסור ערוה, כגון \u0003חמותו, תחלה\u0004 לייבום ורק אחר כך מת האח השני ונפלה גם אשתו לייבום.","ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 אסור בשתיהן? \u0003ליקו\u0004 \u0005[שיעמוד]\u0006 ה\u0003חתן לייבם הך\u0004 \u0005[וייבם את\u0006 האחות \u0005הזו]\u0006 ש\u0003אינה חמותו ברישא\u0004 \u0005[בתחילה]\u0006 \u0003ו\u0004ממילא \u0003תהוי\u0004 \u0005[תהיה]\u0006 \u0003חמותו לגבי אידך\u0004 \u0005[האחר]\u0006 \u0003כיבמה שהותרה\u0004 עם נפילתה, \u0003ונאסרה\u0004 אחר כך כאחות זקוקתו על ידי נפילת אחותה, \u0003וחזרה והותרה\u0004 על ידי שאחיו ייבם את אחותה, ואם כן \u0003תחזור להיתרה הראשון\u0004 ויהא רשאי לייבמה!","\u0003אמר רב פפא:\u0004 צריך לומר שבמשנה מדובר \u0003כגון\u0004 ש\u0003נפלה הך\u0004 \u0005[זו]\u0006 ש\u0003אינה חמותו ברישא\u0004 \u0005[תחילה]\u0006 לייבום ואז היתה מותרת לשניהם, וכשנפלה גם אחותה לייבום, נאסרו שתיהן על האח השני, משום אחות זקוקה.","במקרה ששני האחים בכל זאת קדמו וכנסו, שנינו במשנה שיוציאו, ו\u0003ר' אליעזר אומר\u0004 שיש בזה מחלוקת בין בית שמאי ובית הלל, ש\u0003בית שמאי אומרים:\u0004 יקיימו, ובית הלל אומרים: יוציאו. \u0003תניא\u0004 \u0005[שנינו\u0006 בתוספתא\u0005]\u0006 נוסחה רחבה יותר, \u0003ר' אליעזר אומר: בית שמאי אומרים: יקיימו, ובית הלל אומרים: יוציאו. ר' שמעון אומר: יקיימו. אבא שאול אומר\u0004 היפך דברי ר' אליעזר: \u0003קל היה להם לבית הלל בדבר זה.\u0004 כלומר, בהלכה זו בית הלל הם המקילים, \u0003שבית שמאי אומרים: יוציאו, ובית הלל אומרים: יקיימו.\u0004","על ברייתא זו שואלים: דעת \u0003ר' שמעון כמאן\u0004 \u0005[כ\u0006דעת \u0005מי\u0006 היא\u0005]?\u0006 שכיון שהדבר שנוי במחלוקת בין בית הלל ובית שמאי (אמנם בשתי שיטות הפוכות) לא היה צריך ר' שמעון לנסח את ההלכה בדרך זו, שהרי \u0003אי\u0004 \u0005[אם]\u0006 הוא סבור ש\u0003בית שמאי\u0004 הם הסוברים שיקיימו — \u0003היינו\u0004 \u0005[זוהי]\u0006 שיטת \u0003ר' אליעזר,\u0004 והיה לו לומר זאת בלשון זו. \u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 ר' שמעון סבור ש\u0003בית הלל\u0004 הם הסוברים שיקיימו — \u0003היינו\u0004 \u0005[זוהי]\u0006 שיטת \u0003אבא שאול!\u0004 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 ר' שמעון, והיא שיטה שלישית, שלדעתו \u0003לא נחלקו\u0004 כלל \u0003בית שמאי ובית הלל בדבר זה,\u0004 והכל מודים שיקיימו.","שנינו במשנה שאם \u0003היתה אחת מהן\u0004 אסורה על האחד איסור ערוה — אסור בה ומותר באחותה. ושואלים: \u0003הא תנינא חדא זימנא\u0004 \u0005[הרי\u0006 כבר \u0005שנינו\u0006 דבר זה \u0005פעם אחת]:\u0006 \u0003אחותה כשהיא יבמתה,\u0004 שאם נופלות לייבום אחיות שהן יבמות (גיסות) ואחת מהן אסורה לו משום ערוה — האחרת \u0003או חולצת או מתייבמת!\u0004","ומשיבים: \u0003צריכא\u0004 \u0005[נצרך]\u0006 הדבר להיאמר גם כאן, \u0003דאי אשמועינן התם\u0004 \u0005[שאם היה משמיע לנו\u0006 את ההלכה הזו רק \u0005שם]\u0006 (לעיל יבמות כ, א), כאשר נאמרה ההלכה בלשון כללית, הייתי אומר: \u0003משום דליכא למיגזר\u0004 \u0005[שאין\u0006 מקום \u0005לגזור]\u0006 \u0003משום\u0004 האח ה\u0003שני,\u0004 שהרי מדובר שם רק ביבם אחד ואחות אחת מותרת לו והאחרת אסורה, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 שיש שני אחים \u0003דאיכא למיגזר\u0004 \u0005[שיש\u0006 מקום \u0005לגזור]\u0006 \u0003משום\u0004 החשש שמא יבוא ה\u0003שני\u0004 ששתיהן מותרות לו וייבם אחת מהן ובכך יפגע באחות זקוקתו, ואם כן \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 נאמרה הלכה זו אף לגבי האח שאחת מהן ערוה לו, ונגזור שתהיינה היבמות אסורות לשניהם.","\u0003ו\u0004להיפך: \u0003אי אשמועינן הכא\u0004 \u0005[אם היה משמיע לנו\u0006 רק \u0005כאן],\u0006 אפשר היה לומר: \u0003משום דאיכא\u0004 \u0005[שיש]\u0006 עוד אח \u0003שני דקא מוכח\u0004 \u0005[שמוכיח]\u0006 שהרי הוא אסור בשתיהן, והכל למדים מכאן שיש איסור לייבם שתי אחיות זקוקות, ולא יבואו לטעות בדבר, \u0003אבל התם דליכא\u0004 \u0005[שם שאין]\u0006 אח \u0003שני, אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 נאמרה הלכה זו, ונגזור שלא ייבם מהחשש שמא יבואו להקל באחות זקוקתו, על כן \u0003צריכא\u0004 \u0005[נצרכה\u0006 הלכה זו להיאמר\u0005]\u0006 בשני המקומות.","עוד שנינו במשנה: אם היה איסורה של היבמה \u0003איסור מצוה\u0004 או איסור קדושה — חולצת ולא מתייבמת. ותוהים: \u0003הא נמי תנינא\u0004 \u0005[\u0006הרי \u0005זו גם כן שנינו]:\u0006"],["\u0003איסור מצוה ואיסור קדושה\u0004 — \u0003חולצת ולא מתייבמת!\u0004 ומשיבים: יש חידוש בדבר: \u0003התם\u0004 \u0005[שם]\u0006 שדן בהלכה זו בכלל, מדובר ב\u0003איסור מצוה לחודה\u0004 \u0005[לעצמה],\u0006 שנפלה לבדה לייבום ואיסור מצוה בלבד הוא המונע מלייבם אותה, ואולם \u0003הכא\u0004 \u0005[כאן],\u0006 הרי יש גם \u0003איסור מצוה, ו\u0004גם \u0003אחותה\u0004 הנופלת לפניו לייבום עם זו,","ולכך \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]:\u0006 \u0003ליקום\u0004 \u0005[יעמוד,\u0006 יבוא\u0005]\u0006 \u0003איסור מצוה במקום\u0004 ובאותה דרגה של \u0003איסור ערוה,\u0004 שהרי אם היתה אחת האחיות אסורה על היבם איסור ערוה — מותר באחותה, שכיון שהיא עצמה אסורה לו ואינה נחשבת כזקוקתו, הרי בייבמו את אחותה אינו פוגע באחות זקוקתו, ואם כן כשהאחת אסורה עליו איסור מצוה, למרות שאיננו איסור חמור כל כך, יהיה זה כמו איסור ערוה \u0003ותתייבם\u0004 אחותה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא.","ושואלים: \u0003ו\u0004באמת, מדוע לא \u0003תתייבם?\u0004 ומשיבים: \u0003כיון דמדאורייתא רמיא קמיה\u0004 \u0005[שמן התורה\u0006 היא \u0005מוטלת לפניו\u0006 לייבום\u0005],\u0006 אם כן אסור באחותה, כי בכך \u0003קא פגע\u0004 \u0005[הוא פוגע]\u0006 \u0003באחות זקוקתו.\u0004 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003משום מצוה\u0004 של ייבום \u0003עבוד רבנן\u0004 \u0005[עשו חכמים]\u0006 וביטלו את גזירתם באחות זקוקה כשאחת מהן היא אסורה איסור מצוה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שגם בזה לא ביטלו.","שנינו במשנה שאם \u0003היתה אחת מהן\u0004 אסורה לאח זה איסור ערוה, והשניה אסורה לשני איסור ערוה — שניהם רשאים לייבם את הנשים המותרות להם. ושואלים: \u0003הא תו\u0004 \u0005[זו עוד]\u0006 \u0003למה לי,\u0004 הלא \u0003היינו הך\u0004 \u0005[היא זו]\u0006 שאמרנו שאם נפלו שתי אחיות, ואחת מהן אסורה איסור ערוה לאחד האחים — רשאי אח זה לייבם את השניה, אף שאחיו, היבם השני, אסור בשתיהן. ואם למדנו שמותר לייבם את האחות שאינה איסור ערוה, \u0003מה לי לחד\u0004 \u0005[ל\u0006אח \u0005אחד]\u0006 \u0003ומה לי לתרי\u0004 \u0005[לשניים]\u0006 שהזדמן לפניהם מקרה כזה, ששניהם מותרים?!","ומשיבים: \u0003צריכא\u0004 \u0005[נצרך\u0006 הדבר\u0005]\u0006 להיאמר, \u0003דאי אשמועינן התם\u0004 \u0005[שאם היה משמיע לנו\u0006 רק \u0005שם],\u0006 היינו אומרים: \u0003משום דאיכא\u0004 \u0005[שיש]\u0006 אח \u0003שני\u0004 שאסור בשתיהן \u0003דמוכח\u0004 \u0005[שמוכיח]\u0006 ומראה בכך לבריות שיש איסור באחות זקוקתו, ולכן התירו לאחד מהם, \u0003אבל הכא דליכא\u0004 \u0005[כאן שאין]\u0006 אח \u0003שני דקא מוכח\u0004 \u0005[שמוכיח]\u0006 דבר זה, שהרי שניהם מייבמים כדרכם, והרואה יבוא להקל בכל אחות זקוקה כשאין האחרת איסור ערוה לו, ואם כן \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יתירו חכמים.","\u0003ו\u0004כן אפשר לומר להיפך: \u0003אי אשמועינן הכא\u0004 \u0005[אם היה משמיע לנו כאן]\u0006 בלבד, הייתי אומר: \u0003אדרבא\u0004 \u0005[להיפך],\u0006 \u0003תרווייהו מוכחי אהדדי\u0004 \u0005[שניהם מוכיחים זה על זה]\u0006 שהרי כל אחד מן האחים נושא יבמה אחת דווקא את זו שאיננה קרובתו, \u0003אבל אידך\u0004 \u0005[\u0006במקרה \u0005אחר]\u0006 שאחד יכול לייבם ולשני אסורות שתיהן — \u0003לא\u0004 נתיר גם לראשון, על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 ההלכה שתיאמר בשני המקרים.","שנינו במשנה, שאם כל אחת משתי האחיות היתה אסורה איסור ערוה לאחד מן האחים — האסורה לראשון מותרת לשני והאסורה לשני מותרת לראשון, והוסיפה על כך המשנה: \u0003זו היא שאמרו\u0004 אחותה כשהיא יבמתה או חולצת או מתייבמת. ושואלים: \u0003\"זו היא\" למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 בא הביטוי \"זו היא\"? ומשיבים: \u0003למעוטי\u0004 \u0005[למעט]\u0006 כאשר יש \u0003איסור מצוה לזה ואיסור מצוה לזה,\u0004 שאף שכל אחת מהן אסורה על אח אחר משום איסור מצוה — לא הותר לשניהם לייבם את המותרת להם.","ושואלים: \u0003הא תו\u0004 \u0005[זו עוד]\u0006 \u0003למה לי,\u0004 הלא \u0003היינו הך\u0004 \u0005[היא זו]\u0006 שלמדנו כבר, שאם היתה אחת האחיות אסורה ליבם איסור מצוה — אסור בשתיהן, ו\u0003מה לי לחד\u0004 \u0005[\u0006כשנפלה \u0005ל\u0006פני \u0005אחד],\u0006 \u0003מה לי לתרי\u0004 \u0005[לשניים]?!\u0006","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כי לא אמרינן אוקי\u0004 \u0005[כאשר אין אנו אומרים העמד]\u0006 \u0003איסור מצוה במקום איסור ערוה\u0004 להתיר את האחות השניה — זה רק \u0003היכא דאיכא למיגזר\u0004 \u0005[היכן שיש לגזור]\u0006 \u0003משום\u0004 אח \u0003שני,\u0004 שהרי לשני אסורות שתיהן \u0003אבל היכא דליכא למיגזר\u0004 \u0005[אבל היכן שאין לגזור]\u0006 \u0003משום שני,\u0004 שהרי גם לשני מותרת היבמה האחרת, \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003להאי אוקימנא\u0004 \u0005[\u0006ש\u0005ל\u0006אח \u0005זה אנו מעמידים]\u0006 ומחזקים \u0003איסור מצוה במקום איסור ערוה, ולהאי\u0004 \u0005[ול\u0006אח \u0005זה]\u0006 \u0003אוקימנא\u0004 \u0005[העמדנו]\u0006 \u0003איסור מצוה במקום איסור ערוה, ולייבמו\u0004 \u0005[ושייבמו]\u0006 שני האחים, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא.","אגב הלכה זו, \u0003אמר רב יהודה אמר רב, וכן תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא\u0004 בברייתא: \u0003ב\u0004כל העריות \u0003כולן\u0004 שנמנו במשנה הראשונה שבמסכת \u0003אני קורא בהן,\u0004 כלומר, אפשר שייוצר מצב שתפולנה לייבום שתי אחיות שהיו נשואות לשני אחים, ושכל אחת מהן תהא אסורה משום ערוה לאחד האחים הנותרים, ואז היבמה \u0003האסורה לזה מותרת לזה, ואחותה כשהיא יבמתה או חולצת או מתייבמת.\u0004","\u0003ורב יהודה מתרגם\u0004 (היה מסביר), כי לדעתו אפשר להעמיד כלל זה רק \u0003מחמותו ואילך,\u0004 שבאלה אפשר שיתקיימו הדברים הללו, \u0003אבל שיתא בבי דרישא\u0004 \u0005[\u0006ב\u0005ששת השערים,\u0006 המקרים \u0005ש\u0006ב\u0005התחלה],\u0006 שהן: בתו ובת אשתו וצאצאיהן — \u0003לא.\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם] —\u0006 \u0003כיון\u0004 שהמצב ששתי הנשים הנופלות לייבום תהיינה גם אחיות אחת של השניה וגם בנות של שני אחים, אינו יכול להיות אלא באופן ש\u0003בתו\u0004 זו אינה מן הנישואין אלא רק \u0003באונסין הוא דמשכחת לה\u0004 \u0005[שאתה\u0006 יכול \u0005למצוא אותה],\u0006 אבל \u0003ב\u0004מקרה של \u0003נשואין לא משכחת לה\u0004 \u0005[אין אתה יכול למצוא אותה],\u0006 משום שאם אח אחד נשא אשה והוליד ממנה בת, הרי אסורה אשה זו (שהיא אשת אח שיש לו בנים) לאחיו, ואם כן לא יתכן שיוליד אח אחר בת מאותה אשה, ואינן אחיות.","ודבר זה יכול להיות רק באנוסה, שאנס אח אחד אשה והוליד ממנה בת (ובאופן כזה אין אשה זו אסורה לאחיו), ואף אחיו אנס אותה והוליד אף לו ממנה בת, ושתי הבנות האלה נישאו לשני האחים האחרים, ומתו, ונפלו הבנות־האחיות לפני אבותיהן לייבום, ולדעתו, \u0003בנשואין קמיירי\u0004 \u0005[עוסקת]\u0006 המשנה, \u0003באונסין לא קא מיירי\u0004 \u0005[אינה עוסקת].\u0006","\u0003ואביי מתרגם\u0004 (היה מסביר) שהמשנה מדברת \u0003אף\u0004 ב\u0003בתו\u0004 ה\u0003באה מאנוסתו,\u0004 כי \u0003כיון דאשכוחי משכחת לה\u0004 \u0005[שאתה\u0006 יכול \u0005למצוא\u0006 את האפשרות \u0005הזו]\u0006 — לכן \u0003אי בעיא\u0004 \u0005[אם רצונך]\u0006 — \u0003באונסין תיהוי\u0004 \u0005[תהיה]\u0006 המשנה עוסקת, \u0003אי בעיא\u0004 \u0005[אם רצונך]\u0006 — \u0003בנשואין תהוי\u0004 \u0005[תהיה]\u0006 המשנה עוסקת, שאף שאנו מנסים להסביר את הדברים בנישואין, אבל אם אי אפשר — מסבירים גם על ידי אונסים. \u0003אבל אשת אחיו שלא היה בעולמו —\u0004 גם לדעת אביי \u0003לא,\u0004 אי אפשר לכלול בכלל זה, \u0003כיון\u0004 שהמצב ששתי אחיות תפולנה לפני שני יבמים וכל אחת מהן תהיה אשת אחיו שלא היה בעולמו הוא תלוי במחלוקת, \u0003דאליבא\u0004 \u0005[ש\u0006רק \u0005לפי שיטת]\u0006 \u0003ר' שמעון הוא דמשכחת לה\u0004 \u0005[שאתה מוצא אותה]\u0006 ו\u0003אליבא\u0004 \u0005[ולפי שיטת]\u0006 \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003לא משכחת לה\u0004 \u0005[אינך\u0006 יכול \u0005למצוא אותה]\u0006 לעולם — \u0003בפלוגתא לא קמיירי\u0004 \u0005[ב\u0006דבר השנוי \u0005במחלוקת אינו עוסק]\u0006 ר' חייא, שקבע כלל זה.","\u0003ורב ספרא מתרגם\u0004 (מסביר) ומונה פה \u0003אף\u0004 את \u0003אשת אחיו שלא היה בעולמו, ומשכחת לה\u0004 \u0005[ואתה\u0006 יכול \u0005למצוא אותה]\u0006 את האפשרות הזו \u0003בשיתא אחי\u0004 \u0005[בששה אחים]\u0006 \u0003ואליבא\u0004 \u0005[ולשיטת]\u0006 \u0003ר' שמעון. וסימניך\u0004 וכסימן לדבריו, כיצד יתכן הדבר, הוא: \u0003מת נולד וייבם, מת נולד וייבם.\u0004","כיצד? כגון שהיו שני אחים \u0003ראובן ושמעון,\u0004 שהיו \u0003נשואין\u0004 ל\u0003שתי אחיות,\u0004 והיו להם אחים \u0003לוי ויהודה\u0004 שהיו \u0003נשואין\u0004 ל\u0003שתי נכריות\u0004 (נשים זרות זו לזו). \u0003מת ראובן,\u0004 ולאחר מכן \u0003נולד יששכר, וייבם לוי\u0004 את אשת ראובן, ואחר כך \u0003מת שמעון\u0004 ולאחר שמת \u0003נולד זבולן, וייבם יהודה\u0004 את אשת שמעון. אחר כך \u0003מתו לוי ויהודה בלא בנים ונפלו להו\u0004 \u0005[להן]\u0006 שתי האחיות הללו \u0003קמי\u0004 \u0005[לפני]\u0006 \u0003יששכר וזבולן.\u0004","ומעתה זו שהיתה קודם לכן אשתו של ראובן \u0003האסורה לזה\u0004 ליששכר, שהרי היא אשת אחיו שלא היה בעולמו, אבל \u0003מותרת לזה\u0004 לזבולון. שהרי כאשר נולד זבולון, היתה אשה זו כבר אשתו של לוי שהיה בעולמו. ולדעת ר' שמעון אין מתחשבים בכך שהיא היתה קודם אשת ראובן שלא היה בעולמו, אלא בצד המעשי, שבשעה שנולד היתה היא נשואה. \u0003ו\u0004כן \u0003האסורה לזה\u0004 — \u0003מותרת לזה,\u0004 שזו שהיתה קודם אשת שמעון שהיא אסורה לזבולון משום אשת אחיו שלא היה בעולמו, הלא מותרת ליששכר שכן היתה בעולמו. \u0003ו\u0004נמצא הכלל של אסורה לזה מותרת לזה ב\u0003אחותה שהיא יבמתה.\u0004","ושואלים: \u0003למה לי\u0004 להעמיד במצב זה כאשר \u0003ייבם יהודה? בלא ייבם יהודה נמי משכחת לה\u0004 \u0005[גם כן אתה\u0006 יכול \u0005למצוא אותה]\u0006 אפשרות, ואפשר לתאר מצב כגון זה גם בחמישה אחים בלבד, בלא יהודה. שראובן ושמעון היו נשואים לשתי אחיות, מת ראובן ונולד יששכר וייבם לוי את אשת ראובן, ומת שמעון ונולד זבולון, הרי אם מת לוי אחר כך, נמצא שאשת לוי אסורה ליששכר משום שהיתה עבורו אשת ראובן שלא היה בעולמו, אבל מותרת לזבולון, שעבורו היתה כבר אשת לוי שהיה בעולמו ואשת שמעון אסורה לזבולון ומותרת ליששכר!","ומשיבים: \u0003משום צרה,\u0004 כדי שאפשר יהיה להחיל כלל זה לא רק בהן אלא גם בצרותיהן, שלוי ויהודה היו נשואים לפני כן לשתי אחיות, שנעשו צרות לאשת אחיו שלא היה בעולמו. ושואלים: \u0003הא תינח\u0004 \u0005[זה נוח],\u0006 כדי להביא כאן רק \u0003צרה\u0004 עצמה, אבל \u0003צרה\u0004 של \u0003צרה מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 איך אתה יכול להסביר? כי אם רוצים לכלול את כל הפרטים שבמשנה בתוך כללו של ר' חייא, צריך לדון לא רק בצרותיהן, אלא גם בצרות צרותיהן האמורות במשנה!","ומשיבים: לשם כך צריך להוסיף \u0003כגון דהדר ויבמינהו נמי\u0004 \u0005[שחזרו ויבמו\u0006 את הנשים הללו \u0005גם כן]\u0006 \u0003גד ואשר,\u0004 שהיו מתחילה עוד שני אחים והם ייבמו תחילה את נשי לוי ויהודה (שכל אחד מהם ייבם אחת מנשי ראובן ושמעון), וחזרו ונפלו נשי גד ואשר (שהן צרות צרותיהן של נשי ראובן ושמעון) לפני יששכר וזבולון.","היו \u0003שלשה אחין, שנים מהן נשואין\u0004 לקרובות, כגון \u0003שתי אחיות, או אשה ובתה, או אשה ובת בתה, או אשה ובת בנה,\u0004 ומתו שני האחים בעלי הקרובות ונפלו שתיהן לפני האח השלישי — \u0003הרי\u0004 שתי נשים \u0003אלו חולצות ולא מתייבמות\u0004 משום שכל אחת מהן הינה קרובת זקוקתו. \u0003ור' שמעון פוטר\u0004 את שתיהן אפילו מן החליצה.","\u0003היתה אחת מהן אסורה עליו\u0004 על האח השלישי \u0003איסור ערוה\u0004 שהוא היה קרוב לאחת מהן — \u0003אסור בה\u0004 איסור גמור, \u0003ומותר באחותה\u0004 אף בייבום, מאחר שזו האסורה עליו שוב אינה נחשבת כזקוקתו, ואין כאן אלא אשה אחת הנופלת לפניו לייבום. אולם אם היתה אחת מהם אסורה על האחד \u0003איסור מצוה או איסור קדושה — חולצות ולא מתייבמות.\u0004 משום שאין איסורים אלה מבטלים לגמרי את זיקת הייבום.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' שמעון פוטר בשתיהן מן החליצה ומן היבום, שנאמר: \"ואשה אל אחותה לא תקח לצרר\"\u0004 (ויקרא יח, יח), לומר: \u0003בשעה שנעשו צרות זו לזו,\u0004 שיש מצב שהן עומדות להיות צרות זו לזו, שהרי שתיהן עומדות לייבום לפני אותו אדם — \u0003לא יהא לך ליקוחין אפילו באחת מהן,\u0004 שלדעתו בשעת נפילה כבר פטורות הן מן הייבום ומן החליצה, כמו שפטורה הערוה עצמה מן הייבום והחליצה.","שנינו במשנה שאם \u0003היתה אחת מהן\u0004 אסורה עליו איסור ערוה —אסור בה ומותר באחותה. ושואלים: \u0003הא תו\u0004 \u0005[זו עוד]\u0006 \u0003למה לי\u0004 במשנה זו, הלא \u0003היינו הך\u0004 \u0005[היא זאת]\u0006 ששנינו במשנה הקודמת!","ומשיבים: \u0003ל\u0004דעת \u0003ר' שמעון איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להיאמר כאן שוב, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003הואיל ואמר ר' שמעון שתי אחיות לא חולצות ולא מתייבמות,\u0004 שעצם העובדה שהן עומדות להיות צרות זו לזו אוסרת את שתיהן, ואם כן \u0003לגזור\u0004 \u0005[שיגזור]\u0006 גם כאן, למרות שאחת מהם אסורה עליו, \u0003משום\u0004 שמא יבוא לייבם גם \u0003שתי אחיות דעלמא\u0004 \u0005[בכלל]\u0006 שנפלו לייבום, על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף ר' שמעון אינו גוזר.","שנינו במשנה שאם היו אסורות \u0003איסור מצוה\u0004 או איסור קדושה — חולצות ולא מתייבמות."],["\u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' שמעון:\u0004 שבכל מקרה שיש אחות חלוצה — \u0003שתי\u0004 ה\u0003אחיות לא חולצות ולא מתייבמות,\u0004 וכאן הלא מדין התורה ראויות וזקוקות הן לייבום מדין תורה, ומכיון שכן, הריהי נחשבת כזקוקה, ולדעת ר' שמעון יש לפוטרה אף מן החליצה, ומדוע נאמר שחולצות ולא מתייבמות!","ומשיבים: \u0003גזירה\u0004 היא \u0003משום איסור מצוה דעלמא\u0004 \u0005[בכלל],\u0006 שאם לא היו חולצים להן, יש חשש שיחשבו שנפטרו מחליצה לא משום שהן אחיות אלא משום איסור מצוה, ויחשבו שבאיסור מצוה אין חליצה, ולכן גזרו שיחלצו.","ושואלים: \u0003הא תינח איהי\u0004 \u0005[זה נוח\u0006 ב\u0005זו],\u0006 באחת מהן, שראוי שיחלצו לה כדי להראות שיש חליצה באיסור מצוה, אבל \u0003אחותה מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 על כך שאף היא נזקקת לחליצה? ומשיבים: \u0003גזירה\u0004 גם ב\u0003אחותה משום לתא דידה\u0004 \u0005[הגרר שלה].\u0006","ושואלים: אם כך, שאנו גוזרים מפני חשש ואומרים שמוטב שיחלצו, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003גבי\u0004 איסור \u0003ערוה לא גזרינן\u0004 \u0005[אין אנו גוזרים]\u0006 לדעת ר' שמעון שתצטרך הערוה חליצה משום אחותה, אלא פוטרים אותה לגמרי? ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 הוא ענין \u0003ערוה דמגמר גמירי לה אינשי\u0004 \u0005[שלומדים אותה אנשים],\u0006 שהרי איסור ערוה מפורש בתורה והכל יודעים אותו, \u0003וקלא אית\u0004 \u0005[וקול יש]\u0006 \u0003לה,\u0004 ואין לחשוש שיבואו לטעות ולהחליף אותה ביבמה סתם — מה שאין כן באיסור מצוה שאינו מפורש בתורה ואין הכל יודעים אותו.","היו \u0003שלשה אחין, שנים\u0004 מהם \u0003נשואים\u0004 ל\u0003שתי אחיות, ואחד מופנה\u0004 (רווק). \u0003מת אחד מבעלי\u0004 ה\u0003אחיות\u0004 בלא בנים והשאיר אשה, \u0003ועשה בה מופנה מאמר.\u0004 כלומר, קידש אותה, והוא הקרוי \"מאמר יבמים\", אבל לא בא עליה עדיין, \u0003ואחר כך\u0004 לפני שהספיק לכנוס אותה \u0003מת אחיו השני,\u0004 ונפלה לפניו לייבום גם אשת האח השני שהיא אחותה של זו שקידש —","\u0003בית שמאי אומרים: אשתו עמו,\u0004 שאותה יבמה שקידש הרי היא כאשתו, \u0003והלזו,\u0004 האחרת, \u0003תצא\u0004 ותיפטר מייבום \u0003משום אחות אשה. ובית הלל אומרים:\u0004 כיון שעדיין לא כנס גם את הראשונה — שתיהן זקוקות לו בזיקת ייבום. ולכן \u0003מוציא את אשתו,\u0004 כלומר, את זו שעשה בה מאמר, \u0003בגט,\u0004 לבטל את המאמר שעשה בה, \u0003ובחליצה\u0004 לבטל את קשר הזיקה. \u0003ו\u0004מוציא גם את \u0003אשת אחיו\u0004 השני \u0003בחליצה.\u0004 ומעירים, \u0003זו היא שאמרו: אוי לו על אשתו, ואוי לו על אשת אחיו.\u0004 שהרי בגלל צירוף המאורעות מאבד את שתיהן.","שואלים: \u0003\"זו היא\"\u0004 שאמרו במשנה, שהיא לשון דיוק וצמצום, \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 היא באה? ומשיבים: \u0003למעוטי הך\u0004 \u0005[למעט\u0006 את \u0005זו]\u0006 של \u0003ר' יהושע\u0004 (להלן בדף קט, א) במי שהיה נשוי לקטנה, ונפלה לפניו אחותה לייבום, שסבור ר' יהושע שצריך הלה להוציא את שתיהן, ואמר שם: אוי לו על אשתו אוי לו על אשת אחיו. וממשנתנו נלמד \u0003דלא עבדינן כוותיה\u0004 \u0005[שאין אנו עושים כמותו\u0006 כשיטתו\u0005],\u0006 \u0003אלא אי\u0004 \u0005[או]\u0006 \u0003כ\u0004שיטת \u0003רבן גמליאל, אי\u0004 \u0005[או]\u0006 \u0003כ\u0004שיטת \u0003ר' אלעזר\u0004 שם, שמוצאים בכגון זה דרך שיוכל לשאת לפחות את אחת מהן.","לגופם של הדברים, לכאורה אפשר היה ללמוד שלדעת בית שמאי יש למאמר תוקף בייבום, אולם \u0003אמר ר' אלעזר: לא תימא\u0004 \u0005[אל תאמר]\u0006 ש\u0003מאמר ל\u0004דעת \u0003בית שמאי קונה קנין גמור\u0004 והיא נעשית כאשתו ממש עד כדי כך \u0003דאי בעי לאפוקי, סגי לה בגיטא\u0004 \u0005[שאם\u0006 הוא \u0005רוצה להוציא\u0006 אותה, \u0005די לה בגט]\u0006 ואינה צריכה חליצה, \u0003אלא מאמר לבית שמאי אינו קונה אלא\u0004 כדי \u0003לדחות בצרה בלבד,\u0004 שכוח המאמר מספיק כדי שהצרה, כלומר האחות שנפלה גם היא לפניו, תידחה ולא יצטרך לחלוץ לה.","\u0003אמר ר' אבין: אף אנן נמי תנינא\u0004 \u0005[אף אנו גם כן שנינו]\u0006 הוכחה לכך שמאמר איננו קונה קנין גמור אף לדעת בית שמאי, שכן שנינו במשנה בראש הפרק, שכאשר נפלו שתי אחיות יבמות לפני שני אחים, אם קדמו האחים וכנסו, \u0003בית שמאי אומרים: יקיימו,\u0004 ומדיוק הלשון אפשר להבין: \u0003יקיימו — אין\u0004 \u0005[כן],\u0006 שאם כבר כנסו — יקיימו, אבל \u0003לכתחלה — לא,\u0004 שאינם רשאים לשאת אותן, בגלל האיסור של אחות זקוקתו."],["\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003מאמר לבית שמאי קונה קנין גמור\u0004 ביבמה, הרי יש דרך לפתור ענין זה לכתחילה, דהיינו שאח \u0003זה יעשה מאמר ויקנה ו\u0004אח \u0003זה יעשה מאמר ויקנה\u0004 כי מכיון שעשיית המאמר אין בה איסור כלל — אין כאן חשש של האיסור הקיים בכונס את אחות זקוקתו, שהרי אינו בא עליה אלא רק מקדש אותה, ולאחר שקידש נדחית ממנו הזיקה של אחותה ויוכל לבוא עליה.","ומקשים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 רוצה אתה לומר, שלבית שמאי אף שהמאמר אינו קונה ביבמה קנין גמור, מכל מקום \u0003דוחה\u0004 את הצרה \u0003דחייה גמורה\u0004 ויכול איפוא לשאת את בעלת המאמר — אם כן עדיין קיימת אפשרות אחרת: \u0003זה יעשה מאמר\u0004 באחות אחת \u0003וידחה\u0004 את צרתה, \u0003וזה יעשה מאמר וידחה,\u0004 ואם היתה דרך זו מועילה בשלימות לדעת בית שמאי, הרי אפשר היה להשתמש בה גם במקרה הראשון.","\u0003אלא מאי אית לך למימר\u0004 \u0005[מה יש לך לומר]:\u0006 שאין זו תקנה גמורה כי \u0003מאמר דהתירא\u0004 \u0005[ש\u0006נעשה ב\u0005היתר],\u0006 שאין בו איסור קרובת זקוקה — \u0003דחי\u0004 \u0005[דוחה]\u0006 את הצרה דחייה גמורה, ואילו מאמר \u0003דאיסורא\u0004 \u0005[של איסור]\u0006 \u0003לא דחי\u0004 \u0005[אינו דוחה],\u0006 \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 עליך לומר כי \u0003מאמר, אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003מאמר קונה קנין גמור\u0004 כנישואין, אין לכך סתירה ממה שלא השתמשו בית שמאי בדרך זו, כי גם שם אפשר לומר: \u0003מאמר דהתירא קני\u0004 \u0005[של היתר קונה]\u0006 קנין גמור, אבל מאמר \u0003דאיסורא\u0004 \u0005[\u0006שיש בו איזה סרך \u0005של איסור]\u0006 \u0003לא קני\u0004 \u0005[אינו קונה]\u0006 ואין להוכיח מכאן.","\u0003רב אשי מתני הכי\u0004 \u0005[היה שונה כך]\u0006 את הסוגיה הזו, ובנוסח אחר: \u0003אמר ר' אלעזר: לא תימא\u0004 \u0005[אל תאמר]\u0006 ש\u0003מאמר לבית שמאי דחי\u0004 \u0005[דוחה]\u0006 \u0003דחייה גמורה, וצרתה\u0004 של זו שעשה בה מאמר, \u0003חליצה נמי לא בעיא\u0004 \u0005[גם כן אינה צריכה],\u0006 \u0003אלא דוחה ומשייר הוא.\u0004 כלומר, הוא דוחה את הצרה לענין שאינו חייב לגרש את זו שקידש, אבל עדיין הוא משייר זיקת ייבום כדי לחייב לחלוץ לה.","\u0003אמר ר' אבין: אף אנן נמי תנינא\u0004 \u0005[אף אנו גם כן שנינו]\u0006 מעין זו, במשנה, ששנינו בה: \u0003בית שמאי אומרים יקיימו.\u0004 ונדייק: \u0003יקיימו — אין\u0004 \u0005[כן],\u0006 אבל \u0003לכתחלה\u0004 לשאת אותן — \u0003לא. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003מאמר לבית שמאי דוחה דחייה גמורה,\u0004 אם כן \u0003זה יעשה מאמר וידחה\u0004 את אחותה מעליו, ואחר כך ישא את זו, \u0003וזה יעשה מאמר וידחה!\u0004 אלא ודאי אינה דוחה דחייה גמורה ומאחר ומוטלת לפניו לחליצה, הריהי זקוקתו ואוסרת את השניה עליו! כנגד הוכחה זו טוענים: \u0003ואלא הא קתני\u0004 \u0005[זו\u0006 ש\u0005שנינו]\u0006 במשנתנו \u0003בית שמאי אומרים: אשתו עמו, והלזו,\u0004 השניה, \u0003תצא משום אחות אשה.\u0004 משמע שאיננו צריך לחלוץ לה, ויוצאת אף בלא חליצה, ומכאן שזו דחייה גמורה!","\u0003אלא\u0004 יש לומר כך: ודאי שהיא דוחה דחייה גמורה, \u0003יבמה דחזיא לכולהו\u0004 \u0005[שראויה לכל\u0006 הדברים כולם\u0005],\u0006 שהיא ראויה לייבום גמור כמו במקרה של משנתנו שזו שעשה בה מאמר נפלה ראשונה והיתה ראויה לייבום — \u0003חזיא\u0004 \u0005[ראויה]\u0006 גם \u0003למקצתה\u0004 כשאינו מייבם אותה אלא עושה בה רק מאמר, ויש במאמר כוח לדחות את הצרה לגמרי, ואילו \u0003יבמה דלא חזיא לכולהו\u0004 \u0005[שאיננה ראויה לכולם],\u0006 שהרי במקרה שמדובר בו במשנה הראשונה שנפלו שתיהן כאחת אינו רשאי לייבם, לכן גם \u0003לא חזיא למקצתה\u0004 \u0005[אינה ראויה למקצתה]\u0006 ואין המאמר קונה ואיננו דוחה לגמרי.","באותו נושא \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבה:\u0004 האם \u0003מאמר, ל\u0004דעת \u0003בית שמאי, נישואין\u0004 הוא ש\u0003עושה,\u0004 כלומר, שאנחנו רואים אותו כקשר נישואין גמור \u0003או אירוסין\u0004 הוא ש\u0003עושה\u0004 כמו כל קידושין אחרים? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: למאי הלכתא\u0004 \u0005[למה,\u0006 לענין איזו \u0005הלכה]\u0006 אתה שואל זאת?","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ליורשה\u0004 כשמתה, \u0003וליטמא לה\u0004 אם הוא כהן או \u0003להפר\u0004 את \u0003נדריה\u0004 שהם זכויות וחובות הבאות רק על ידי נישואין, \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי \u0003ארוסה בעלמא\u0004 \u0005[בכלל]\u0006 שהיא ארוסה גמורה, מדין תורה, \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא\u0004 בברייתא: \u0003אשתו ארוסה — לא אונן\u0004 שאינו מתאבל עליה אבילות גמורה ביום מותה, \u0003ולא מטמא לה\u0004 במותה. \u0003וכן היא לא אוננת ולא\u0004 מחוייבת להיות \u0003מטמאת לו.\u0004 אם \u0003מתה — אינו יורשה,\u0004 אם \u0003מת הוא — גובה כתובתה.\u0004 ואם גם ארוסה גמורה איננה נחשבת כאשתו לעניינים אלה, הרי כאשר \u0003עבד\u0004 \u0005[עשה]\u0006 \u0003בה מאמר מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר שאיננו יורשה ואינו מיטמא לה? ואין איפוא כל מקום לשאלה בענין זה.","\u0003ואלא\u0004 יש לומר כי השאלה היא \u0003לענין מסירה לחופה, מאי\u0004 \u0005[מה\u0006 דינה\u0005]?\u0006 האם יש צורך גם שיעשה חופה כדרך שכונס ארוסה אחרת, או לא? וצדדי השאלה, האם \u0003נישואין עושה\u0004 המאמר, \u0003ולא בעיא\u0004 \u0005[ואינה צריכה]\u0006 עוד \u0003מסירה לחופה, או דלמא\u0004 \u0005[שמא]\u0006 רק \u0003אירוסין עושה\u0004 המאמר, \u0003ובעיא\u0004 \u0005[וצריכה]\u0006 \u0003מסירה לחופה?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: אם כן הוא — זו איננה שאלה: \u0003השתא\u0004 \u0005[עכשיו],\u0006 הרי אם \u0003לא עבד\u0004 \u0005[עשה]\u0006 \u0003בה מאמר\u0004 כלל, הלא \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"יבמה יבא עליה\"\u0004 (דברים כה, ה), ולמדנו שאפילו \u0003בעל כרחה —\u0004 אם \u0003עבד\u0004 \u0005[עשה]\u0006 \u0003בה מאמר מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר שיכול לבוא עליה, ואיננו זקוק לחופה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003שאני אומר: כל העושה מאמר ביבמתו פרחה ממנו זיקת יבמין\u0004 שאינו נחשב עוד כיבם, ודיני ייבום אינם חלים עוד עליו \u0003וחלה עליה\u0004 \u0005[עליו]\u0006 \u0003זיקת אירוסין\u0004 רגילה. ולכן יש מקום לשאלה אם גם לענין חופה הרי זו כזיקת אירוסין ממש, או שמא יש בה עדיין דין ייבום, שאיננה זקוקה לחופה כדי להיכנס לנישואין, ונחשבת כיבמה רגילה, שאין המאמר גורע מכח הייבום. ואם כן \u0003מאי\u0004 \u0005[מה]\u0006 ההלכה בזה?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה לכך, ממה ששנינו: \u0003שומרת יבם,\u0004 אשה הזקוקה לייבום, \u0003בין\u0004 שהיתה ממתינה ל\u0003יבם אחד\u0004 שהיה רק אח אחד למת, \u0003בין\u0004 שהיתה ממתינה ל\u0003שני יבמין,\u0004 מהו לענין הפרת נדרים? \u0003ר' אליעזר אומר: יפר.\u0004 שהיבם יכול להפר את נדריה כשם שבעלה מפר. \u0003ר' יהושע אומר:\u0004 שזה נכון רק כשהיתה זקוקה \u0003ל\u0004יבם \u0003אחד ולא לשנים. ר' עקיבא אומר: לא לאחד ולא לשנים\u0004 אפשרות להפר נדריה.","\u0003והוינן\u0004 \u0005[והיינו\u0006 עוסקים\u0005]\u0006 \u0003בה,\u0004 בשאלה זו, בפירוש השיטות: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ר' עקיבא\u0004 הוא \u0003סבר: אין זיקה אפילו לחד\u0004 \u0005[לאחד],\u0006 שלדעתו אין הזיקה יוצרת קירבה כלל אפילו כשיש רק יבם אחד. \u0003לר' יהושע\u0004 צריך לומר \u0003לחד\u0004 \u0005[\u0006לגבי יבם \u0005אחד]\u0006 \u0003יש זיקה\u0004 שכיון שודאי זקוקה לו היא נחשבת כעין אשתו, \u0003לתרי\u0004 \u0005[לשניים]\u0006 \u0003אין זיקה,\u0004 כיון שלא ברור מי הוא זה שייבם אותה. \u0003אלא לר' אליעזר, נהי נמי דקסבר\u0004 \u0005[אם אמנם שהוא סובר]\u0006 \u0003יש זיקה, בשלמא לחד\u0004 \u0005[נניח\u0006 שזקוקה \u0005ל\u0006יבם \u0005אחד]\u0006 מובן שהוא \u0003מיפר, אלא לתרי אמאי\u0004 \u0005[לשניים מדוע]?\u0006 הרי לא ברור למי מן האחים תתקשר האשה!","\u0003ואמר ר' אמי בר אהבה: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים] —\u0006 \u0003כגון דעבד\u0004 \u0005[שעשה]\u0006 \u0003בה\u0004 אחד מהם \u0003מאמר ו\u0004כשיטת \u0003בית שמאי היא,\u0004 ש\u0003אמר: מאמר קונה קנין גמור.\u0004","ומכאן נפתור את שאלתנו, \u0003אי אמרת בשלמא\u0004 \u0005[אם אתה אומר נניח]\u0006 שהמאמר \u0003נישואין עושה — משום הכי\u0004 \u0005[כך]\u0006 \u0003מיפר\u0004 היבם את הנדרים כדרך שהבעל עושה. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שהמאמר רק \u0003אירוסין עושה — היכי מצי מיפר\u0004 \u0005[איך יכול להפר]?\u0006 והרי גם ארוס גמור מדין תורה אינו מפר נדרי ארוסתו לבדו, שכן \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003נערה המאורסה — אביה ובעלה\u0004 יחד \u0003מפירים נדריה.\u0004 וכיצד יוכל היבם להפר לבדו, אם אינו נחשב כבעל? \u0003אמר רב נחמן בר יצחק\u0004 אפשר לדחות ולפרש: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003מיפר — מיפר בשותפות\u0004 עם האב.","ושואלים: \u0003ול\u0004דעת \u0003ר' אלעזר,\u0004 ש\u0003אמר: מאמר\u0004 אף \u0003לבית שמאי אינו קונה\u0004 קנין גמור, ואינו מועיל \u0003אלא לדחות לצרה בלבד,\u0004 ואינו קונה קנין גמור, אם כן \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003מיפר\u0004 אפילו \u0003בשותפות?\u0004 ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003ר' אלעזר: אימר דאמרי אנא\u0004 \u0005[אמור\u0006 שמה \u0005שאמרתי אני]\u0006 ש\u0003אינו קונה אלא לדחות לצרה בלבד,\u0004 לא היתה הכוונה לומר שאין במאמר כל קנין, אלא להדגיש ש\u0003לא סגי\u0004 \u0005[די]\u0006 \u0003לה בגיטא\u0004 \u0005[בגט]\u0006 \u0003אלא בעי נמי\u0004 \u0005[צריכה גם כן]\u0006 \u0003חליצה,\u0004 אבל לענין שלא יוכל \u0003להפר נדריה מי אמרינן\u0004 \u0005[האם אמרנו]\u0006 שאין המאמר קונה בה כלל, שלא יוכל להפר נדריה לבד?","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003ר' אלעזר: ולרב נחמן בר יצחק מי ניחא\u0004 \u0005[האם נוח]\u0006 תירוץ זה, שאמר שהכוונה שיפרו האב והיבם יחד? \u0003מי קתני\u0004 \u0005[האם שנה\u0006 במשנה\u0005]\u0006 \u0003\"יפרו\"?\u0004 הלא \u0003\"יפר\" קתני\u0004 \u0005[שנה],\u0006 משמע שאין ההפרה נעשית בשותפות, אלא הוא מפר לבדו. \u0003אלא\u0004 יש להסביר את המשנה בדרך אחרת: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים] —\u0006 במקרה כזה שהיבם (בין כשעשה מאמר או לא עשה מאמר) לא רצה לא ליבם ולא לחלוץ, \u0003שעמדה\u0004 היבמה \u0003בדין\u0004 שיכפו אותו ליבם או לחלוץ, \u0003ופסקו לה מזונות משלו,\u0004 שכיון שהיא זקוקה לו ואינה יכולה להינשא לאחר, פסקו בית דין שיפרנסנה משלו,","\u0003ו\u0004כפי שאמר \u0003רב פנחס משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא.\u0004 ש\u0003אמר רב פנחס משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: כל הנודרת — על דעת בעלה היא נודרת,\u0004 שכיון שהיא תלויה בו בפרנסתה — אינה עושה דבר אלא מדעתו. וכיון שיבם זה מספק את מזונותיה של היבמה, יש לומר שגם נדריה הם על דעתו, ומטעם זה הוא יכול להפר את נדריה לבד. ומכאן אין איפוא הוכחה לגבי תוקפו של קנין המאמר."],["\u0003שלשה אחין, שנים מהם נשואים\u0004 ל\u0003שתי אחיות ואחד נשוי\u0004 ל\u0003נכרית\u0004 (אשה זרה להם), \u0003מת אחד מבעלי אחיות, וכנס\u0004 ה\u0003נשוי\u0004 ל\u0003נכרית את אשתו ומת\u0004 אחר כך גם הוא בלי בנים, ונפלו שתי הנשים לייבום לפני האח האחר הנותר — \u0003הראשונה\u0004 (זו שנפלה ראשונה לייבום) \u0003יוצאה משום אחות אשה\u0004 שהרי היא אחות אשתו של אח זה, \u0003ושניה\u0004 יוצאת \u0003משום צרתה\u0004 שכן היתה צרת האחות לאחר הייבום. אבל אם \u0003עשה בה\u0004 האח הנשוי נכרית רק \u0003מאמר,\u0004 ועדיין לא ייבם את האחות \u0003ומת — נכרית\u0004 שנעשתה על ידי המאמר כעין צרה לאחות — \u0003חולצת ולא מתייבמת\u0004.","מן ההלכה האחרונה במשנה מדייקים: \u0003טעמא דעבד\u0004 \u0005[הטעם,\u0006 דווקא \u0005שעשה]\u0006 \u0003בה\u0004 נשוי הנכרית \u0003מאמר\u0004 באחות, \u0003הא לא עבד\u0004 \u0005[הרי\u0006 אם \u0005לא עשה]\u0006 \u0003בה מאמר — נכרית יבומי נמי מייבמה\u0004 \u0005[\u0006היתה \u0005מתייבמת גם כן],\u0006 אף על פי שנעשתה צרת אחות אשה על ידי הזיקה. \u0003אמר רב נחמן: זאת אומרת אין זיקה,\u0004 שאין רואים את הזקוקה כנשואה, \u0003ואפילו\u0004 כשהזיקה היא \u0003בחד אחא\u0004 \u0005[באח אחד],\u0006 שהרי אחות זו שמת בעלה נפלה לייבום רק לפני האח הנשוי נכרית ולו בלבד היתה זקוקה.","היו \u0003שלשה אחים, שנים מהם נשואים\u0004 ל\u0003שתי אחיות, ואחד נשוי\u0004 ל\u0003נכרית. מת הנשוי\u0004 ל\u0003נכרית, וכנס אחד מבעלי\u0004 ה\u0003אחיות את אשתו, ומת\u0004 גם הוא בלי בנים — \u0003הראשונה,\u0004 כלומר, האחות — \u0003יוצאת\u0004 ונפטרת מייבום \u0003משום אחות אשה, ושניה,\u0004 הנכרית שייבם — יוצאת \u0003משום צרתה.\u0004 אבל אם \u0003עשה בה\u0004 בנכרית \u0003מאמר ומת — נכרית\u0004 זו \u0003חולצת ולא מתייבמת,\u0004 שהרי בגלל המאמר היא רק כעין צרת אחות אשה.","שואלים: \u0003הא תו\u0004 \u0005[\u0006משנה \u0005זו\u0006 ששנינו \u0005עוד,\u0006 שוב\u0005]\u0006 \u0003למה לי,\u0004 הלא \u0003היינו הך\u0004 \u0005[היא זו]\u0006 כמו המשנה הקודמת! ויתר על כן, הדין האמור בה נובע בפשטות מן הדין הקודם. \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003ומה התם\u0004 \u0005[שם]\u0006 ש\u0003אחות אשה הויא\u0004 \u0005[הריהי]\u0006 זו שנעשית \u0003צרה לנכרית\u0004 שהיא אשת האח מכבר, \u0003אמרת\u0004 \u0005[אומר אתה]\u0006 שה\u0003נכרית אסורה,\u0004 למרות שהערוה היא זו המצטרפת ונוספת, \u0003הכא\u0004 \u0005[כאן]\u0006 שה\u0003נכרית הויא\u0004 \u0005[היא]\u0006 הנעשית \u0003צרה לאחות אשה — לא כל שכן\u0004 שהיא פטורה משום צרה!","ומשיבים, שאכן משנה זו אינה צריכה, אלא כך נוצרה כפילות זו: ה\u0003תנא, הך תנא ברישא\u0004 \u0005[\u0006את \u0005זו,\u0006 את המשנה שלנו, \u0005שנה בתחילה]\u0006 \u0003והך חזיא להתירא ושריא\u0004 \u0005[ו\u0006את \u0005זו\u0006 הקודמת \u0005ראה אותה להיתר והתירה],\u0006 שסבר כי אם הערוה היא שנצטרפה לביתו של האיש — אינה אוסרת את אשתו הראשונה משום צרת ערוה. \u0003והדר חזיא לאיסורא\u0004 \u0005[וחזר\u0006 ו\u0005ראה\u0006 אותה \u0005לאיסור],\u0006 שהחליט שגם זו קרויה צרת ערוה ואסורה.","\u0003ואיידי דחביבה ליה אקדמה\u0004 \u0005[ומתוך ש\u0006היא \u0005חביבה לו,\u0006 משום שיש בה חידוש, \u0005הקדים אותה]\u0006 ושנה אותה בראש. ובאמת היה יכול עכשיו לוותר על המשנה שלנו, שאין בה חידוש ואפשר ללמוד אותה בקל וחומר מן הקודמת, אלא \u0003ומשנה לא זזה ממקומה.\u0004 כי מאחר שקבעו את המשנה בגירסה, לא מצאו לנחוץ למחוק אותה לגמרי, והיא נשארה במשנה למרות שאיננה נחוצה עוד.","היו \u0003שלשה אחין, שנים מהם נשואים\u0004 ל\u0003שתי אחיות ואחד נשוי\u0004 ל\u0003נכרית, מת אחד מבעלי אחיות, וכנס\u0004 ה\u0003נשוי\u0004 ל\u0003נכרית את אשתו, ומתה אשתו של\u0004 האח ה\u0003שני\u0004 (הנשוי לאחות), \u0003ואחר כך מת נשוי נכרית — הרי זו\u0004 האחות \u0003אסורה עליו,\u0004 על האח שנשאר, \u0003עולמית.\u0004 ואף שעכשיו איננה עוד אחות אשתו, שהרי אשתו כבר מתה ואחות אשתו לאחר מיתת אשתו מותרת, \u0003הואיל ונאסרה עליו\u0004 כבר \u0003שעה אחת,\u0004 שכאשר נפלה לייבום בראשונה (לפני שכנסה הנשוי נכרית) היתה אסורה לו משום אחות אשתו, הריהי נאסרת עליו לעולם ופוטרת את צרתה הנכרית.","\u0003אמר רב יהודה אמר רב\u0004 כלל בענין זה: \u0003כל יבמה שאין אני קורא בה בשעת נפילה \"יבמה יבא עליה\"\u0004 (דברים כה, ה), כלומר, שאין היבם יכול לייבם אותה, מחמת איסור — \u0003הרי היא\u0004 נעשית מאותו רגע \u0003כאשת אח שיש לה בנים, ואסורה\u0004 לו לעולם. ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 רב בכך? הלא \u0003תנינא\u0004 \u0005[שנינו]\u0006 דבר זה במשנתנו: \u0003הרי זו אסורה עליו עולמית, הואיל ונאסרה עליו שעה אחת!\u0004","ומשיבים: משום שאת המשנה אפשר היה להבין באופן אחר, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003לא איחזיא לה\u0004 \u0005[ראויה]\u0006 \u0003בנפילה ראשונה,\u0004 בפעם הראשונה שנפלה לפניו לייבום, שהרי כשמת בעלה הראשון היתה אסורה לזה משום אחות אשתו שאשתו מתה רק אחרי שייבם אותה אחיו, ואז נאסרה לעולם, \u0003אבל היכא דאיחזיא לה\u0004 \u0005[במקום שהיתה ראויה]\u0006 \u0003בנפילה ראשונה,\u0004 כשנפלה לפניו לייבום בראשונה שבטל בינתיים האיסור ממנה, כגון כשמתה אשתו לפני שאחיו ייבם אותה ונעשית ראויה לו, \u0003אימא תישתרי\u0004 \u0005[אמור\u0006 ש\u0005תהיה מותרת],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רב שאף אז אסורה עליו לעולם.","ומקשים: \u0003הא נמי תנינא\u0004 \u0005[זו גם כן שנינו],\u0006 שהרי נאמר במשנה להלן: \u0003שני אחין נשואים\u0004 ל\u0003שתי אחיות, מת אחד מהם, ואחר כך מתה אשתו של\u0004 ה\u0003שני — הרי זו אסורה עליו עולמית, הואיל ונאסרה עליו שעה אחת\u0004 כשנפלה לפניו והיתה אשתו שהיא אחותה עדיין בחיים!","ומשיבים: גם משם אי אפשר היה ללמוד הלכה כללית. \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003התם הוא דאידחי לה מהאי ביתא\u0004 \u0005[שם זו שנדחתה מבית זה],\u0006 מביתו של אדם זה, \u0003לגמרי,\u0004 שכיון שחובת הייבום חלה רק על האח הנותר, וכיון שנאסרה עליו משעת נפילה נפטרה לגמרי מחובת ייבום, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 במקרה של רב מדובר \u0003דלא אידחי לה מהאי ביתא\u0004 \u0005[שלא נדחתה מבית זה]\u0006 \u0003לגמרי,\u0004 שהרי עדיין זקוקה היא לייבום לאח אחר, ואם כן \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003מיגו דחזיא להאי\u0004 \u0005[מתוך ש\u0006היא \u0005ראויה לזה]\u0006 ה\u0003נשוי נכרית,\u0004 שהיא מותרת לו, \u0003חזיא נמי להאי\u0004 \u0005[ראויה גם כן לזה]\u0006 לאח השני, לאחר שמתה אשתו, שהרי לא נפטרה לגמרי מחובת ייבום — על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רב שבכל מקרה, כל שנאסרה שעה אחת, הרי היא אסורה עולמית.","\u0003שלשה אחים, שנים מהם נשואין\u0004 ל\u0003שתי אחיות, ואחד נשוי\u0004 ל\u0003נכרית. גירש אחד מבעלי\u0004 ה\u0003אחיות את אשתו, ומת\u0004 ה\u0003נשוי נכרית, וכנסה\u0004 (וייבמה) \u0003המגרש, ו\u0004אחר כך \u0003מת,\u0004 ונפלה אותה אשה לפני מי שעדיין הוא בעל האחות השניה — \u0003זו היא שאמרו: וכולן שמתו\u0004 הקרובות \u0003או נתגרשו — צרותיהן מותרות,\u0004 שהרי בשעה שנפלה לפניו לייבום כבר לא היתה זו הנכרית צרת אחות אשתו.","ומדייקים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003גירש\u0004 בעל האחות את אשתו, \u0003ואחר כך מת\u0004 הנשוי נכרית וכנס אחיו את היבמה, \u0003אבל\u0004 אם \u0003מת\u0004 האח הראשון קודם, \u0003ואחר כך גירש\u0004 בעל האחות את אשתו — הרי נכרית זו שנתייבמה \u0003אסורה,\u0004 משום שעל ידי הזיקה שהיתה לה אל אחיו עוד לפני שגירש את אשתו, הרי היא נחשבת כצרת אחות אשתו. \u0003אמר רב אשי: זאת אומרת: יש זיקה, אפילו בתרי אחי\u0004 \u0005[בשני אחים].\u0006 שאף שהיו שני אחים שאליהם היא זקוקה לייבום, אומרים אנו שיש זיקה לשניהם, והיא נאסרת משום צרת אחות אשה בזיקה.","ושואלים: \u0003ולרב אשי קשיא\u0004 \u0005[קשה]\u0006 מה שאמר \u0003רב נחמן\u0004 על המשנה הראשונה שבדף זה, שאפשר לדקדק ממנה שאין זיקה אפילו באח אחד! ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003רב אשי:\u0004 הדיוק שדייק רב נחמן במשנה הראשונה איננו הכרחי. שאפשר היה לומר: \u0003הוא הדין דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003לא עבד\u0004 \u0005[עשה]\u0006 \u0003בה\u0004 נשוי הנכרית \u0003מאמר,\u0004 גם אז \u0003נכרית מיחלץ חלצה\u0004 \u0005[לחלוץ,\u0006 היתה \u0005חולצת],\u0006 אבל \u0003יבומי לא מייבמה\u0004 \u0005[לייבם, אינה מתייבמת],\u0006 משום שהיתה צרת אחות אשה בזיקה. \u0003והא דקתני\u0004 \u0005[ומה ששנה]\u0006 \u0003מאמר\u0004 — לא בא להודיענו שאסורה משום המאמר, אלא \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 מדברי \u0003בית שמאי דאמרי\u0004 \u0005[שאומרים]\u0006 \u0003מאמר קונה\u0004"],["\u0003קנין גמור,\u0004 ולשיטה זו הנכרית אינה צריכה אפילו חליצה, שהרי נחשבת צרת ערוה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003לא כ\u0004דעת \u0003בית שמאי.\u0004","ושואלים מצד שני: \u0003ולרב נחמן\u0004 שדייק מהמשנה ראשונה שאין זיקה, \u0003קשיא\u0004 \u0005[קשה]\u0006 דיוקו של \u0003רב אשי\u0004 ממשנתנו שיש זיקה! \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ותנסה לתרץ בדרך דומה: \u0003הוא הדין\u0004 במשנתנו שלנו ש\u0003אפילו\u0004 אם \u0003מת\u0004 האח שהיה נשוי נכרית \u0003ואחר כך גירש\u0004 הנשוי לאחות האחרת את אשתו, שגם אז \u0003צרתה\u0004 של האחות (כלומר, הנכרית) \u0003מותרת. אלא,\u0004 אם כך אתה אומר — \u0003\"זו היא\"\u0004 שנאמר בסוף המשנה \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]?\u0006 שהרי לפירוש זה הוא הדין בכל מקרה! ומשיבים: \u0003למעוטי\u0004 \u0005[למעט]\u0006 מקרה אחר, שקודם \u0003כנס\u0004 בעל האחות את הנכרית, כלומר, שייבם אותה, \u0003ואחר כך גירש\u0004 את האחות, שבמקרה זה אותה נכרית היא בוודאי צרת אחות אשתו ואינה מותרת.","ואומרים: \u0003הניחא אי סבר לה\u0004 \u0005[זה נוח אם סבור הוא]\u0006 בפירוש המשניות \u0003כ\u0004דעת \u0003ר' ירמיה,\u0004 ש\u0003אמר: תברא\u0004 \u0005[\u0006יש \u0005שבר]\u0006 חוסר המשכיות במשניות, ואין משנתנו זו באותה שיטה כמו המשנה בפרק ראשון, הקובעת בדרך כלל שאם נתגרשו הקרובות שוב אין כאן משום איסור צרה. ולדעתו \u0003מי ששנה זו לא שנה זו.\u0004","\u0003ו\u0004יסוד המחלוקת הוא: \u0003האי תנא\u0004 \u0005[תנא זה]\u0006 של המשנה בפרק ראשון \u0003סבר\u0004 כי \u0003מיתה מפלת,\u0004 כלומר, הזמן הקובע לענין איסור צרות הוא כאשר מת היבם ולפי המצב באותה שעה קובעים אם היבמה מותרת לו ולפיכך גם כנס ואחר כך גירש מותרת. \u0003והאי תנא\u0004 \u0005[ותנא זה]\u0006 של משנתנו \u0003סבר\u0004 כי \u0003נישואין הראשונים מפילים,\u0004 שאם בזמן שהיתה האשה נשואה לאח שמת היתה אסורה משום קרבה וצרתה היתה אסורה משום צרת ערוה, אף שעם מותו השתנה מצב הקירבה, היא ממשיכה להיות אסורה וכן צרתה אסורה.","ולשיטה זו אכן אפשר לומר כי ההדגשה \u0003\"זו היא\"\u0004 באה \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003כנס ולבסוף גירש. אלא אי סבר לה\u0004 \u0005[אם סבור הוא]\u0006 \u0003כרבא,\u0004 ש\u0003אמר: לעולם\u0004 תפרש שדעת \u0003חד תנא\u0004 \u0005[תנא אחד]\u0006 \u0003הוא,\u0004 אלא בסגנון \u0003ו\"זו ואין צריך לומר זו\" קתני\u0004 \u0005[שנה],\u0006 ואף התנא במשנתנו סבור כי כנס ואחר כך גירש מותרת, אם כן \u0003\"זו היא\" למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]?\u0006 ומשיבים: \u0003על כרחך\u0004 עליך לומר כי רב נחמן \u0003כר' ירמיה סבירא ליה\u0004 \u0005[סבור הוא]\u0006 בפירושו את המשניות.","שואלים מצד אחר: \u0003ולרבא\u0004 הסובר כי מיתה מפלת ואם כנס ואחר כך גירש מותרת, \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003אי סבר לה\u0004 \u0005[אם סבור הוא]\u0006 \u0003כרב אשי\u0004 שיש זיקה, אם כן יש לומר ש\u0003\"זו היא\"\u0004 באה \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003מת בלא גירש\u0004 כלל, שאסורה משום שהיתה כל הזמן צרת ערוה בזיקה, \u0003אלא אי סבר לה\u0004 \u0005[אם סבור הוא]\u0006 \u0003כרב נחמן\u0004 בענין זה שאין זיקה — \u0003\"זו היא\" למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 בא? ומשיבים: \u0003על כרחך\u0004 יש לומר כי \u0003כרב אשי סבירא ליה\u0004 \u0005[סבור הוא],\u0006 ולפי זה יש קשר בין השיטות השונות בפירושי המשניות והמחלוקת ביחס להלכה זו.","\u0003וכולן,\u0004 כל חמש עשרה הנשים האסורות משום ערוה, אם \u0003היו בהן\u0004 לאחיו שמת \u0003קדושין או גרושין בספק\u0004 — \u0003הרי אלו הצרות\u0004 שלהן \u0003חולצות ולא מתייבמות,\u0004 משום שהן צרות ערוה מספק. ומסבירים \u0003כיצד ספק קדושין? זרק לה\u0004 חפץ לשם \u0003קדושין\u0004 ברשות הרבים, והיה ביניהם מרחק של שמונה אמות, והיה החפץ \u0003ספק קרוב לו\u0004 ולא הגיע לרשותה \u0003ספק קרוב לה —\u0004 ובתוך ארבע אמות שלה, שהיא יכולה לזכות בחפץ בקנין ארבע אמות — \u0003זהו ספק קדושין.\u0004","\u0003ספק גרושין —\u0004 כגון \u0003כתב\u0004 גט \u0003בכתב ידו ואין עליו עדים\u0004, או \u0003יש עליו עדים ואין בו זמן\u0004 (תאריך), או \u0003יש בו זמן ואין בו אלא עד אחד,\u0004 כיון ששלושת הגיטין האלה ספק אם הם תופסים, הרי אשה שנתגרשה בהם הינה ספק מגורשת ו\u0003זהו\u0004 הקרוי \u0003ספק גרושין.\u0004","מעירים: \u0003ואילו בגרושין, ספק קרוב לו ספק קרוב לה לא קתני\u0004 \u0005[שנה],\u0006 אף שלכאורה אפשר היה לומר אותו דבר בגט כמו בקידושין, שזרקו ולא נתברר אם היה קרוב לו או לה.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שלא הביא במשנתנו גם ענין זה? \u0003אמר רבה\u0004 ספק זה אינו מחייב חליצה, שכן \u0003אשה זו,\u0004 הצרה, הלא \u0003בחזקת היתר לשוק עומדת,\u0004 שהרי בשעת הנישואין היתה צרת ערוה \u0003ומספק\u0004 בלבד \u0003אתה בא לאוסרה\u0004 לשוק עד שתחלוץ מפני שלא ברור לנו מה המצב ושמא נתגרשה הערוה — \u0003אל תאסרנה מספק.\u0004 מה שאין כן הגיטין שהוזכרו במשנה שהם גיטין ודאי, אלא שיש בהם חשש ופקפוק.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אי הכי\u0004 \u0005[אם כך]\u0006 אתה אומר, \u0003בקדושין נמי נימא\u0004 \u0005[גם כן נאמר]:\u0006 \u0003אשה זו\u0004 הצרה \u0003בחזקת היתר ליבם עומדת\u0004 לפני שקידש את הערוה, \u0003ומספק\u0004 שמא היא צרת ערוה \u0003אתה בא לאוסרה — אל תאסרנה מספק,\u0004 ותתייבם!","ומסבירים: \u0003התם\u0004 \u0005[שם],\u0006 לענין הקדושין, אנחנו הולכים \u0003לחומרא\u0004 כי אמנם הצרה היתה ודאי אשתו והיתה צריכה ייבום, ובגלל ספק שבקידושי הערוה החמרנו עליה שלא תתייבם ורק תחלוץ.","ומקשים: הרי \u0003האי\u0004 \u0005[\u0006חומרה \u0005זו]\u0006 — \u0003חומרא דאתי לידי קולא\u0004 \u0005[ש\u0006עלולה \u0005להביא לידי הקלה]\u0006 במקום אחר \u0003הוא.\u0004 כיצד? \u0003זימנין דאזיל\u0004 \u0005[פעמים שהולך]\u0006 \u0003הוא,\u0004 אותו אדם עצמו שקידש את הערוה \u0003ומקדש לה\u0004 \u0005[אותה]\u0006 את \u0003אחותה קדושי ודאי\u0004 בחיי בעלה, ואם אתה אומר שהיא לחומרה ואינה מתייבמת משום צרת ערוה, יאמרו שאין קידושין תופסים באחותה שהרי היא אחות אשתו ולא ידעו שקידושי הראשון היו מספק, וכי רק לחומרא בלבד אמרו שלא תתייבם, וצריך שיחולו קידושין מספק באחותה. ונמצא אתה מתיר אשת איש.","\u0003ואי נמי\u0004 \u0005[ואם גם כן]\u0006 \u0003זימנין דאתא\u0004 \u0005[פעמים שיבוא]\u0006 אדם \u0003אחר ומקדש לה לדידה\u0004 \u0005[ויקדש אותה עצמה]\u0006 \u0003קדושי ודאי, וכיון\u0004 ש\u0003אסר לה מר לצרה לייבומי\u0004 \u0005[שאדוני אוסר את הצרה לייבום]\u0006 \u0003אמרי\u0004 \u0005[יאמרו]\u0006 אנשים: שקידושין \u0003דקמא\u0004 \u0005[של הראשון],\u0006 האח שמת, \u0003קדושין\u0004 גמורים היו, \u0003ודבתרא\u0004 \u0005[ושל האחרון],\u0006 של האיש האחר, \u0003לאו\u0004 \u0005[לא]\u0006 \u0003קדושין\u0004 הם. שהרי אם היא נשואה לראשון הריהי אסורה לשני משום אשת איש ואין קידושין תופסים בה, וכיון שאינה מקודשת לראשון, בודאי תפסו בה גם קידושי שני, ונמצא שיבואו להתיר אשת איש!"],["\u0003כיון דקא מצרכת\u0004 \u0005[שאתה מצריך]\u0006 \u0003חליצה,\u0004 ואין אתה פוטר אותה לגמרי — \u0003מידע ידעי דחומרא בעלמא הוא\u0004 \u0005[\u0006הכל \u0005יודעים שחומרה בלבד היא]\u0006 שלא החליטו חכמים שקידושין ראשונים ודאיים הם, ולא יבואו להפקיע את הקידושין האחרים. הקשה לו אביי: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003גירושין נמי ליתני\u0004 \u0005[גם כן שישנה]\u0006 ספק קרוב לו ספק קרוב לה, \u0003וליצרכה\u0004 \u0005[ויצריכנה]\u0006 \u0003חליצה, ומידע ידעי דחומרא בעלמא הוא\u0004 \u0005[ויודעים שחומרה בלבד היא]\u0006 ולא יבואו לידי מכשול!","ענה לו: יש בכך מכשול, שכן \u0003אם אתה אומר חולצת,\u0004 מתוך כך עלול להיות שתהא גם \u0003מתייבמת.\u0004 שמא יטעו אנשים ויחשבו שאם היא ראויה לחליצה — ראויה היא גם לייבום, ויגרמו לייבום אשה האסורה בייבום. הקשה לו אביי: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בספק קדושין, \u0003אם אתה אומר חולצת\u0004 שמא תהא גם \u0003מתייבמת!\u0004 ענה לו רבה: \u0003ותתייבם, ואין בכך כלום\u0004 כי במקרה כזה על ה\u0003חזקה\u0004 שלה, שהיא חזקת היתר, \u0003קא קיימא\u0004 \u0005[היא\u0006 \u0005עומדת],\u0006 שבעיקרו של דבר אנו מניחים שהיא מותרת בייבום ושאסרנוה רק מחמת חשש, וגם אם תתייבם, לא תהא בכך עבירה ממש.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי,\u0004 אפשר להוכיח שגם במקום של ספק אומרים שצריכה לחלוץ, שכן שנינו במשנה: \u0003נפל הבית עליו\u0004 על אדם אחד \u0003ועל בת אחיו\u0004 שהיתה נשואה לו, ולא היו לו ילדים, \u0003ואין ידוע איזה מהם מת ראשון,\u0004 אם היתה צרה לאותה אשה שמתה, הרי \u0003צרתה חולצת ולא מתייבמת,\u0004 שאם הוא מת ראשון נמצא שבשעת מותו היתה הצרה אסורה ליבם משום צרת בתו. אבל אם הבת מתה קודם, הרי בשעת מיתת הבעל לא היתה האשה השניה צרת ערוה, וחייבת בייבום. ומחמת ספק זה חולצת ולא מתייבמת.","ולשיטתך, \u0003אמאי\u0004 \u0005[מדוע]\u0006 נעשה כך? \u0003הכא נמי נימא\u0004 \u0005[כאן גם כן נאמר]\u0006 ש\u0003אשה זו,\u0004 הצרה, \u0003בחזקת היתר לשוק עומדת\u0004 שכל תקופת נשואיה היתה פטורה מייבום משום צרת ערוה, \u0003ומספק\u0004 (שמא מתה צרתה קודם) \u0003אתה בא לאוסרה\u0004 ולהצריכה חליצה — \u0003אל תאסרנה מספק!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הכא נמי לחומרא\u0004 \u0005[כאן גם כן לחומרה]\u0006 אנו עושים, מחמת ספק, הלא \u0003חומרא דאתי לידי קולא הוא\u0004 \u0005[חומרה שבאה לידי הקלה היא].\u0006 \u0003שאם אתה אומר חולצת\u0004 יאמרו שהיא גם \u0003מתייבמת,\u0004 ואם תתייבם — הרי יש בה ספק איסור צרת הבת, האסורה משום ערוה כבת עצמה! השיב לו רבה: \u0003גירושין דשכיחי\u0004 \u0005[ש\u0006הם \u0005מצויים] —\u0006 \u0003גזרו בהו רבנן\u0004 \u0005[בהם חכמים],\u0006 שאם אתה אומר שחולצת, יכול להיווצר מכשול שתהא מתייבמת, אולם \u0003מפולת דלא שכיחי\u0004 \u0005[שאינה מצויה]\u0006 — \u0003לא גזרו בהו רבנן\u0004 \u0005[בהן חכמים],\u0006 שאין חכמים גוזרים גזירה בדבר שאינו מצוי.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 טעם אחר להבדיל בין המקרים: \u0003גירושין דקיימא\u0004 \u0005[שקיימת]\u0006 \u0003ערוה דקא מוכח\u0004 \u0005[שהיא מוכחת],\u0006 שידוע שהיא ערוה, \u0003וצרתה קמצרכת לה\u0004 \u0005[אתה מצריך אותה]\u0006 \u0003חליצה, אמרי\u0004 \u0005[אומרים]\u0006 אנשים: \u0003קמו ביה רבנן בגיטא\u0004 \u0005[עמדו,\u0006 ביררו, \u0005חכמים בגט\u0006 זה\u0005]\u0006 וקבעו \u0003דגיטא מעליא\u0004 \u0005[שגט מעולה]\u0006 \u0003הוא,\u0004 ולכן הצריכו לחלוץ לצרה \u0003ואתו לייבומי\u0004 \u0005[ובאים לייבם]\u0006 את ה\u0003צרה\u0004 על סמך הנחה מוטעית זו. ואילו במקרה של \u0003מפולת, מי קמו בהו רבנן\u0004 \u0005[האם עמדו חכמים בהם]\u0006 \u0003במפולת\u0004 לדעת מי מהם מת קודם? והכל יודעים שהיה כאן ספק שלא נתברר, ויבינו שרק מחמת הספק גזרו שתחלוץ ולא יבואו לייבם על סמך חליצה זו.","ושואלים: \u0003וגבי גירושין מי לא תנן\u0004 \u0005[האם לא שנינו]\u0006 דין זה, בספק קרוב לו וספק קרוב לה? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003היתה\u0004 אשתו \u0003עומדת ברשות הרבים\u0004 במרחק שמונה אמות מבעלה \u0003וזרקו\u0004 את הגט \u0003לה,\u0004 אם היה הגט \u0003קרוב לה\u0004 בתוך ארבע אמותיה — \u0003מגורשת,\u0004 ואם היה \u0003קרוב לו\u0004 בתוך ארבע אמותיו — \u0003אינה מגורשת.\u0004 היה \u0003מחצה על מחצה — מגורשת ואינה מגורשת.\u0004","\u0003ואמרינן\u0004 \u0005[ואומרים אנו]\u0006 על כך: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזה ענין, נאמרה \u0005הלכה]\u0006 זו שהיא מגורשת ואינה מגורשת? ומסיקים: לשני עניינים, \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003כהן הוא\u0004 המגרש הזה — \u0003אסורה ליה\u0004 \u0005[לו]\u0006 אשתו מספק, שמא נתגרשה על ידי גט זה ואינו יכול לחזור ולשאתה. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003ערוה היא,\u0004 כלומר, שהאשה הזו המגורשת מספק היא ערוה לאחי הבעל, ומת בעלה, הרי אף שהיא עצמה אסורה להתייבם — \u0003צרתה בעיא\u0004 \u0005[צריכה]\u0006 \u0003חליצה.\u0004 ומכאן רואים שאין הבדל בין קידושין וגירושין \u0003ולא אמרינן\u0004 \u0005[ואין אנו אומרים]\u0006 \u0003שאם אתה אומר חולצת מתייבמת\u0004 ואין חוששים איפוא לחשש זה!","ומשיבים: \u0003הא איתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר עליה]\u0006 על הלכה זו, שהיא מקרה מיוחד. \u0003רבה ורב יוסף דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 בספק גט זה שדיברנו בו — \u0003בשתי כיתי עדים עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שכת \u0003אחת\u0004 של עדים \u0003אומרת:\u0004 נפל הגט \u0003קרוב לה, ואחת אומרת: קרוב לו. דהוה ליה ספיקא דאורייתא\u0004 \u0005[שהרי הוא ספק מן התורה]\u0006 שיש כאן שתי עדויות שכל אחת מהן מושלמת לעצמה והן סותרות זו את זו, ודבר כגון זה, ספק מן התורה הוא ומחמירים בו. \u0003ומתניתין דהכא\u0004 \u0005[ומשנתנו של כאן]\u0006 מדברת \u0003בכת אחת\u0004 של עדים, שנחלקו בעדותם, או שלא יכלו לברר מה קרה בדיוק. \u0003דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 נעשה \u0003ספיקא דרבנן\u0004 \u0005[ספק\u0006 רק מדברי \u0005חכמים]\u0006 שיש לפנינו עדות אחת מסופקת, ובספק שמדברי סופרים נוטים להקל.","ושואלים: \u0003וממאי דמתניתין דהכא\u0004 \u0005[וממה\u0006 יודע אתה \u0005ש\u0006ב\u0005משנתנו של כאן]\u0006 מדובר שהיה הספק \u0003בכת אחת?\u0004 ומשיבים: \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003קדושין, מה קדושין\u0004 מדובר בספק \u0003בכת אחת, אף גרושין\u0004 מדובר \u0003בכת אחת.\u0004 ותוהים: \u0003וקדושין גופייהו\u0004 \u0005[עצמם]\u0006 שבמשנתנו, \u0003ממאי\u0004 \u0005[ממה]\u0006 יודע אתה שמדובר בספק \u0003ב\u0004דברי \u0003כת אחת\u0004 של עדים? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003בשתי כיתי עדים?\u0004 ומשיבים: \u0003אי\u0004 \u0005[אם]\u0006 מדובר פה \u0003בשתי כיתי עדים\u0004 הסותרות זו את זו \u0003תתייבם, ואין בכך כלום,\u0004 שהרי יש עדים האומרים שלא נתקדשה.","ומקשים: כיצד אפשר לומר כך, הרי \u0003קיימי\u0004 \u0005[עומדים]\u0006 \u0003עדים וקאמרי\u0004 \u0005[ואומרים]\u0006 שהקידושין נפלו \u0003קרוב לה,\u0004 ולפי זה היא מקודשת וצרתה היא צרת ערוה ויש כאן איפוא ספק מן התורה, \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 \u0003תתייבם ואין בכך כלום?! ותו\u0004 \u0005[ועוד],\u0006 לגופו של ההבדל בין שתי כיתות לכת אחת — הלא גם \u0003בשתי כיתי עדים נמי ספיקא דרבנן היא\u0004 \u0005[גם כן ספק מדברי סופרים הוא]\u0006 ואינו נחשב כספק בעצם המציאות, שהוא ספק מן התורה. ומדוע — \u0003דאמרינן\u0004 \u0005[שאומרים אנו]:\u0006 \u0003אוקי תרי לבהדי תרי\u0004 \u0005[העמד שנים כנגד שנים],\u0006 כלומר, העמד את שני העדים מול שני העדים האחרים, ואין כאן איפוא ספק מן התורה, שבטלה העדות, \u0003ו\u0004את ה\u0003אשה אוקמה אחזקה\u0004 \u0005[העמד אותה על חזקתה],\u0006 מכיון שספק זה הוא רק מדברי סופרים ולא מדברי תורה!","וראיה לדבר, \u0003מידי דהוה אנכסי\u0004 \u0005[כמו\u0006 המקרה \u0005שהיה בנכסים]\u0006 של אדם אחד שהיה מכונה \u0003בר שטיא,\u0004 משום שלעתים היה משתגע. וכך היה המעשה: \u0003בר שטיא\u0004 זה \u0003זבין נכסי\u0004 \u0005[מכר נכסים],\u0006 \u0003אתו בי תרי ואמרי\u0004 \u0005[באו שנים,\u0006 שני עדים, \u0005ואמרו]:\u0006 \u0003כשהוא חלים\u0004 \u0005[בריא]\u0006 \u0003זבין\u0004 \u0005[מכר],\u0006 והמכירה קיימת \u0003ואתו בי תרי ואמרי\u0004 \u0005[ובאו שנים\u0006 אחרים \u0005ואמרו]:\u0006 \u0003כשהוא שוטה זבין\u0004 \u0005[מכר],\u0006 ואז אין ממש במכירה. \u0003ואמר רב אשי\u0004 בענין זה: \u0003אוקי תרי להדי תרי\u0004 \u0005[העמד שני\u0006 עדים \u0005כנגד שנים]\u0006 ועדות אחת מכחישה את השניה, ואין איפוא לפנינו שום עדות,"],["\u0003וארעא אוקמא\u0004 \u0005[ו\u0006את \u0005הקרקע העמד]\u0006 \u0003בחזקת בר שטיא,\u0004 שכיון שאין כאן הוכחה, משאירים את הדבר בחזקתו. ואם כן, אף במקרה של קידושין ושל גירושין היינו צריכים לומר שאין זה אלא ספק מדברי סופרים ותישאר האשה בחזקתה!","\u0003אלא אמר אביי:\u0004 יש לדחות את דברי רבה ופירושו, ויש להבין את הדבר כמליצת הכתוב \u0003\"יגיד עליו רעו\"\u0004 (איוב לו, לג), שדבר אחד נלמד מחבירו. כלומר, \u0003תנא\u0004 \u0005[שנה\u0006 התנא\u0005],\u0006 ספק זה, \u0003בקידושין, והוא הדין לגירושין\u0004 כאשר היה הגט ספק קרוב לו ספק קרוב לה. וכן \u0003תנא בגירושין\u0004 גיטין שיש ספק בכתיבתם, \u0003והוא הדין לקידושין.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אי\u0004 \u0005[אם]\u0006 אתה מפרש שאין הדינים מיוחדים לכל מקרה, אלא בסגנון של \u0003\"יגיד עליו רעו\", מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"זהו\" דקתני\u0004 \u0005[ששנה]\u0006 במשנה? שלשון המשנה \"זהו ספק קידושין\", \"זהו ספק גירושין\", משמעה: זהו ולא אחר!","\u0003אלא אמר רבא: כל\u0004 הספקות \u0003שיש בקידושין,\u0004 וכגון ספק קרוב לו ספק קרוב לה — \u0003יש\u0004 גם \u0003בגירושין. ו\u0004אולם, \u0003יש בגירושין\u0004 ספקות \u0003מה שאין בקידושין,\u0004 שבקידושין טעות בשטר אינה פוסלת. \u0003ו\u0004לפי זה \u0003\"זהו\"\u0004 שנאמר במשנה ב\u0003גירושין — לאו דוקא,\u0004 אינו מדוייק ואיננו בא למעט ספק קרוב לו ספק קרוב לה, \u0003אלא, משום דתנא\u0004 \u0005[ששנה]\u0006 \u0003\"זהו\" בקדושין תנא נמי\u0004 \u0005[שנה גם כן]\u0006 \u0003\"זהו\" בגירושין. ו\u0004שואלים: \u0003\"זהו\"\u0004 האמור ב\u0003קידושין למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 בא? ומשיבים: \u0003למעוטי\u0004 \u0005[למעט]\u0006 ענין ה\u0003זמן\u0004 התאריך, \u0003דליכא\u0004 \u0005[שאינו]\u0006 \u0003בקידושין.\u0004 שגם אם מקדש אשה בשטר — אינו צריך לכתוב בו זמן.","ושואלים לגופו של דבר: \u0003ומפני מה\u0004 באמת \u0003לא תקנו זמן בקידושין? הניחא\u0004 \u0005[זה נוח]\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהטעם שתיקנו כתיבת תאריך בגט הוא \u0003משום פירי\u0004 \u0005[פירות]\u0006 שכן מזמן הנישואין זכאי הבעל לאכול (וליהנות) מפירות נכסיה של האשה, וצריך שייכתב תאריך בגט כדי לדעת מאימתי הופקעה זכותו לאכול מהם ולמכור את הפירות. ומשום כך אין צריך לכתוב תאריך בשטר קידושין, שהרי שטר הקידושין יוצר רק קשר אירוסין ו\u0003ארוסה לית לה פירי\u0004 \u0005[אין לה פירות],\u0006 כלומר, אין הבעל אוכל פירות נכסיה עד שישאנה.","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שתיקנו חובת כתיבת זמן בגיטין \u0003משום בת אחותו,\u0004 שפעמים שאדם נשוי לבת אחותו והוא יודע שזנתה תחתיו, ומתוך שהיא קרובתו וחס עליה — עשוי הוא לתת לה גט בלי תאריך כדי להצילה מעונש מוות (אם יבואו עדים ויעידו על כך), וכשבאים העדים ומעידים עליה, היא יכולה לטעון שבאותו זמן כבר היתה גרושה. ואם כן, משום חשש זה, \u0003ליתקין\u0004 \u0005[שיתקינו]\u0006 \u0003זמן\u0004 גם בשטר אירוסין, שאף על ידי שטר קידושין בלא תאריך יוכל לחפות על בת אחותו, שאם תזנה תחתיו בתקופת האירוסין אי אפשר יהיה להענישה, ולכן מן ההכרח לכתוב זמן גם בשטר זה!","ומשיבים: \u0003משום דאיכא\u0004 \u0005[שיש]\u0006 מי ש\u0003מקדש בכספא\u0004 \u0005[בכסף]\u0006 \u0003ואיכא\u0004 \u0005[ויש]\u0006 מי ש\u0003מקדש בשטרא\u0004 \u0005[בשטר],\u0006 לכך \u0003לא תקון רבנן\u0004 \u0005[חכמים]\u0006 \u0003זמן\u0004 גם בשטר, שהרי בקידושי כסף אין מקום לזמן.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף לרב אשי: והא עבדא\u0004 \u0005[והרי\u0006 ה\u0005עבד],\u0006 \u0003דאיכא דקני בכספא ואיכא בשטרא\u0004 \u0005[שיש שקונה\u0006 אותו \u0005בכסף ויש\u0006 שקונה אותו \u0005בשטר]\u0006 \u0003ו\u0004בכל זאת \u0003תקון רבנן\u0004 \u0005[התקינו חכמים]\u0006 \u0003זמן\u0004 בשטר קנין עבד! והשיב לו: \u0003התם רובא בשטרא\u0004 \u0005[שם\u0006 בעבד \u0005הרוב\u0006 קונים \u0005בשטר],\u0006 \u0003הכא רובא בכספא\u0004 \u0005[כאן\u0006 בקידושין, \u0005הרוב\u0006 מקדשים \u0005בכסף].\u0006","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 טעם אחר, שלא תיקנו שייכתב זמן בשטר אירוסין, \u0003משום דלא\u0004 \u0005[שאי]\u0006 \u0003אפשר\u0004 לתקן זאת באופן שיבטיח שלא יבוא מכשול על ידי כך. ומדוע: \u0003היכי ליעביד\u0004 \u0005[כיצד נעשה]?\u0006 \u0003לינחה גבי דידה\u0004 \u0005[\u0006אם תאמר \u0005שיניחו\u0006 את שטר קידושין \u0005אצלה]\u0006 — \u0003מחקה ליה\u0004 \u0005[תמחק\u0006 היא \u0005אותו,\u0006 את התאריך\u0005]\u0006 ושוב אי אפשר יהיה להוכיח מתי זינתה. \u0003לינחה גבי דידיה\u0004 \u0005[שיניחו\u0006 את השטר \u0005אצלו] —\u0006 \u0003זמנין\u0004 \u0005[פעמים]\u0006 ש\u0003בת אחותו היא ומחפה עלה\u0004 \u0005[עליה]\u0006 והוא ימחק את התאריך.","ואם תאמר \u0003לינחה גבי\u0004 \u0005[שיניחוהו אצל]\u0006 ה\u0003עדים\u0004 החתומים על השטר — הרי \u0003אי דזכירי\u0004 \u0005[אם\u0006 יהיה המקרה \u0005שזוכרים]\u0006 מעצמם את זמן נתינת השטר לאשה — הרי אינם זקוקים לתאריך שבו, \u0003ליתו ליסהוד\u0004 \u0005[שיבואו\u0006 וש\u0005יעידו]\u0006 על כך על פי זכרונם. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא,\u0004 שאינם זוכרים מעצמם — \u0003זמנין דחזו מכתבא ואתו מסהדי\u0004 \u0005[פעמים ש\u0006הם \u0005רואים\u0006 רק \u0005מתוך הכתב\u0006 את התאריך \u0005ויבואו להעיד]\u0006 על סמך הכתוב, \u0003ורחמנא אמר\u0004 \u0005[והתורה אמרה]\u0006 \u0003\"מפיהם\" — ולא מפי כתבם,\u0004 שאין עדות כשירה אלא זו שאדם אומרה ממה שיודע מעצמו, ולא על סמך דבר כתוב.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003בגירושין נמי נימא הכי\u0004 \u0005[גם כן נאמר כך]\u0006 שקיים אותו חשש, שמא תבוא האשה למחוק את התאריך שבגט המצוי ברשותה! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 בגט — הזמן הכתוב בו, \u0003להצלה דידה\u0004 \u0005[שלה]\u0006 \u0003קאתי\u0004 \u0005[בא\u0006 התאריך\u0005],\u0006 שהרי הגט מוציאה מחזקת אשת איש והיא חוששת למחקו שמא ייפסל לגמרי ותיחשב גם אחר כך כנשואה (רמב\"ן), אבל \u0003הכא\u0004 \u0005[כאן]\u0006 בשטר אירוסין, הזמן \u0003לחובה דידה\u0004 \u0005[שלה]\u0006 \u0003קאתי\u0004 \u0005[\u0006הוא \u0005בא],\u0006 שאם תמחוק את התאריך, או תחביא את השטר, הרי בחזקת פנויה היא עומדת, ובלא תאריך ברור היא לא תיענש.","\u0003שלשה אחין, נשואין\u0004 ל\u0003שלש\u0004 נשים \u0003נכריות\u0004 (שאינן קרובות זו לזו) \u0003ומת אחד מהן, ועשה בה השני מאמר\u0004 ולא הספיק לכונסה, \u0003ומת\u0004 גם הוא — \u0003הרי אלו\u0004 שתי הנשים שנפלו לפני האח השלישי \u0003חולצות ולא מתייבמות.\u0004","ומדוע — \u0003שנאמר: \"ומת אחד מהם... יבמה יבא עליה\"\u0004 (דברים כה, ה), לומר: זו \u0003שעליה זיקת יבם אחד,\u0004 שזקוקה רק לייבום לאיש אחד \u0003ולא\u0004 זו \u0003שעליה זיקת שני יבמין,\u0004 שהרי זו שהיתה אשתו של האח שמת ראשון עדיין זקוקה בגללו לייבום, ומשעשה בה השני מאמר ומת, נוספה לה זיקה נוספת. \u0003ר' שמעון אומר:\u0004 אין לחשוש לכך, אלא \u0003מייבם לאיזו\u0004 מהן \u0003שירצה וחולץ לשניה.\u0004","שואלים: \u0003ואי\u0004 \u0005[אם]\u0006 הלכה זו, לפטור מייבום אשה שעליה \u0003זיקת שני יבמין דאורייתא\u0004 \u0005[מן התורה]\u0006 היא, כפי שאפשר להבין מן הראיה המובאת במשנה, אם כן \u0003חליצה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא תיבעי\u0004 \u0005[תצטרך]\u0006 ותיפטר לגמרי! \u0003אלא\u0004 יש לומר, שבאמת איסור זה אינו מן התורה (שמדין תורה היה רשאי לייבם את שתיהן, כל אחת משום שהיא אשתו של אח אחר), אלא \u0003מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003וגזירה\u0004 עשו בכך, \u0003שמא יאמרו\u0004 אנשים ש\u0003שתי יבמות הבאות מבית אחד מתייבמות.\u0004 שכיון שעשה בה האח השני מאמר, עלולים לחשוב ששתיהן הן נשיו של האח השני, ואם יתייבמו שתיהן, יחשבו שאדם רשאי לייבם שתי נשותיו של אחיו, והרי התורה מתירה ייבום רק באשה אחת של המת, ולא בשתים.","ושואלים: \u0003ונייבם לחדא וניחלוץ לחדא\u0004 \u0005[ושייבם ל\u0006אשה \u0005אחת\u0006 מהן \u0005ושיחלוץ לאחת]\u0006 ואז אין מקום לחשש זה! ומשיבים: אין עושים כן, \u0003גזירה שמא יאמרו: בית אחד\u0004 (שתי נשים של איש אחד), \u0003מקצתו בנוי\u0004"],["\u0003ומקצתו חלוץ,\u0004 ששתי יבמות שהיו נשואות לאיש אחד, לאחת מייבמים ולשניה חולצים.","ותוהים: \u0003ויאמרו!\u0004 מה איכפת לנו אם יאמרו? שהרי גם אם ינהגו כך לא יהיה בכך כל נזק, שהרי אין עבירה בחליצה! ומשיבים: \u0003אי\u0004 \u0005[אם]\u0006 שהוא \u0003מייבם\u0004 בתחילה לאחת \u0003והדר חליץ\u0004 \u0005[ו\u0006רק \u0005אחר כך\u0006 הוא \u0005חולץ]\u0006 לשניה — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 ולא היה חשש.","\u0003אלא גזירה דילמא חליץ ברישא\u0004 \u0005[שמא יחלוץ בראשונה]\u0006 לאחת מנשי אחיו \u0003והדר מייבם\u0004 \u0005[ויחזור\u0006 ו\u0005ייבם]\u0006 את השניה, \u0003ו\u0004במקרה זה עבר על איסור, כי מאחר שכבר חלץ \u0003קם ליה\u0004 \u0005[עומד הוא]\u0006 \u0003ב\u0004איסור \u0003\"אשר לא יבנה\", ו\u0004הרי \u0003רחמנא אמר\u0004 \u0005[התורה אמרה]\u0006 \"אשר לא יבנה את בית אחיו\" (דברים כה, ט), לומר: \u0003כיון שלא בנה,\u0004 וחלץ ליבמה — \u0003שוב לא יבנה.\u0004","\u0003אמר רבא:\u0004 אם אותו אח שעשה בה מאמר גם \u0003נתן\u0004 לאותה אשה \u0003גט ל\u0004הפקיע את \u0003מאמרו — הותרה צרתה.\u0004 כלומר, מותר לאח השלישי לייבם את אשתו של זה שעשה מאמר ונתן גט, ששוב אינה נחשבת כצרת אשת שני מתים, שכן כל הקשר שהיה ביניהן התבטל. \u0003אבל היא\u0004 עצמה, אותה אשה שעשה בה מאמר וניתן לה גט — \u0003אסורה\u0004 לאח השלישי, ומדוע? \u0003דמחלפה\u0004 \u0005[ש\u0006היא \u0005מתחלפת]\u0006 שעלולים להחליפה \u0003בבעלת גט\u0004 אחרת שכן מי שנתן ליבמתו גט בלבד — אסור לו מאז לייבם אותה, ועלולים להתירה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 נוסח אחר, \u0003אמר רבא:\u0004 אם \u0003נתן\u0004 האח השני \u0003גט למאמרו — הותרה אפילו היא\u0004 להתייבם לשלישי. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003מאי דעבד\u0004 \u0005[מה שעשה]\u0006 \u0003בה,\u0004 המאמר — \u0003שקליה\u0004 \u0005[נטל אותו],\u0006 שביטל אותו על ידי הגט, ונמצא כאילו לא עשה דבר. ומשום כך הרי לגבי האח השלישי נשארת היא בזיקתה הראשונה כאילו לא עשה האח השני מאומה.","\u0003שני אחין נשואין\u0004 ל\u0003שתי אחיות, ומת אחד מהן\u0004 ואשתו פטורה מן הייבום משום אחות אשה \u0003ואחר כך מתה אשתו של שני,\u0004 הרי אף שהיבמה איננה עוד אחות אשתו, מכל מקום \u0003הרי זו אסורה עליו עולמית, הואיל ונאסרה עליו\u0004 כבר \u0003שעה אחת.\u0004","שואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 \u0003השתא\u0004 \u0005[עכשיו],\u0006 הרי, \u0003ומה התם\u0004 \u0005[שם]\u0006 (לעיל יבמות ל, א) במקרה של שלושה אחים ומהם שנים נשואים לשתי אחיות והשלישי נשוי לנכרית ומת אחד מבעלי האחיות וייבם בעל הנכרית את אשתו ואחר כך מתה אשתו של האח השני (אחת האחיות) ואחר כך מת בעל הנכרית, ש\u0003לא מידחיא מהאי ביתא\u0004 \u0005[נדחתה\u0006 אותה אשה \u0005מבית זה]\u0006 \u0003לגמרי,\u0004 שמשמת בעלה הראשון עדיין היתה חובת ייבום מוטלת עליה בשל האח השלישי שאינה אסורה עליו — \u0003אמרת\u0004 שלאחר מות יבמה, האח השלישי, \u0003לא\u0004 תתייבם, שמכיון שחל עליה איסור אחות אשה היא נפטרת מבעל אחותה לעולם, \u0003הכא דקא מידחיא מהאי ביתא\u0004 \u0005[כאן\u0006 שהיו רק שני אחים, \u0005שנדחתה מבית זה]\u0006 \u0003לגמרי,\u0004 שהרי בשעה שמת בעלה לא עמדה בפניה שום אפשרות להתייבם, \u0003לא כל שכן\u0004 שבטלה ממנה חובת ייבום! ומשיבים: ה\u0003תנא — הא תנא ברישא\u0004 \u0005[\u0006את המשנה \u0005הזו\u0006 של כאן \u0005שנה בתחילה],\u0006 \u0003והך חזיא להיתירא\u0004 \u0005[ואת אלה\u0006 האחרות \u0005ראה\u0006 בהן ל\u0005היתר]\u0006 \u0003ושריא\u0004 \u0005[והתירה],\u0006 \u0003והדר חזיא לאיסורא\u0004 \u0005[ואחר כך ראה\u0006 בהן צד \u0005איסור].\u0006 \u0003ואיידי דחביבה ליה אקדמה\u0004 \u0005[ועל ידי ש\u0006היתה \u0005חביבה עליו,\u0006 משום החידוש שבה, \u0005הקדים אותה]\u0006 ובאמת אין צורך עוד במשנתנו, אלא \u0003ומשנה\u0004 ראשונה אף שלאחר שנשנתה השניה הריהי מיותרת, \u0003לא זזה ממקומה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בא עליה\u0004 על אשה זו שאמרנו שאסורה עליו עולמית — \u0003חייב עליה\u0004 גם \u0003משום אשת אח,\u0004 שהרי לא הותרה משום מצות ייבום, \u0003ו\u0004גם \u0003משום אחות אשה,\u0004 אלו \u0003דברי ר' יוסי. ר' שמעון אומר: אינו חייב אלא משום אשת אח בלבד.\u0004 שאין איסור חל על איסור, וכיון שאסורה כבר מדין אשת אח, לא חל עליה איסור נוסף של אחות אשה. ושואלים: \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא אחרת\u0005],\u0006 \u0003ר' שמעון אומר: אינו חייב אלא משום אחות אשה בלבד!\u0004","ומשיבים: זו \u0003לא קשיא\u0004 \u0005[אינה קשה],\u0006 \u0003כאן\u0004 בברייתא שאמר ר' שמעון שאינו חייב אלא משום אחות אשה, הרי זה כ\u0003שנשא\u0004 האח ה\u0003חי\u0004 קודם את אשתו, \u0003ואחר כך נשא\u0004 האח ש\u0003מת\u0004 את אחותה, שמתחילה חל על אשה זו איסור אחות אשה, ואחרי שנשאה אחיו חל עליה גם איסור אשת אח. ואילו \u0003כאן\u0004 במשנה שאמר ר' שמעון שאינו חייב אלא משום אשת אח, הרי זה באופן \u0003שנשא\u0004 בתחילה האח ה\u0003מת\u0004 את אשתו, והיתה אסורה על האח קודם משום אשת אחיו, \u0003ואחר כך נשא\u0004 ה\u0003חי\u0004 את אחותה והפכה להיות גם אחות אשתו.","ושואלים: \u0003ו\u0004לדעת \u0003ר' שמעון, היכא\u0004 \u0005[היכן]\u0006 ש\u0003נשא\u0004 האח ש\u0003מת\u0004 קודם אחות אחת ונמצא שהיתה אסורה על אחיו משום אשת אח, \u0003ואחר כך נשא חי\u0004 את אחותה לשיטתו שרק האיסור הראשון בלבד חל ו\u0003כיון\u0004 ש\u0003איסור אחות אשה לא חייל\u0004 \u0005[אינו חל],\u0006 משום שהיתה אסורה כבר מצד אחר, הרי אחרי שמת בעלה — \u0003תתייבם יבומי\u0004 \u0005[שתתייבם]\u0006 עכשיו, שהרי איסור אשת אח שהיה עליה פקע והותר על ידי מיתת בעלה, והיא חייבת בייבום!","\u0003אמר רב אשי: איסור אחות אשה מיתלא תלי וקאי\u0004 \u0005[תלוי ועומד]\u0006 ואינו בטל לגמרי, \u0003אי פקע\u0004 \u0005[אם פוקע]\u0006 \u0003איסור אשת אח\u0004 במות האחד משום מצוות ייבום — \u0003אתי\u0004 \u0005[בא]\u0006 \u0003איסור אחות אשה וחייל\u0004 \u0005[וחל],\u0006 שהוא חוזר וניעור, ושוב היא אסורה עליו, \u0003והלכך\u0004 \u0005[ולכן]\u0006 \u0003לא פקע\u0004 לחלוטין.","מדברי הברייתא יוצא שלדעת ר' יוסי עובר מי שייבם אשה זו על שני איסורים. ושואלים: \u0003ו\u0004האם \u0003סבר ר' יוסי\u0004 ש\u0003איסור חל על איסור? והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003עבר עבירה שיש בה שתי מיתות,\u0004 כגון שבא על אשה שהיא ערוה לו והיא אשת איש, שיש בכך עונש מיתה אחד משום ערוה (שריפה), ועונש מיתה אחר משום אשת איש (חנק) — \u0003נידון ב\u0004מיתה ה\u0003חמורה\u0004 שבהן (שריפה). \u0003ר' יוסי אומר: נידון בזיקה הראשונה הבאה עליו.\u0004 כלומר, נידון לפי האיסור הראשון שחל עליו לגבי אשה זו.","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003כיצד אמר ר' יוסי נידון בזיקה הראשונה הבאה עליו?\u0004 למשל, אם היתה אשה זו \u0003חמותו,\u0004 והיא היתה אז אלמנה או גרושה, אם נישאה אחר כך \u0003ונעשית אשת איש\u0004 ובא עליה — \u0003נידון\u0004 בשריפה משום איסור \u0003חמותו,\u0004 שאיסור זה חל עליו תחילה. ואם היתה \u0003אשת איש\u0004 ולאחר מכן נשא את בתה \u0003ו\u0004אז \u0003נעשית חמותו,\u0004 אם בא עליה — \u0003נידון ב\u0004חנק משום איסור \u0003אשת איש.\u0004 הרי שלדעת ר' יוסי אין איסור חל על איסור ואינו חייב אלא באיסור אחד!"],["\u0003אמר ר' אבהו: מודה ר' יוסי באיסור מוסיף.\u0004 כלומר, אם היקף האיסור השני רחב יותר ומוסיף על האיסור הראשון עוד אנשים שלא היו אסורים בשל האיסור הראשון — הרי הוא חל.","ושואלים: \u0003תינח\u0004 \u0005[נניח]\u0006 דבר זה \u0003היכא\u0004 \u0005[היכן,\u0006 כאשר\u0005]\u0006 \u0003נשא\u0004 תחילה האח ה\u0003חי\u0004 אשה, ואז נאסרה אחותה עליו משום אחות אשה, \u0003ואחר כך נשא\u0004 האח ש\u0003מת\u0004 את אחותה, שאז אפשר לומר: \u0003מגו דאתוסף\u0004 \u0005[מתוך שנוסף]\u0006 \u0003איסור לגבי אחים,\u0004 שהרי בתחילה היו שאר האחים (חוץ ממנו) מותרים באותה אחות, וכאשר נשא אותה אחיהם נוסף בה איסור (אשת אח) לגבי האחים, על כן \u0003אתוסף איסור לגבי דידיה\u0004 \u0005[נוסף איסור גם לגביו],\u0006 והוא הקרוי איסור מוסיף.","\u0003אלא היכא\u0004 \u0005[היכן,\u0006 במקום\u0005]\u0006 ש\u0003נשא\u0004 קודם האח ש\u0003מת\u0004 את האשה, שקודם היה קיים על כל האחים איסור אשת אח ו\u0003אחר כך נשא\u0004 האח ה\u0003חי\u0004 את אחותה, \u0003מאי\u0004 \u0005[מה]\u0006 \u0003איסור מוסיף איכא\u0004 \u0005[יש\u0006 כאן\u0005]?\u0006 שהרי לא נוספו אנשים אחרים הנאסרים מכוח הנישואין עם אחותה, שהרי האיסור בזה (אחות אשתו) חל רק עליו ולא על אדם נוסף!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003מגו דאיתסר בכולה אחוותא\u0004 \u0005[מתוך שנאסר בכל האחיות],\u0006 שהרי קודם לכן, כאשר נשא אחיו אחת מן האחיות, היו כל השאר מותרות לו, וכאשר נשא הוא עצמו אחות אחרת — נאסר בכל שאר האחיות, ואם כן בגלל שנשא את האשה נוסף בכך איסור עליו. אולם, \u0003האי\u0004 \u0005[זה]\u0006 הרי אינו נקרא איסור מוסיף אלא \u0003איסור כולל הוא.\u0004 כלומר, שאיסור זה כולל ומוסיף על אותו אדם עצמו צדדים אסורים. אבל אינו קרוי איסור מוסיף — משום שאינו מוסיף איסור לגבי אנשים אחרים.","\u0003אלא אמר רבא:\u0004 מה שאמר ר' יוסי בברייתא שחייב משום אשת אח ומשום אחות אשה, כוונתו: \u0003מעלה\u0004 (מחשיב) \u0003אני עליו כאילו עשה שתים,\u0004 שהרי עבר בה משום שני איסורים \u0003ו\u0004אכן \u0003אינו חייב\u0004 מבחינת דיני אדם \u0003אלא אחת. וכן כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן: מעלה אני עליו כאילו עשה שתים, ואינו חייב אלא אחת.\u0004 ושואלים: \u0003מאי נפקא מינא\u0004 \u0005[מה יוצא מזה],\u0006 אם מחשיבים לו כאילו עשה שתים? ומשיבים: \u0003לקברו בין רשעים גמורים.\u0004 שכשם שאין קוברים צדיק אצל רשע, כך אין קוברים רשע אצל רשע גדול ממנו, ומי שעשה עבירה זו נחשב כאילו עשה שתי עבירות ולא אחת והרי הוא רשע יותר.","\u0003ו\u0004מעירים, שבעיה זו של איסור חל על איסור, ובאיזה אופן הוא חל \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 היא שנויה. \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 בברייתא שנחלקו חכמים בשאלה זו: \u0003זר\u0004 (מי שאינו כהן), \u0003ששימש\u0004 ועבד אחת מעבודות הקודש, כגון שהקטיר עולה על גבי המזבח \u0003בשבת,\u0004 מה דינו? \u0003ר' חייא אומר: חייב שתים,\u0004 הן משום זר ששימש במקדש, והן כמחלל שבת. \u0003בר קפרא אומר: אין חייב אלא אחת. קפץ ר' חייא ונשבע: העבודה!\u0004 (כלומר, נשבע בעבודת בית המקדש), \u0003כך שמעתי מרבי\u0004 (יהודה הנשיא) שאמר בענין זה: שחייב \u0003שתים. קפץ בר קפרא ונשבע: העבודה! כך שמעתי מרבי:\u0004 שחייב \u0003אחת.\u0004","כיון שאי אפשר היה להוכיח מן המסורת, \u0003התחיל ר' חייא לדון\u0004 ולנתח את הדבר מבחינה הגיונית: מלאכת \u0003שבת — לכל נאסרה, כשהותרה\u0004 מלאכה זו \u0003במקדש\u0004 בעבודת הקודש — רק \u0003אצל כהנים הותרה\u0004. משמע: \u0003לכהנים הותרה, ולא לזרים,\u0004 ולכן, כשעשה הזר עבודה בשבת \u0003יש כאן\u0004 עבירה \u0003משום זרות, ויש כאן\u0004 גם \u0003משום\u0004 חילול \u0003שבת. התחיל בר קפרא לדון\u0004 לצד אחר: \u0003שבת לכל נאסרה, כשהותרה במקדש — הותרה,\u0004 שהמשמש במקדש (בהיתר) — הותרה לו שבת. אם כן נמצא ש\u0003אין כאן אלא\u0004 משום \u0003זרות,\u0004 שהרי אם היה איש זה כהן היה מותר בעבודה, ואי אפשר לדונו משום מחלל שבת.","כיוצא בו נחלקו בבעיה דומה: כהן \u0003בעל מום ששימש\u0004 במקדש, ועשה עבודה \u0003בטומאה\u0004 בקרבן ציבור הדוחה טומאה. \u0003ר' חייא אומר: חייב שתים,\u0004 הן משום שהוא בעל מום, והן משום שהוא טמא. \u0003בר קפרא אומר: אין חייב אלא אחת\u0004 (משום בעל מום). \u0003קפץ ר' חייא ונשבע: העבודה! כך שמעתי מרבי\u0004 שחייב \u0003שתים. קפץ בר קפרא ונשבע: העבודה! כך שמעתי מרבי:\u0004 חייב \u0003אחת.\u0004","\u0003התחיל ר' חייא לדון: טומאה לכל נאסרה,\u0004 שכל הטמאים אסורים להיכנס למקדש, \u0003כשהותרה\u0004 הטומאה \u0003במקדש,\u0004 כשכל הציבור כולו טמא — \u0003אצל כהנים תמימים\u0004 (שאינם בעלי מום) \u0003הותרה,\u0004 ורק \u0003לכהנים תמימים הותרה, ולא לבעלי מומין.\u0004 ואם אותו בעל מום שימש בטומאה — \u0003יש כאן\u0004 עבירה \u0003משום בעלי מומין, ויש כאן\u0004 עבירה \u0003משום טומאה. התחיל בר קפרא לדון\u0004 לצד אחר: \u0003טומאה לכל נאסרה, כשהותרה במקדש — הותרה,\u0004 והבעיה היתה איפוא רק בשל היות הכהן בעל מום, נמצא כי \u0003אין כאן אלא\u0004 רק \u0003משום בעל מום.\u0004","וכן נחלקו בשאלה נוספת: \u0003זר,\u0004 שאינו כהן, \u0003שאכל מליקה\u0004 חטאת העוף, שאין שוחטים אותה אלא מולקים אותה מן העורף, והיא מותרת לכהנים, אבל כל עוף מלוק אחר אסור משום נבילה, שהרי הומת בלא שחיטה. והשאלה היא: אם זר אכל חטאת מלוקה כזו, מה דינו. \u0003ר' חייא אומר: חייב שתים\u0004 משום זר שאכל קרבן הנאכל רק לכהנים, ומשום נבילה. \u0003בר קפרא אומר: אין חייב אלא אחת. קפץ ר' חייא ונשבע: העבודה! כך שמעתי מרבי: שתים. קפץ בר קפרא ונשבע: העבודה! כך שמעתי מרבי: אחת.\u0004","\u0003התחיל ר' חייא לדון: נבלה לכל נאסרה, כשהותרה במקדש — אצל כהנים הותרה,\u0004 כלומר, רק לכהנים בלבד. וכיון ש\u0003לכהנים הותרה ולא לזרים — יש כאן משום זרות,\u0004 דהיינו: זר שאוכל חטאת, \u0003ויש כאן משום מליקה —\u0004 שאוכל נבילה. \u0003התחיל בר קפרא לדון: נבילה לכל נאסרה,\u0004 ו\u0003כשהותרה במקדש — הותרה\u0004 לכולם, ו\u0003אין כאן\u0004 אם כן \u0003אלא\u0004 רק \u0003משום זרות,\u0004 שהרי אם כהן היה — לא היה בכך איסור."],["\u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עיקרון הם \u0005חלוקים]?\u0006 — \u0003ב\u0004בעיה של \u0003איסור כולל\u0004 חלוקים הם, \u0003ואליבא\u0004 \u0005[ועל פי שיטתו]\u0006 של \u0003ר' יוסי. ר' חייא סבר\u0004 כי לדעת \u0003ר' יוסי באיסור כולל מיחייב תרתי\u0004 \u0005[חייב שתים],\u0006 \u0003בר קפרא סבר: לא מיחייב\u0004 \u0005[אינו חייב]\u0006 לדעת ר' יוסי \u0003אלא חדא\u0004 \u0005[אחת],\u0006 ולא חייב ר' יוסי שניים אלא במקום שיש איסור מוסיף.","ושואלים: \u0003ומאי\u0004 \u0005[ומה]\u0006 \u0003איסור כולל איכא הכא\u0004 \u0005[יש כאן]\u0006 בנושאים אלה? \u0003בשלמא\u0004 \u0005[נניח]\u0006 במקרה של \u0003זר\u0004 ששימש בשבת, אפשר לומר כך: \u0003מעיקרא שרי\u0004 \u0005[מתחילה\u0006 הלא הוא \u0005מותר]\u0006 \u0003ב\u0004שאר \u0003מלאכה\u0004 בימות החול \u0003ואסור בעבודה\u0004 שבמקדש, \u0003אתיא\u0004 \u0005[באה]\u0006 \u0003לה שבת, מגו דקא מיתסר\u0004 \u0005[מתוך ש\u0006הוא \u0005נאסר]\u0006 \u0003במלאכה\u0004 מכל מקום בגלל שבת — \u0003מיתסר נמי\u0004 \u0005[נאסר גם כן]\u0006 \u0003בעבודה\u0004 שבמקדש בגלל שבת, שאפשר לומר שעל העבודה הזו נוסף איסור שבת, והוא איסור הכולל גם מלאכה שמחוץ למקדש.","וכן בענין \u0003בעל מום\u0004 ששימש בטומאה, שהרי \u0003מעיקרא\u0004 \u0005[מתחילה],\u0006 לפני שנטמא, היה \u0003שרי\u0004 \u0005[מותר]\u0006 \u0003באכילה\u0004 מן הקדשים (שכהן בעל מום מותר באכילת קדשים. ויקרא כא, כג) \u0003ואסור בעבודה,\u0004 ככל כהן בעל מום. \u0003איטמי ליה\u0004 \u0005[\u0006כאשר \u0005נטמא לו],\u0006 \u0003מגו דקא מיתסר\u0004 \u0005[מתוך שהוא נאסר]\u0006 \u0003באכילה\u0004 — \u0003מיתסר נמי\u0004 \u0005[נאסר גם כן]\u0006 \u0003בעבודה\u0004 משום טומאה, וזה הוא האיסור הכולל שבדבר. \u0003אלא מליקה — בבת אחת היא דמשכחת לה\u0004 \u0005[הוא שאתה מוצא אותה],\u0006 שאיסור הזרות ואיסור הנבילה חלים בבת אחת על העוף, שכל עוד לא נמלקה לא היתה אסורה אלא משום מעילה, ולא חל עליה איסור זרות אלא משעת מליקה, שמשעה זו ואילך היא מסורה לכהנים, אבל \u0003באיסור כולל לא משכחת לה\u0004 \u0005[אין אתה מוצא אותה]\u0006 שהרי לא היה כאן איסור ראשון שחל תחילה, אלא שני האיסורים באו בבת אחת.","\u0003אלא\u0004 יש לחזור מן ההסבר שאמרנו, ולומר כי \u0003קמפלגי\u0004 \u0005[חולקים הם]\u0006 הרי זה \u0003באיסור בבת אחת, ואליבא\u0004 \u0005[ועל פי שיטתו]\u0006 של \u0003ר' יוסי. ר' חייא סבר\u0004 כי לדעת \u0003ר' יוסי באיסור\u0004 ב\u0003בת אחת מיחייב תרתי\u0004 \u0005[חייב שתים],\u0006 \u0003ובר קפרא סבר: לא מיחייב\u0004 \u0005[אינו חייב]\u0006 לשיטת ר' יוסי \u0003אלא חדא\u0004 \u0005[אחת].\u0006","אולם גם לשיטה זו יש לשאול: \u0003והכא, מאי\u0004 \u0005[וכאן, מה]\u0006 \u0003איסור\u0004 ב\u0003בת אחת איכא הכא\u0004 \u0005[יש כאן]?\u0006 שהרי בשני המקרים הקודמים חלים האיסורים בזה אחר זה, ולא בבת אחת! ומשיבים, יש להסביר כך: לענין \u0003זר ששימש בשבת — כגון דאייתי\u0004 \u0005[שהביא]\u0006 אדם זה \u0003שתי שערות\u0004 של סימן בגרות \u0003בשבת,\u0004 וקודם לכן, מכיון שהיה קטן — לא היה חייב כלל, ולכן \u0003דהויא להו\u0004 \u0005[שהרי הם]\u0006 איסורי \u0003זרות ושבת\u0004 חלים עליו שניהם \u0003בהדי הדדי\u0004 \u0005[ביחד].\u0006","\u0003בעל מום נמי\u0004 \u0005[גם כן],\u0006 \u0003כגון דאייתי\u0004 \u0005[שהביא]\u0006 בו ביום \u0003שתי שערות ואיטמי ליה\u0004 \u0005[ונטמא לו],\u0006 כלומר, שתחילה נטמא ובתוך טומאתו ומומו הביא שתי שערות, \u0003דהויא ליה\u0004 \u0005[שהיתה לו]\u0006 בשעת הבאת השערות חלות של איסור \u0003בעל מום ו\u0004איסור \u0003טומאה בהדי הדדי\u0004 \u0005[ביחד].\u0006 \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003שחתך אצבעו בסכין טמאה,\u0004 שהחיתוך והסרת האצבע עשו אותו גם בעל מום וגם טמא בבת אחת.","לאחר שביררנו את שורש המחלוקת דנים בדבר מצד אחר, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' חייא\u0004 יכול הוא להסביר את חילוקי הדעות בינו לבין בר קפרא בדרך זו: \u0003כי אתנייה לדידיה\u0004 \u0005[כאשר לימד\u0006 רבי \u0005אותו]\u0006 היה זה \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' יוסי,\u0004 שר' יוסי סבור שיש מקרים שאיסור חל על איסור. ו\u0003כי אתנייה\u0004 \u0005[\u0006ו\u0005כאשר לימד\u0006 רבי\u0005]\u0006 \u0003לבר קפרא\u0004 היה זה \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' שמעון\u0004 שאין איסור חל כלל על איסור. ולכן יכול היה ר' חייא להבין מדוע עומד בר קפרא על דעתו, שהרי הוא מספר דבר שאירע באמת, אלא שר' חייא סבר שבר קפרא לא הבין שרבי לא אמר את דבריו לשיטת ר' יוסי. \u0003אלא ל\u0004דעת \u0003בר קפרא,\u0004 וכי \u0003ר' חייא שקורי קא משקר\u0004 \u0005[משקר\u0006 הוא\u0005]?\u0006 שנשבע ששמע מפי רבי דברים שלא היו?","\u0003אלא\u0004 יש להסביר באופן אחר: \u0003קמיפלגי\u0004 \u0005[חולקים]\u0006 ר' חייא ובר קפרא \u0003באיסור בת אחת,\u0004 שחלו שני איסורים בבת אחת, \u0003ואליבא\u0004 \u0005[ועל פי שיטתו]\u0006 של \u0003ר' שמעון,\u0004 שיש מקום לומר שכאשר באו שני האיסורים יחד מודה ר' שמעון שהם חלים. אולם אף להסבר זה יש מקום לשאול: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003לר' חייא,\u0004 מובן כי \u0003קא מישתבע לאפוקי\u0004 \u0005[נשבע\u0006 כדי \u0005להוציא]\u0006 את \u0003ר' שמעון מחזקיה\u0004 \u0005[מחזקתו],\u0006 שהרי אנו יודעים שר' שמעון סבור שאין איסור חל על איסור, ולכן נשבע ר' חייא להדגיש שאף על פי כן, כשחלים האיסורים בבת אחת — מודה אף ר' שמעון שאיסור חל על איסור. \u0003אלא לבר קפרא למה ליה לאשתבועי\u0004 \u0005[לו להישבע]?\u0006 די היה לו לעמוד בדבריו, שהרי זו היא דעת ר' שמעון! ומעירים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר.","ויש לשאול גם מצד אחר: לפי הסבר זה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003בר קפרא, כי אתנייה רבי לדידיה\u0004 \u0005[כאשר לימד רבי אותו],\u0006 היה זה \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' שמעון\u0004 האומר שאין איסור חל על איסור. ו\u0003כי אתנייה\u0004 \u0005[\u0006ו\u0005כאשר לימדו]\u0006 \u0003לר' חייא\u0004 היה זה \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' יוסי,\u0004 ולכן ר' חייא באמת נשבע, אלא שהחליף את השיטות. \u0003אלא ל\u0004דעת \u0003ר' חייא\u0004 שאף לר' שמעון חייב שתיים באיסור בבת אחת, וכי \u0003בר קפרא שקורי קא משקר\u0004 \u0005[משקר\u0006 הוא\u0005]?\u0006 שאין דבריו לא כר' שמעון ולא כר' יוסי!","ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003ר' חייא:\u0004 בר קפרא ודאי לא שיקר, אלא טעה, וכך היה הדבר: \u0003כי אתנייה רבי לדידיה\u0004 \u0005[כאשר שנה רבי לו],\u0006 לבר קפרא, לא על הכל שנה לו כן, אלא \u0003תרתי\u0004 \u0005[שניהם]\u0006 \u0003לפטור אתנייה\u0004 \u0005[לימד אותו],\u0006 בשני המקרים שיש בהם איסור כולל — בזר ששימש בשבת, ובעל מום ששימש בטומאה, ואמר לו כי במקרים אלה ר' שמעון מחייב רק אחת, שהרי לפי מה שהסברנו כעת, ר' שמעון סבור שאיסור חל על איסור רק באיסור בבת אחת, ולא באיסור כולל,"],["\u0003ו\u0004גם בענין \u0003איסור כולל אתנייה\u0004 \u0005[שנה לו]\u0006 שאם היה מקרה של איסור כולל, יש לפטור, \u0003ואליבא\u0004 \u0005[ועל פי שיטתו]\u0006 של \u0003ר' שמעון. וחזיא\u0004 \u0005[וראה]\u0006 \u0003לבר קפרא\u0004 מקרה של \u0003זר שאכל מליקה, ואיידי דדמיא לה, ערבה בהדייהו\u0004 \u0005[ומתוך שהיא דומה\u0006 לשאלות הקודמות \u0005לה, ערב אותה אתן],\u0006 ולאחר זמן היה נדמה לו שבאמת שמע את כולן יחד מפי רבי, \u0003ועיין בה\u0004 בשאלה זו, \u0003ולא אשכח\u0004 \u0005[מצא]\u0006 שהיא יכולה להתקיים \u0003אלא\u0004 כשקרו הדברים \u0003בבת אחת.\u0004","\u0003וסבר מדהא\u0004 \u0005[מ\u0006תוך \u0005שזו]\u0006 \u0003בבת אחת,\u0004 שהרי איסור זר שאכל מליקה יכול להיות רק כשחלו האיסורים בבת אחת, \u0003הא נמי\u0004 \u0005[זו גם כן],\u0006 כלומר, גם האחרות, מדובר בהן כשהיו הדברים \u0003בבת אחת. ומדהנך\u0004 \u0005[ומ\u0006כיון \u0005שאלו]\u0006 שמע אותם \u0003לפטור, הנך נמי\u0004 \u0005[אלה גם כן]\u0006 \u0003לפטור.\u0004 ואם כן לדעת ר' חייא לא שיקר בר קפרא ביודעין, אלא שמע דברים מסויימים מפי רבי, ובטעות ערב בהם עניינים אחרים, ומתוך כך גרם לעצמו שבילבל את הנושאים.","לעיקרם של דברי בר קפרא \u0003מיתיבי\u0004 \u0005[מקשים],\u0006 שנינו: \u0003זר ששימש בשבת, ובעל מום ששימש בטומאה — יש כאן משום זרות, ומשום שבת, ומשום בעל מום, ומשום טומאה,\u0004 אלו \u0003דברי ר' יוסי. ר' שמעון אומר: אין כאן אלא משום זרות ובעל מום בלבד.\u0004 ומדייקים: \u0003ואילו\u0004 את השאלה לגבי זר שאכל \u0003מליקה שיירה\u0004 \u0005[שייר אותה]\u0006 ולא מנה אותה בין הדברים השנויים במחלוקת זו.","ומעתה נדון: \u0003למאן שיירה\u0004 \u0005[ל\u0006פי שיטת \u0005מי שייר אותה],\u0006 כלומר, לדעת מי מן התנאים אין שאלה זו שייכת לכאן? \u0003אילימא\u0004 \u0005[אם\u0006 תרצה \u0005לומר]\u0006 שהיא \u0003ל\u0004שיטת \u0003ר' יוסי, השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 לדעת \u0003ר' יוסי\u0004 אפילו \u0003באיסור כולל מיחייב\u0004 \u0005[חייב]\u0006 \u0003שתים,\u0004 כמו שאמרנו בענין זר ששימש בשבת, ואם כן — \u0003באיסור בת אחת מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר שהוא מחייב שתים? \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מוכח מכאן שהסיבה ששייר מקרה זה ולא שנה אותו כאן היא \u0003ל\u0004דעת \u0003ר' שמעון. ו\u0004כך יש לומר: אכן \u0003באיסור כולל הוא דפטר\u0004 \u0005[שפוטר]\u0006 ר' שמעון, \u0003אבל באיסור בבת אחת —\u0004 גם לר' שמעון \u0003מיחייב\u0004 \u0005[חייב]\u0006 שתים. ומכאן אם כן \u0003תיובתא\u0004 \u0005[קושיה\u0006 חמורה\u0005]\u0006 על דברי \u0003בר קפרא!\u0004 ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה\u0006 היא\u0005]\u0006 ונדחו דבריו.","על פרט אחד מאותם דינים שואלים: הזכרנו \u0003זר ששימש בשבת,\u0004 והשאלה היא: \u0003במאי\u0004 \u0005[במה]\u0006 שימש, איזו עבודה עשה? \u0003אי\u0004 \u0005[אם]\u0006 תאמר שהמדובר \u0003בשחיטה\u0004 ששחט הזר את הקרבן — הלא \u0003שחיטה בזר כשרה,\u0004 וכיון שכך אין כאן משום זרות. \u0003ואי\u0004 \u0005[ואם]\u0006 תאמר שהמדובר \u0003בקבלה והולכה,\u0004 שקיבל את הדם או הוליך את המזרק המכיל דם אל המזבח — אמנם יש פה משום זר שעשה עבודת כהונה, אבל מבחינת שבת \u0003טלטול בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא,\u0004 ואין בכך איסור מלאכה בשבת מן התורה.","\u0003אי\u0004 \u0005[אם]\u0006 תאמר, ששימש \u0003בהקטרה,\u0004 ששרף את הקרבן על המזבח, אולם הרי דיון זה הוא לשיטת ר' יוסי, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוסי\u0004 ש\u0003הבערה\u0004 שנאמרה בתורה (\"לא תבערו אש בכל מושבותיכם ביום השבת\". שמות לה, ג) \u0003ללאו יצאתה.\u0004 כלומר, שהיא יוצאת מכלל כל המלאכות האסורות בשבת, שבכולן יש חיוב מיתה בעשייתן במזיד, וחיוב חטאת בעשייתן בשוגג, וזו אין בה אלא איסור לאו בלבד, ומדוע אמר ר' יוסי שחייב שתי חטאות?","\u0003אמר רב אחא בר יעקב:\u0004 מדובר כאן \u0003בשחיטת פרו של כהן גדול\u0004 ביום הכיפורים. ששחיטה ודאי מלאכה גמורה היא. \u0003וכדברי האומר שחיטת פרו של כהן גדול בזר פסולה.\u0004 שעבודה זו מיוחדת לכהן הגדול בלבד. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שמדובר בשחיטת פר כהן גדול, \u0003מאי איריא\u0004 \u0005[מה שייך],\u0006 מדוע דווקא \u0003זר? אפילו כהן הדיוט\u0004 ששחט אותה \u0003נמי\u0004 \u0005[גם כן]\u0006 נחשב כזר ויחולו עליו אותם איסורים! ומשיבים: אכן, אפשר לפרש \u0003שזר אצלו קאמר\u0004 \u0005[אמר],\u0006 כלומר, אין מדובר דווקא בזר ממש, שאיננו כהן כלל, אלא בכל מי שעבודה זו היא זרה אצלו, ואפילו הוא כהן הדיוט.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי:\u0004 קושיה זו שהקשינו שאין כאן מלאכה גמורה — אינה קושיה, שהרי \u0003מידי\u0004 \u0005[וכי]\u0006 מספר \u0003חטאות קתני\u0004 \u0005[שנה]\u0006 כאן, \u0003או לאוי קתני\u0004 \u0005[לאוים שנה]?!\u0006 \u0003אלא איסורי בעלמא קא חשיב\u0004 \u0005[איסורים בלבד הוא מונה],\u0006 כמה איסורים יש בפעולה מסויימת, בלי לדון בחומרתם של איסורים אלה. ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מכאן]\u0006 ומה זה משנה כמה איסורים יש? ומשיבים: \u0003לקוברו בין רשעים גמורים.\u0004 שאם עבר עבירה כפולה כזו הרי הוא רשע בשני דברים, וצריך לנהוג בו כפי שנוהגים ברשע גמור.","\u0003שנים שקידשו שתי נשים, ובשעת כניסתן לחופה\u0004 אחרי האירוסין \u0003החליפו את\u0004 אשתו \u0003של זה לזה, ואת של זה לזה — הרי אלו חייבין משום אשת איש,\u0004 שהרי כל אחד בא על אשת חבירו. \u0003ואם היו אחין\u0004 — הרי הם חייבים גם \u0003משום אשת אח, ואם היו\u0004 נשים אלה \u0003אחיות\u0004 — חייבים גם \u0003משום \"אשה אל אחותה\". ואם היו נדות —\u0004 חייבים גם \u0003משום נדה.\u0004","\u0003ו\u0004לאחר ביאה זו \u0003מפרישין אותן\u0004 הנשים מבעליהן \u0003שלשה חדשים, שמא מעוברות הן\u0004 מאותה ביאה של איסור. כדי שאפשר יהיה להבחין בילד שנולד מביאה זו, שממזר הוא. \u0003ואם היו קטנות שאינן ראויות לילד — מחזירים אותן מיד\u0004 לבעליהן הראויים. \u0003ואם היו כהנות\u0004 (בנות כהנים), הרי \u0003נפסלו\u0004 בכך \u0003מן התרומה,\u0004 משום שכל אחת נבעלה בעילת זנות ואסורה לכהן, ופסולה מלאכול בתרומה.","שנינו במשנה: \u0003החליפו\u0004 את של זה לזה. ושואלים: \u0003מידי ברשיעי עסקינן\u0004 \u0005[וכי ברשעים\u0006 כאלה \u0005עוסקים אנו]\u0006 שמחליפים את נשותיהם בכוונה?! \u0003ותו\u0004 \u0005[ועוד]:\u0006 אם עשו זאת בכוונה תחילה — \u0003הא דתני\u0004 \u0005[זו ששנה]\u0006 \u0003ר' חייא\u0004 בענין זה: \u0003הרי כאן שש עשרה חטאות\u0004 (ארבע חטאות לכל אחד מן הגברים, וכן לכל אחת מן הנשים), אם מונים את כל הקרבנות שהבעלים והנשים נתחייבו בהם — ולפי זה, \u0003אי\u0004 \u0005[אם]\u0006 עשו זאת \u0003במזיד מי איכא\u0004 \u0005[האם יש]\u0006 כאן \u0003קרבן?\u0004 שהרי אין מביאים קרבן אלא על השגגה! \u0003אמר רב יהודה: תני\u0004 \u0005[שנה]\u0006 כאן \u0003\"הוחלפו\",\u0004 כלומר, לא שהחליפו בזדון, אלא התחלפו להם הנשים בטעות.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר, \u0003דקתני סיפא\u0004 \u0005[ש\u0006כן \u0005שנה בסוף\u0006 המשנה\u0005]:\u0006 \u0003אם היו קטנות שאינן ראויות לילד — מחזירין אותן מיד. ואי\u0004 \u0005[ואם]\u0006 היה הדבר \u0003במזיד, מי שריא\u0004 \u0005[האם מותר]\u0006 להחזיר אשה שזינתה? ומעירים: \u0003הא לא קשיא\u0004 \u0005[זה איננו קשה],\u0006 שגם אם היה הדבר במזיד, כיון שהיו נשים אלה קטנות, הלא \u0003פיתוי קטנה\u0004 כ\u0003אונס נינהו\u0004 \u0005[הוא]\u0006 נחשב, \u0003ואונס בישראל,\u0004 כלומר, אנוסה לגבי ישראל \u0003מישרא שרי\u0004 \u0005[מותרת]\u0006 היא.","\u0003אלא\u0004 יש לדייק זאת מצד אחר: \u0003דקתני\u0004 \u0005[ששנה]\u0006 שם: \u0003מפרישין אותן שלשה חדשים שמא מעוברות הן,\u0004 ומכאן נסיק: \u0003הא לאו\u0004 \u0005[הרי אם לא]\u0006 היו \u0003מעוברות,\u0004 שהתברר אחר שלושה חדשים שאינן מעוברות — \u0003שריין\u0004 \u0005[מותרות\u0006 הן\u0005]\u0006 לבעלים, \u0003ואי\u0004 \u0005[ואם]\u0006 היה הדבר \u0003במזיד, מי שרי\u0004 \u0005[האם מותר]?\u0006 \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי מדובר פה ב\u0003הוחלפו\u0004 בשגגה. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא הדבר."],["\u0003ולשיטת ר' חייא, שכל אחד מהם חייב ארבע חטאות, מאן האי תנא\u0004 \u0005[מי הוא תנא זה]\u0006 \u0003דאית ליה\u0004 \u0005[שיש לו,\u0006 שהוא סבור\u0005]\u0006 שאיסור חל על איסור גם ב\u0003איסור כולל ו\u0004גם ב\u0003איסור מוסיף ו\u0004גם ב\u0003איסור בת אחת?\u0004 שאם היו אלה אחים — ברגע שקידש אחד מהם אשה, נאסרה אותה אשה על האח השני בבת אחת משום אשת איש ומשום אשת אח. וכאשר האח האחר קידש את אחותה — יש כאן איסור כולל, שהרי על ידי קדושיה הוא נאסר לא רק באחות אשתו שהיא אשת אחיו, אלא גם בשאר האחיות. ולאחר זמן כשנעשתה נידה, הרי היא אסורה אז אפילו לבעלה משום נידה, והרי זה איסור מוסיף. ומי הוא התנא שסובר שאיסור חל על איסור בכולם?","\u0003אמר רב יהודה אמר רב:\u0004 שיטת \u0003ר' מאיר היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 ברייתא\u0005]:\u0006 \u0003יש אוכל אכילה אחת וחייב עליה,\u0004 על אותה אכילה עצמה \u0003ארבע חטאות ו\u0004קרבן \u0003אשם אחד.\u0004","כיצד? אם היה כהן \u0003טמא שאכל חלב, והוא,\u0004 אותו חלב, \u0003נותר מן המוקדשין, ביום הכיפורים.\u0004 שחייב חטאת אחת משום טמא שאכל מן המוקדשים, וחטאת אחרת משום שאכל נותר, ועוד חטאת משום שאכל ביום הכיפורים, ועוד חטאת אחרת משום שאכל חלב. וכיון שבאכילה זו נהנה מן הקדשים, הריהו חייב גם משום מעילה, וצריך להביא לכפרתו קרבן אשם. וחלב זה היה אסור מלידתה של הבהמה, ומשהקדישה, חל על כל הבהמה איסור מוקדשים ונאסרה אף בהנאה — הרי איסור מוסיף. וכשנטמא הכהן הזה ונאסר בכל הקדשים הרי כאן עוד איסור כולל. וכיון שנעשה נותר, נאסר גם למזבח — הרי כאן עוד איסור מוסיף, וביום הכיפורים חל איסור כולל נוסף, שהרי ביום הכיפורים אסור באכילה אף בחולין.","\u0003ר' מאיר אומר: אם היתה\u0004 זו \u0003שבת והוציאו בפיו\u0004 מרשות לרשות תוך כדי אכילה — הרי זה \u0003חייב\u0004 גם משום שבת. שכיון ששבת ויום הכיפורים חלו בזמן אחד, חייב גם משום איסור שבת, והרי כאן שני איסורים שחלו בבת אחת. \u0003אמרו לו: אינו מן השם.\u0004 כלומר, תוספת זו שאתה מוסיף לענין שבת איננה מאותו נושא של שאר הדברים שאמרנו, כי האיסורים האחרים נעשים כולם בעצם פעולת האכילה, וכאן האיסור הוא משום הוצאה. ומכל מקום מוכח שר' מאיר סבור שאיסור חל על איסור בכל הצדדים הללו.","ויש לשאול לענין משנתנו: \u0003ור' מאיר,\u0004 אף שבכלל סובר הוא שבאופן כזה חל איסור על איסור, אולם באופן כזה שכוונתו היתה לדבר מצוה, לשאת אשה, שאף בכך אומרים שאיסור חל על איסור, \u0003אליבא דמאן\u0004 \u0005[לפי שיטתו של מי]\u0006 מרבותיו אמר זאת? \u0003אי אליבא\u0004 \u0005[אם\u0006 תאמר \u0005לפי שיטתו]\u0006 של \u0003ר' יהושע\u0004 אמר זאת, \u0003האמר\u0004 \u0005[הרי אמר]\u0006 ר' יהושע, שמי ש\u0003טעה בדבר מצוה,\u0004 וחשב שהוא עושה מצוה, ותוך כדי כך עשה בשגגה עבירה שחייבים עליה חטאת, הרי זה \u0003פטור.\u0004 ואף כאן, כיון שאותם אנשים שנתחלפו נשותיהם טעו בדבר מצוה, שהרי חשבו לקיים מצות נישואין, צריכים היו להיות פטורים מחטאת! \u0003אלא\u0004 יש לומר שאמר זאת \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' אליעזר,\u0004 שגם הטועה בדבר מצוה ועבר — חייב חטאת.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 תירוץ אחר: \u0003לעולם\u0004 אפילו \u0003אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' יהושע\u0004 אמר כן, אלא, \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' יהושע\u0004 שמי ש\u0003טעה בדבר מצוה פטור — הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים \u0003גבי תינוקות.\u0004 כגון שנתחלפו למוהל תינוקות שהיה צריך למול, ומל בשבת בטעות תינוק שעדיין לא הגיע זמנו למול, שלא קיים מצות מילה, והיה צריך להתחייב משום מלאכה בשבת, שפוטר אותו ר' יהושע — משום ש\u0003זמנו בהול,\u0004 כיון שזמן מילה כדינה הוא רק באותו יום, היה בהול וטרוד לעשותה, ומכיון שהוא בהול, טעה, שחשב שהגיע זמנו בשבת, \u0003אבל האי\u0004 \u0005[זה]\u0006 שטעה בנישואין, \u0003כיון\u0004 ש\u0003אין זמנו בהול,\u0004 יתכן שבאופן כזה \u0003לא\u0004 פטר ר' יהושע.","ומקשים: \u0003והרי\u0004 אכילת \u0003תרומה,\u0004 ש\u0003אין זמנה בהול, ו\u0004בכל זאת \u0003קפטר\u0004 \u0005[פוטר]\u0006 ר' יהושע את הטועה בעשיית מצוה, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003היה\u0004 כהן \u0003אוכל בתרומה ונודע\u0004 לו \u0003שהוא\u0004 פסול לכהונה, כגון שהוא \u0003בן גרושה או בן חלוצה,\u0004 ונמצא שהוא כזר שאכל תרומה בשגגה, \u0003ר' אליעזר מחייב\u0004 אותו שישלם גם \u0003קרן\u0004 כדין זר שאכל תרומה \u0003ו\u0004גם \u0003חומש,\u0004 שזר האוכל תרומה בשוגג משלם לכהן את מחירה ומוסיף חומש. \u0003ור' יהושע פוטר,\u0004 כיון שבשעת אכילה סבר שהוא עוסק בדבר מצוה, שהוא כהן האוכל תרומה.","ודוחים: \u0003הא איתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר עליה]\u0006 על משנה זו: \u0003אמר רב ביבי בר אביי: הכא\u0004 \u0005[כאן]\u0006 \u0003בתרומה\u0004 של חמץ שהיה אותו כהן אוכל אותה \u0003בערב הפסח עסקינן\u0004 \u0005[עוסקים אנו]\u0006 ש\u0003זמנה בהול,\u0004 שהוא ממהר לאוכלה, כדי שלא תישאר ויצטרכו לשורפה.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר שונה לכל הענין, שמשנתנו אינה עוסקת באיסור כולל או איסור מוסיף, אלא \u0003באיסור בת אחת, ואליבא\u0004 \u0005[ועל פי]\u0006 שיטתו של \u0003ר' שמעון,\u0004 שבבת אחת אף הוא מודה שחייב שנים.","ושואלים: \u0003בשלמא כולהו\u0004 \u0005[נניח\u0006 את \u0005כולם]\u0006 את שאר האיסורים \u0003משכחת להו\u0004 \u0005[יכול אתה למצוא אותם]\u0006 שיחולו כולם בבת אחת, כיצד — \u0003דשוינהו\u0004 \u0005[שמינו]\u0006 \u0003שליח\u0004 אחד שיקדש להם נשים, \u0003ושוו אינהו\u0004 \u0005[ומינו הן,\u0006 הנשים\u0005]\u0006 \u0003שליח\u0004 שיקבל עבורן קידושין, \u0003ופגע\u0004 \u0005[ופגש]\u0006 \u0003שליח בשליח,\u0004 וקידש את שתי האחיות לשני האחים, ונמצא שחלו כל האיסורים באותו רגע עצמו. \u0003אלא\u0004 שיהיו גם \u0003נדות\u0004 בבת אחת בשעת הקידושין \u0003היכי משכחת לה\u0004 \u0005[כיצד יכול אתה למצוא זאת]?\u0006","\u0003אמר רב עמרם אמר רב:\u0004 מדובר כאן \u0003ב\u0004מצב שהיו הנשים \u0003שופעות\u0004 דם נדה \u0003מתוך\u0004 שנת \u0003שלשה עשר\u0004 ללידת בעליהן עד \u0003לאחר\u0004 שנהיו בני \u0003שלשה עשר לאחיובי אינהו\u0004 \u0005[לחייב אותם]\u0006 את האחים, שברגע שבו הגיעו לבגרות וחלו הקדושין היו הנשים נידות, ואותו זמן היה \u0003מתוך\u0004 שנת \u0003שנים עשר לאחר שנים עשר\u0004 של גיל הנשים, \u0003לחיובי אינהי\u0004 \u0005[לחייב אותן].\u0006 כלומר, רק אם נולדו הבעלים ונשותיהן באותו תאריך (בהבדל של שנה) ובדיוק ביום שבו הגברים הגיעו לגיל בגרות (שלוש עשרה) הגיעו גם הנשים לבגרותן (שתים עשרה), ואם היו באותו זמן נידות, הרי חלו כל האיסורים בבת אחת וחייבים על כולם, גם לדעת ר' שמעון.","שנינו במשנה ש \u0003מפרישים אותן\u0004 שלושה חדשים שמא מעוברות הן. ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 אנו יודעים ש\u0003אין אשה\u0004 בתולה \u0003מתעברת בביאה ראשונה! אמר ר' נחמן אמר רבה בר אבהו:\u0004 מדובר כאן \u0003שבעלו ושנו\u0004 (וחזרו ובעלו), ויש אפשרות שהתעברו בבעילה השניה. ושואלים: אם כן, \u0003ואלא הא דתנא\u0004 \u0005[זו ששנה]\u0006 \u0003ר' חייא: הרי כאן שש עשרה חטאות,\u0004 ואם היו שם שתי בעילות אם כן \u0003תלתין ותרתין הויין\u0004 \u0005[שלושים ושתים הן],\u0006 שכל איסור נעשה פעמיים!","ומשיבים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאתה מחשיב כל ביאה להתחייב חטאת עליה בנפרד — הלא \u0003ל\u0004דעת \u0003ר' אליעזר,\u0004 ש\u0003מחייב\u0004 חטאת בביאה אחת \u0003על כל כח וכח\u0004 על כל תנועה ותנועה שבביאה — אם כן \u0003טובא הויין\u0004 \u0005[הרבה הם]\u0006 האיסורים שישנם, שהרי הוא מכפיל את מספר החטאות פי כמה. \u0003אלא\u0004 ודאי לדעת ר' אליעזר יש לומר שרק את האיסורים שנעשו \u0003בכח ראשון קחשיב\u0004 \u0005[הוא מונה],\u0006 \u0003הכי נמי\u0004 \u0005[כך גם כן],\u0006 אף לדעת חכמים, יש לומר, כי רק את האיסורים של ה\u0003ביאה\u0004 ה\u0003ראשונה קחשיב\u0004 \u0005[הוא מונה].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן:\u0004"],["\u0003והא\u0004 \u0005[והרי]\u0006 \u0003תמר בביאה ראשונה איעברא\u0004 \u0005[נתעברה]\u0006 שמקובל שתמר היתה עדיין בתולה כשבא עליה יהודה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תמר באצבע מעכה\u0004 את הבתולים, לפני הביאה, ולכן נתעברה בביאה ראשונה. ש\u0003אמר ר' יצחק: כל מועכות של בית רבי\u0004 שנוהגות למעוך את בתוליהן — \u0003תמר שמן,\u0004 כלומר, מכנים אותן תמר, \u0003ולמה נקרא שמן תמר — על שם תמר שמעכה באצבעה.\u0004 על עצם הראיה מתמר תוהים: \u0003והא הוו\u0004 \u0005[והרי היו]\u0006 \u0003ער ואונן\u0004 שהיו בעליה קודם לכן ולא היה איפוא לתמר למעוך את בתוליה לפני שבא עליה יהודה! ומשיבים: \u0003\"ער ואונן\" שמשו שלא כדרכן\u0004 (בפי הטבעת), ולכן היתה עדיין בתולה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: אשה שילדה, \u0003כל עשרים וארבעה חדש\u0004 שהתינוק יונק, בעלה \u0003דש\u0004 (בועל) \u0003מבפנים, וזורה\u0004 את הזרע \u0003מבחוץ,\u0004 כדי שהאשה לא תתעבר, שאם תתעבר ייפסק חלבה, ועלול התינוק למות. אלו \u0003דברי ר' אליעזר. אמרו לו:\u0004 דברים \u0003הללו\u0004 שאתה מציע לעשות \u0003אינו אלא כמעשה ער ואונן\u0004 ואסור לעשותם! ועל כל פנים משמע מכאן שער ואונן באו עליה כדרכה, אלא שלא גמרו את ביאתם!","ומשיבים: כוונת הדברים היתה שהם נהגו \u0003כמעשה ער ואונן\u0004 מבחינה מסויימת, \u0003ו\u0004אולם \u0003לא כמעשה ער ואונן\u0004 לגמרי. ומפרטים: \u0003כמעשה ער ואונן\u0004 מבחינת השחתת הזרע, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והיה אם בא אל אשת אחיו ושחת ארצה\u0004 לבלתי נתן זרע לאחיו\u0003\"\u0004 (בראשית לח, ט), \u0003ו\u0004אולם \u0003לא כמעשה ער ואונן\u0004 בדיוק, ש\u0003אילו התם\u0004 \u0005[שם]\u0006 בער ואונן היתה הביאה \u0003שלא כדרכה, והכא\u0004 \u0005[וכאן]\u0006 מדובר בביאה \u0003כדרכה.\u0004","ושואלים שוב לעצם המעשה: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003אונן\u0004 שבא עליה שלא כרגיל, יודעים ממה \u0003דכתיב ביה\u0004 \u0005[שנאמר בו]\u0006 \u0003\"ושחת ארצה\"\u0004 (שם), \u0003אלא ער מנלן\u0004 \u0005[מניין לנו]\u0006 שבא עליה שלא כדרכה? \u0003אמר רב נחמן בר יצחק: דכתיב\u0004 \u0005[שנאמר]\u0006 באונן \u0003\"וימת גם אתו\"\u0004 (בראשית לח, י), כלומר, \u0003אף הוא באותה מיתה מת,\u0004 על שעבר אותה עבירה שעבר אחיו. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003אונן\u0004 בא עליה שלא כדרכה, שלא רצה שתלד \u0003משום\u0004 שידע ש\u0003\"לא לו יהיה הזרע\"\u0004 (בראשית לח, ט), אלא יהיה נחשב אחרי אחיו המת, \u0003אלא ער מאי טעמא עבד הכי\u0004 \u0005[מה טעם עשה כך]?\u0006 ומשיבים: \u0003כדי שלא תתעבר ויכחיש\u0004 (ויתמעט) \u0003יופיה\u0004 בהריון.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 נאמר: \"ואשה אשר ישכב איש אותה שכבת זרע ורחצו במים\" (ויקרא טו, יח). ומדייקים: \u0003\"אותה\"\u0004 הוא מיעוט, \u0003פרט לכלה,\u0004 שביאתה בפעם הראשונה אינה מחייבת טבילה, אלו \u0003דברי ר' יהודה. וחכמים אומרים: פרט ל\u0004ביאה \u0003שלא כדרכה,\u0004 שביאה שלא כדרכה אינה מחייבת טבילה. \u0003אמר ליה\u0004 החכם \u0003הון בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן לרב נחמן\u0004 אביו: \u0003לימא קא סבר\u0004 \u0005[האם לומר שסבור]\u0006 \u0003ר' יהודה: התורה חסה על תכשיטי\u0004 (איפור) \u0003כלה,\u0004 שלא יתקלקלו מחמת המים, ולפיכך פטרוה מטבילה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 לא זה הטעם, אלא \u0003לפי שאין אשה מתעברת מביאה ראשונה,\u0004 ולכן אין ביאה כזו מטמאה, שאינה שכיבה הראויה לזרע.","ומוסיפים: \u0003במאי קמיפלגי\u0004 \u0005[במה חלוקים]\u0006 ר' יהודה וחכמים — \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 שמה שנאמר \u0003\"שכבת זרע\"\u0004 משמעו \u0003פרט להעראה,\u0004 שהיא ביאה לא גמורה ובלא הוצאת זרע, והמיעוט \u0003\"אותה\"\u0004 משמעו \u0003פרט לשלא כדרכה. ו\u0004אילו \u0003ר' יהודה סבר: שלא כדרכה והעראה\u0004 שניהם \u0003מ\u0004ן המיעוט \u0003\"שכבת זרע\" נפקא\u0004 \u0005[יוצאים,\u0006 נלמדים\u0005]\u0006 שאין זו שכיבה העשויה להביא להולדה (\"זרע\"), \u0003\"אותה\"\u0004 שנאמר — \u0003פרט לכלה\u0004.","אגב דברים אלה, בענין ביאה שאינה ראויה להולדה, מביאים: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל \u0003אמר\u0004 בשם \u0003ר' יוחנן: כל\u0004 אשה \u0003ששהתה אחר\u0004 שמת \u0003בעלה\u0004 או שנתגרשה ממנו \u0003עשר שנים\u0004 בלא תשמיש \u0003ונשאת — שוב אינה יולדת. אמר רב נחמן: לא שנו\u0004 דבר זה \u0003אלא שאין דעתה להנשא, אבל\u0004 אם \u0003דעתה\u0004 במשך הזמן \u0003להנשא — מתעברת\u0004 לאחר מכן. \u0003אמר ליה רבא ל\u0004אשתו, \u0003בת רב חסדא: קא מרנני רבנן אבתריך\u0004 \u0005[מרננים חכמים אחריך],\u0006 שכן בין הזמן שנתאלמנה עד לזמן שנשאה רבא עברו יותר מעשר שנים והיא ילדה לו בכל זאת ילדים, ולכאורה נראה ששימשה בינתיים! \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אנא דעתאי עלך הואי\u0004 \u0005[אני דעתי עליך היתה],\u0006 שמסופר שכבר בהיותה ילדה נתנבאה שתינשא לו, ולכן אף לאחר שהייה ארוכה זו ילדתי לך.","מסופר: \u0003ההיא דאתיא לקמיה\u0004 \u0005[\u0006אשה אחת \u0005שבאה לפני]\u0006 \u0003רב יוסף, אמרה לו: רבי, אנא\u0004 \u0005[אני]\u0006 \u0003שהיתי אחר בעלי עשר שנים ו\u0004בכל זאת \u0003ילדתי! אמר לה: בתי, אל תוציאי לעז על דברי חכמים. אמרה ליה\u0004 \u0005[לו]\u0006 והודתה: \u0003לגוי נבעלתי\u0004 בתוך הזמן הזה, ואם כן אין בכך סתירה לדברי חכמים.","\u0003אמר שמואל: וכולן,\u0004 כל הנשים שנבעלו — ויש חשש שנתעברו, \u0003צריכות להמתין שלשה חדשים\u0004 לפני שהן נישאות, כדי להבחין בין ילד שנולד מביאה קודמת לזה שנולד מן הנישואין, \u0003חוץ מגיורת\u0004 קטנה \u0003ומשוחררת קטנה,\u0004 שאף שייתכן שנבעלו, מכל מקום כיון שהן קטנות אינן יכולות להרות. \u0003אבל קטנה בת ישראל\u0004 שנבעלה \u0003צריכה להמתין שלשה חדשים.\u0004","ושואלים: \u0003ובמאי\u0004 \u0005[ובמה]\u0006 באיזו קטנה מדובר? \u0003אי\u0004 \u0005[אם]\u0006 שיצאה \u0003במיאון\u0004 שהיתה נשואה (נישואין מדברי סופרים) ומיאנה בבעלה, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל דלא בעיא\u0004 \u0005[ש\u0006הממאנת \u0005אינה צריכה]\u0006 להמתין, \u0003ואי\u0004 \u0005[ואם]\u0006 יצאה \u0003בגט,\u0004 שנתגרשה אותה קטנה — \u0003האמרה\u0004 \u0005[הרי\u0006 כבר \u0005אמר אותה]\u0006 \u0003שמואל\u0004 את ההלכה הזו \u0003חדא זימנא\u0004 \u0005[פעם אחת]\u0006 ומדוע חזר ואמר? שכן \u0003אמר שמואל: מיאנה בו\u0004 הקטנה בבעלה — \u0003אינה צריכה להמתין שלשה חדשים\u0004 לנישואין השניים, אבל אם \u0003נתן לה גט — צריכה להמתין שלשה חדשים,\u0004 כדי לא להבדיל בין גרושה גדולה לגרושה קטנה! \u0003אלא\u0004 צריך לומר שמדובר כאן שנבעלה אותה קטנה \u0003בזנות,\u0004"],["\u0003וגזרו רבנן\u0004 \u0005[חכמים]\u0006 ב\u0003קטנה משום גדולה\u0004 שזינתה, וצריכה הפרשה.","ושואלים: \u0003ומי גזרינן\u0004 \u0005[והאם גוזרים אנו]\u0006 ב\u0003קטנה משום גדולה? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003אם היו קטנות שאינן ראויות לילד — מחזירין אותן מיד.\u0004 משמע שאין חוששים כלל לענין הפרשה ואף אין גוזרים! \u0003אמר רב גידל אמר רב:\u0004 דבר זה שאמרו במשנה רק \u0003הוראת שעה היתה.\u0004 ותוהים: \u0003מכלל\u0004 הדברים אתה למד \u0003דהואי\u0004 \u0005[שהיה]\u0006 מאורע כזה? שהלא מלשון המשנה ברור שמדובר באפשרות בלבד, ולא במעשה שהיה, שכן אם אירע מעשה שכזה היה לה למשנה לציינו! \u0003אלא\u0004 יש לומר: \u0003כהוראת שעה היתה,\u0004 שבמקרה כזה אין גוזרים. \u0003ו\u0004הטעם לכך הוא כי \u0003חילוף\u0004 כגון זה שבמשנה, שהחליפו את נשותיהם, \u0003לא שכיח\u0004 \u0005[אינו מצוי],\u0006 ובדבר שאינו מצוי אין חכמים גוזרים בקטנה.","\u0003לישנא אחרינא אמרי לה\u0004 \u0005[\u0006ב\u0005לשון אחרת אומרים זאת]\u0006 את ההלכה ש\u0003אמר שמואל: כולן צריכות להמתין שלשה חדשים, חוץ מגיורת ומשוחררת גדולה,\u0004 שאינן ממתינות. \u0003אבל קטנה בת ישראל\u0004 בכל מקרה \u0003אינה צריכה להמתין שלשה חדשים.\u0004 ומבררים: \u0003במאי\u0004 \u0005[במה]\u0006 בדיוק מדובר? \u0003אי\u0004 \u0005[אם]\u0006 בקטנה שיצאה מבעלה \u0003במיאון — האמרה\u0004 \u0005[הרי\u0006 כבר \u0005אמר אותה]\u0006 \u0003שמואל חדא זימנא\u0004 \u0005[פעם אחת].\u0006 \u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 ביוצאה \u0003בגט,\u0004 שנתגרשה — \u0003הא קאמר\u0004 \u0005[הרי אמר]\u0006 \u0003שמואל דבעיא\u0004 \u0005[ש\u0006היא \u0005צריכה],\u0006 להמתין! ש\u0003אמר שמואל: מיאנה בו — אינה צריכה להמתין שלשה חדשים, נתן לה גט — צריכה להמתין שלשה חדשים! אלא\u0004 יש לומר שמדובר \u0003בזנות, וזנות בקטנה לא שכיח\u0004 \u0005[אינו מצוי],\u0006 ובדבר שאינו מצוי לא גזרו חכמים. ושואלים: \u0003גיורת ו\u0004שפחה \u0003משוחררת דשכיח בהו\u0004 \u0005[שמצוי בהן]\u0006 \u0003זנות\u0004 בהיותן גויות או שפחות, \u0003ליגזור\u0004 \u0005[שנגזור]\u0006 עליהן להמתין שלושה חדשים! ומשיבים: שמואל \u0003הוא\u0004 ש\u0003אמר\u0004 ופסק \u0003כ\u0004שיטת \u0003ר' יוסי. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הגיורת, והשבויה\u0004 (שיש מקום לחשוש שנאנסה בזמן שביה) \u0003והשפחה, שנפדו\u0004 או \u0003שנתגיירו\u0004 או \u0003שנשתחררו — צריכות להמתין שלשה חדשים\u0004 עד שתינשאנה, אלו \u0003דברי ר' יהודה. ר' יוסי מתיר\u0004 להן \u0003ליארס ולינשא מיד. אמר רבה: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוסי — קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003אשה\u0004 כשהיא \u0003מזנה משמשת במוך\u0004 שמניחה בבית הרחם \u0003כדי שלא תתעבר,\u0004 ולכן אין לחשוש שהרתה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: בשלמא\u0004 \u0005[נניח]\u0006 \u0003גיורת\u0004 אפשר להבין שהיא עושה כך, \u0003כיון\u0004 ש\u0003דעתה לאיגיורי\u0004 \u0005[להתגייר],\u0006 \u0003מנטרה נפשה\u0004 \u0005[\u0006היא \u0005שומרת את עצמה]\u0006 שלא תתעבר בעודה גויה, \u0003כדי להבחין בין זרע שנזרע בקדושה,\u0004 כלומר, ילדים שיוולדו לה לאחר גיור \u0003ובין זרע שנזרע שלא בקדושה. שבויה ושפחה נמי\u0004 \u0005[גם כן]\u0006 אפשר לומר שהן נזהרות מאותו טעם, \u0003דשמעי ממרייהו\u0004 \u0005[ששומעות מאדוניהן]\u0006 שהם רוצים לשחררן או שעומדים לפדות אותן, \u0003ומנטרי נפשייהו\u0004 \u0005[ושומרות את עצמן]\u0006 שלא תתעברנה במצב זה. \u0003אלא\u0004 שפחה ה\u0003יוצאת בשן ועין,\u0004 כלומר, שנשתחררה משום שפגע בה אדוניה ופגם באחד מעשרים וארבעה ראשי איברים שלה, כגון בשן או בעין, \u0003היכי משכחת לה\u0004 \u0005[איך אתה מוצא אותה]\u0006 שתיזהר בעצמה? והרי אינה יודעת על כך מראש, ואינה נשמרת שלא להתעבר!","","","\u0003וכי תימא כל דממילא\u0004 \u0005[ואם תאמר כל\u0006 דבר \u0005ש\u0006בא \u0005מעצמו],\u0006 כגון כאן שהשחרור בא מעצמו שלא מדעתה, \u0003מודה ר' יוסי\u0004 שצריכה להמתין — \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אנוסה ומפותה צריכה להמתין שלשה חדשים\u0004 שמא נתעברה, אלו \u0003דברי ר' יהודה, ר' יוסי מתיר ליארס ולינשא מיד.\u0004 והרי האנוסה בודאי לא הכינה את עצמה קודם שלא תתעבר!","\u0003אלא אמר אביי: אשה מזנה מתהפכת\u0004 לאחר ביאה, ומשתדלת שהזרע לא ייקלט, כדי \u0003שלא תתעבר,\u0004 וכך נוהגת גם השפחה. ושואלים: אם כן הדבר, שהיא משתדלת שלא תתעבר, \u0003ואידך\u0004 \u0005[והאחר]\u0006 מדוע בכל זאת מצריך להפרישן? ומשיבים: \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא לא נתהפכה יפה יפה\u0004 ובשל כך תתעבר.","שנינו במשנה: \u0003ואם היו כהנות\u0004 נפסלו מן התרומה, ותוהים: \u0003כהנות\u0004 (בנות כהנים) — \u0003אין\u0004 \u0005[כן],\u0006 \u0003ישראלית — לא,\u0004 והרי גם ישראליות הנשואות לכהנים, שאוכלות מתרומת בעליהן, צריכות להיפסל, שהלא אשת כהן שנאנסה אסורה לבעלה! ומשיבים: \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003אם היו נשי כהנים\u0004 הרי הן נפסלות. ומדייקים: \u0003נשי כהנים — אין\u0004 \u0005[כן]\u0006 נפסלו לבעליהן, \u0003נשי ישראלים — לא,\u0004 שאם ימותו בעליהן תהיינה כשרות להינשא לכהנים ולאכול תרומה,","ועל כך מקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב עמרם: הא מילתא\u0004 \u0005[דבר זה]\u0006 \u0003אמר לן\u0004 \u0005[לנו]\u0006 \u0003רב ששת ואנהרינהו לעיינין ממתניתין\u0004 \u0005[והאיר את עינינו ממשנתנו]\u0006 להראות לנו שדבריו רמוזים במשנה (להלן יבמות נג, ב). וכך אמר: \u0003אשת ישראל שנאנסה, אף על פי שמותרת לבעלה\u0004 בכל זאת \u0003פסולה לכהונה,\u0004 כלומר להינשא לכהן, אם בעלה זה ימות, שאמנם מותרת היא לבעלה, אבל לענין כהונה נפסלה אף על ידי אונס.","\u0003אמר רבא: הכי קאמר\u0004 \u0005[כך אמר]\u0006 התנא במשנה: \u0003אם היו כהנות נשואות לישראל נפסלו מן התרומה דבי נשייהו\u0004 \u0005[של בית אביהן]\u0006 שגם אם ימותו בעליהן בלא בנים — שוב אינן יכולות לחזור לאכול בתרומה בבית אביהן (שלא כשאר בנות כהנים, שאם יצאו מבעליהן הישראלים בלא בנים כשרות לאכול בתרומה) משום שנפסלו על ידי ביאת איסור.",""],["\u0003החולץ ליבמתו ונמצאת\u0004 שהיתה \u0003מעוברת\u0004 בשעת החליצה \u0003וילדה\u0004 אחר כך, \u0003בזמן שהולד\u0004 שנולד \u0003של קיימא\u0004 (שלא היה נפל ולא היה צורך כלל בחליצה) — \u0003הוא,\u0004 החולץ, \u0003מותר בקרובותיה והיא מותרת בקרוביו,\u0004 שכן לא היתה זו חליצה כלל, ואין הם נחשבים כקרובים כלל. \u0003ו\u0004אף \u0003לא פסלה מן הכהונה\u0004 כחלוצה, אלא היא כאלמנה רגילה.","\u0003אין הולד של קיימא\u0004 והוברר שאכן היתה צריכה לחלוץ — כיון שחלצה, \u0003הוא אסור בקרובותיה והיא אסורה בקרוביו ופסלה מן הכהונה.\u0004","\u0003הכונס\u0004 (נושא לאשה) \u0003את יבמתו ונמצאת\u0004 שהיתה \u0003מעוברת\u0004 בזמן שכנסה, \u0003וילדה, בזמן שהולד של קיימא — יוציא\u0004 את האשה הזו, שהרי היא אשת אחיו האסורה לו, \u0003וחייבין\u0004 שניהם \u0003בקרבן\u0004 חטאת משום ששגגו בעבירה חמורה שחייבים על זדונה כרת.","\u0003ואם אין\u0004 ה\u0003ולד של קיימא — יקיים\u0004 אותה כאשתו.","נולד ילד, אלא שהוא \u0003ספק בן תשעה\u0004 חודשים \u0003ל\u0004אח ה\u0003ראשון\u0004 שמת, \u0003ספק בן שבעה לאחרון — יוציא, והולד כשר.\u0004 שבין שהוולד הוא מהבעל הראשון ובין שהוא מהבעל השני (היבם) לא היתה עבירה ביצירתו. \u0003וחייבין באשם תלוי\u0004 ככל מי שעבר עבירה שעל ודאי מביא חטאת ועל ספק — אשם תלוי.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בנושא זה: \u0003החולץ למעוברת ו\u0004אחר כך \u0003הפילה. ר' יוחנן אמר: אינה צריכה חליצה מן האחין\u0004 משום שנתברר לאחר מעשה שחליצתה כשירה היתה. \u0003ריש לקיש אמר: צריכה חליצה\u0004 נוספת \u0003מן האחין,\u0004 משום שהחליצה הראשונה לא נעשתה כראוי.","ומבארים, \u0003ר' יוחנן אמר: אינה צריכה חליצה מן האחין,\u0004 כי \u0003חליצת מעוברת שמה חליצה\u0004 וחליצה כשירה היא, אלא אם כן יתברר לאחר מכן שילדה ילד חי, \u0003ו\u0004כן \u0003ביאת מעוברת\u0004 שהפילה לאחר מכן — \u0003שמה ביאה,\u0004 וקיים בה מצות ייבום. \u0003וריש לקיש אמר: צריכה חליצה מן האחין,\u0004 כי \u0003חליצת מעוברת לא שמה חליצה, וביאת מעוברת לא שמה ביאה,\u0004 ולכן אין החליצה הזו, או הביאה הזו, פוטרת יבמה זו (וכן את צרותיה) מזיקת הייבום.","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון \u0005הם חלוקים]?\u0006 ומשיבים: \u0003איבעית אימא קרא, ואיבעית אימא סברא\u0004 \u0005[אם תרצה אמור\u0006 שחולקים בפירוש \u0005הכתוב, ואם תרצה אמור\u0006 ב\u0005סברה].\u0006","ומפרטים, \u0003איבעית אימא סברא\u0004 \u0005[אם תרצה אמור\u0006 שחלוקים ב\u0005סברה]\u0006 זו: \u0003ר' יוחנן סבר: אם יבא אליהו\u0004 בשעת החליצה \u0003ויאמר דהא דאיעברא מפולי מפלה\u0004 \u0005[שזו ש\u0006היא \u0005מעוברת\u0006 בו \u0005תפיל\u0006 אותו\u0005],\u0006 \u0003מי לאו\u0004 \u0005[האם לא]\u0006 \u0003בת חליצה ויבום היא?\u0004 וכיון שכך, \u0003השתא נמי תגלי מילתא\u0004 \u0005[עכשיו גם כן יתגלה הדבר]\u0006 \u0003למפרע,\u0004 שמאחר שהפילה לבסוף, אנחנו אומרים שכבר אז זה לא היה ההריון ממש, וממילא היתה חליצתה חליצה, וביאתה ביאה כשירה.","\u0003וריש לקיש אמר: תגלי מילתא\u0004 \u0005[יתגלה הדבר]\u0006 \u0003למפרע לא אמרינן\u0004 \u0005[אין אנו אומרים],\u0006 שכיון שבאותה שעה לא היה הדבר ראוי, אף על פי שלאחר מעשה זה התברר — אין אנחנו אומרים שבירור זה כוחו יפה למפרע.","\u0003ואיבעית אימא קרא\u0004 \u0005[ואם תרצה אמור\u0006 שחולקים בפירוש \u0005הכתוב];\u0006 \u0003ר' יוחנן סבר:\u0004 הלא \u0003\"ובן אין לו\"\u0004 (דברים כה, ה) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003והא לית ליה\u0004 \u0005[והרי אין לו]\u0006 בסופו של דבר. \u0003וריש לקיש סבר:\u0004 שאת הביטוי \u0003\"ובן אין לו\"\u0004 כבר דרשוהו חכמים, ופרשוהו: \u0003עיין עליו.\u0004 כלומר, חפש בכל דרך, שמא יש לו בן באיזה מקום שהוא בעולם. ועובר זה הוא לפי שעה בגדר בן כלשהו, ולכן אין בה מצות ייבום.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 ממה ששנינו במשנתנו: \u0003אין הולד של קיימא — הוא אסור בקרובותיה, והיא אסורה בקרוביו ופסלה מן הכהונה.\u0004 ומעתה, \u0003בשלמא לדידי דאמינא\u0004 \u0005[נניח\u0006 \u0005ל\u0006שיטתי \u0005שלי שאני אומר]\u0006 כי \u0003חליצת מעוברת שמה חליצה — משום הכי\u0004 \u0005[כך]\u0006 \u0003פסלה\u0004 על ידי חליצה זו מן הכהונה, \u0003אלא לדידך דאמרת\u0004 \u0005[ל\u0006שיטתך \u0005שלך שאומר אתה]\u0006 כי \u0003חליצת מעוברת לא שמה חליצה, אמאי\u0004 \u0005[מדוע]\u0006 \u0003פסלה מן הכהונה?\u0004 הלא לשיטתך מה שעשה אינו נחשב כלל!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש לר' יוחנן: פסול זה לכהונה \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 הוא, \u0003ולחומרא בעלמא\u0004 \u0005[ולהחמיר בלבד]\u0006 שמא יבואו לטעות בכך.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 נוסח אחר: \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ריש לקיש לר' יוחנן:\u0004 שנינו \u0003אין הולד של קיימא — הוא אסור בקרובותיה, והיא אסורה בקרוביו, ופסלה מן הכהונה. בשלמא לדידי דאמינא\u0004 \u0005[נניח ל\u0006שיטתי \u0005שלי שאני אומר]\u0006 כי \u0003חליצת מעוברת לא שמה חליצה — היינו דקתני\u0004 \u0005[זהו ששנה]\u0006 \u0003\"פסלה מן הכהונה\" —\u0004 כוונתו \u0003לחומרא\u0004 בלבד שאנו מחמירים עליה, \u0003ולא קתני\u0004 \u0005[שנה]\u0006 \u0003\"אינה צריכה חליצה מן האחין\".\u0004 ומשמע שצריכה חליצה מן האחים לפי שהחליצה הראשונה חליצה פסולה היתה ולא הועילה כלל, אף שמחמירים בה לפוסלה בגלל חליצה זו מן הכהונה.","\u0003אלא לדידך\u0004 \u0005[ל\u0006שיטתך \u0005שלך]\u0006 שאתה אומר שחליצה מעוברת שמה חליצה, אם כן \u0003\"אינה צריכה חליצה מן האחין\" מיבעי ליה\u0004 \u0005[צריך\u0006 היה \u0005לו]\u0006 לומר! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן לריש לקיש: \u0003אין הכי נמי\u0004 \u0005[כן הוא גם כן],\u0006 שבאמת אינה צריכה חליצה מן האחים. \u0003ואיידי דתנא רישא\u0004 \u0005[ואגב ששנה\u0006 ב\u0005ראש\u0006 המשנה\u0005]\u0006 \u0003\"לא פסלה\" — תנא סיפא\u0004 \u0005[שנה\u0006 ב\u0005סופה]\u0006 \u0003\"פסלה\",\u0004 כדי להשלים את ההקבלה הסגנונית, אבל למעשה — פטורה לגמרי, ואינה צריכה חליצה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 ממה ששנינו בסיפא: \u0003אין הולד של קיימא — יקיים. בשלמא לדידי דאמינא\u0004 \u0005[נניח ל\u0006שיטתי \u0005שלי שאני אומר]\u0006 כי \u0003חליצת מעוברת שמה חליצה, וביאת מעוברת שמה ביאה — משום הכי\u0004 \u0005[כך]\u0006 \u0003קתני\u0004 \u0005[שנה]\u0006 \u0003יקיים.\u0004","\u0003אלא לדידך דאמרת\u0004 \u0005[ל\u0006שיטתך \u0005שלך שאתה אומר]\u0006 כי \u0003חליצת מעוברת לא שמה חליצה, וביאת מעוברת לא שמה ביאה,\u0004 הרי ביאתו הראשונה לא עשתה בה כל קנין ואם כן — \u0003\"יחזור ויבעול ויקיים\" מיבעי ליה\u0004 \u0005[צריך\u0006 היה \u0005לו]\u0006 לומר! ומשיב ריש לקיש: אכן, \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"יקיים\" — יחזור ויבעול ויקיים, דלא סגי\u0004 \u0005[שלא די]\u0006 להחשיבה כאשתו בלא ביאה נוספת לאחר שהפילה, אלא כיון שדרך העולם שאם יקיים אותה יבוא עליה — לא פירשו את הדבר. אבל חייב לעשות בה מעשה, ובלא זה אכן לא יקנה אותה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בנוסח אחר: \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ריש לקיש לר' יוחנן\u0004 ממה ששנינו במשנתנו: \u0003אין הולד של קיימא — יקיים. בשלמא לדידי דאמינא\u0004 \u0005[נניח ל\u0006שיטתי \u0005שלי שאני אומר]\u0006 כי \u0003חליצת מעוברת לא שמה חליצה, וביאת מעוברת לא שמה ביאה — היינו דקתני\u0004 \u0005[זהו ששנה]\u0006 \u0003\"יקיים\",\u0004 שפירושו: \u0003יחזור ויבעול ויקיים, דלא סגי בלאו הכי\u0004 \u0005[שלא די בלא זה]\u0006 וצריך לעשות בה מעשה של קנין כדי לקיימה ובלי זה גם לא תוכל להינשא לאחר,","\u0003אלא לדידך\u0004 \u0005[ל\u0006שיטתך \u0005שלך]\u0006 שכבר היא קנויה לו כאשתו — \u0003\"רצה יוציא, רצה יקיים\" מיבעי ליה\u0004 \u0005[צריך היה לו לומר],\u0006 שבודאי אינו חייב לקיימה, ויכול לגרשה לאחר שקנאה בביאתו הראשונה! השיב לו ר' יוחנן: \u0003אין הכי נמי\u0004 \u0005[כן, כך\u0006 הוא באמת \u0005גם כן]\u0006 אלא, \u0003איידי דתנא רישא\u0004 \u0005[אגב ששנה\u0006 ב\u0005תחילה]\u0006 \u0003\"יוציא\" — תנא נמי סיפא\u0004 \u0005[שנה גם כן\u0006 ב\u0005סופה]\u0006 \u0003\"יקיים\"\u0004 כדי לשמור על ההקבלה הלשונית.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 מברייתא על ר' יוחנן, שנינו: \u0003הכונס את יבמתו ונמצאת מעוברת — הרי זו לא תנשא צרתה\u0004 לאחר, \u0003שמא יהא ולד בן קיימא.\u0004 ותוהים תחילה על לשון הברייתא: \u0003אדרבה\u0004 (להיפך), \u0003כי הוי\u0004 \u0005[כאשר יהיה]\u0006 \u0003הולד בן קיימא,\u0004 הלא אז \u0003מיפטרה\u0004 \u0005[נפטרת]\u0006 \u0003צרתה,\u0004 שהרי מתברר שהיו למת בנים, ויכולה אלמנתו להינשא לכל מי שתרצה! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 ותקן את הגירסה כך: \u0003שמא לא יהא הולד בן קיימא,\u0004 וכיון שאז נתברר שלא היו למת בנים, הרי אף הצרה זקוקה לייבום.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר כשיטת ר' יוחנן ש\u0003ביאת מעוברת שמה ביאה, אמאי\u0004 \u0005[מדוע]\u0006 אם כן \u0003לא תנשא צרתה? תיפטר\u0004 \"הצרה\" \u0003בביאה של חבירתה\u0004 בכל מקרה; שאם הולד בן קיימא — הרי אין עליה חובת ייבום, ואם איננו בן קיימא — על כל פנים נפטרה על ידי ביאה של צרתה!","\u0003אמר אביי:\u0004 יש לתרץ כי \u0003בביאה\u0004 של יבמה מעוברת \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 \u0003דלא פטרה\u0004 \u0005[שאינה פוטרת],\u0006 \u0003כי פליגי\u0004 \u0005[כאשר חלוקים\u0006 הם\u0005]\u0006 הרי זה \u0003בחליצה.\u0004","ש\u0003ר' יוחנן סבר: חליצת מעוברת שמה חליצה,\u0004 אף ש\u0003ביאת מעוברת לא שמה ביאה.\u0004 ו\u0003ריש לקיש סבר: ביאת מעוברת לא שמה ביאה, ו\u0004כן \u0003חליצת מעוברת לא שמה חליצה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: מה נפשך\u0004 \u0005[רצונך],\u0006 כלומר, בכל דרך שתרצה להבין אי אפשר לומר כדבריך. שהרי \u0003אי\u0004 \u0005[אם]\u0006 \u0003ביאת מעוברת שמה ביאה,\u0004 שכיון שהפילה לבסוף כאילו לא היתה מעוברת — אם כן \u0003חליצת מעוברת\u0004 גם היא \u0003שמה חליצה. ואי\u0004 \u0005[ואם]\u0006 \u0003ביאת מעוברת לא שמה ביאה,\u0004 משום שאנחנו דנים לפי המצב כעת, וכעת הרי היא מעוברת, אם כן — \u0003חליצת מעוברת נמי\u0004 \u0005[גם כן]\u0006 \u0003לא שמה חליצה. דהא קיימא לן\u0004 \u0005[שהרי קיים לנו,\u0006 מוחזק בידינו\u0005],\u0006"],["ש\u0003כל העולה\u0004 (הראוי) \u0003ליבום\u0004 — \u0003עולה לחליצה, וכל שאין עולה ליבום — אינו עולה לחליצה.\u0004","\u0003אלא אמר רבא:\u0004 יש לדחות את מה שאמרנו, ו\u0003הכי קאמר\u0004 \u0005[\u0006ו\u0005כך אמר],\u0006 כך יש לתרץ את הברייתא לדעת ר' יוחנן: \u0003הכונס יבמתו ונמצאת מעוברת — הרי זו לא תנשא צרתה, שמא יהא ולד בן קיימא. וביאת מעוברת\u0004 שילדה ולד בן קיימא — לפי כולם \u0003לא שמה ביאה, וחליצת מעוברת לא שמה חליצה.\u0004 שהרי התברר למפרע שלא היה מקום לא לייבום ולא לחליצה. ומאחר שהביאה והחליצה לא היו כשרות — לא נפטרה הצרה באלו, \u0003ו\u0004אף אין הצרה נפטרת משום שיש ליבמה ולד במעיה כי \u0003הולד אינו פוטר עד שיצא לאויר העולם\u0004.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבא\u0004 במפורש: \u0003הכונס יבמתו ונמצאת מעוברת — הרי זו לא תנשא צרתה, שמא יהא ולד בן קיימא, ואין ביאה וחליצה פוטרת\u0004 אותה איפוא, \u0003אלא ולד פוטר. ו\u0004אולם אינה נפטרת מיד, ש\u0003הולד אין פוטרה עד שיצא לאויר העולם.\u0004","ומדייקים כאן: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 שיש לחשוש \u0003שמא יהא ולד בן קיימא הוא, הא\u0004 \u0005[הרי]\u0006 אם \u0003לא הוי\u0004 \u0005[יהיה]\u0006 \u0003ולד בן קיימא —\u0004 אפשר ללמוד מכאן כי \u0003מיפטר\u0004 \u0005[נפטרת]\u0006 \u0003צרתה,\u0004 ואם כן \u0003לימא תיהוי תיובתא\u0004 \u0005[\u0006האם \u0005נאמר\u0006 ש\u0005תהא\u0006 זאת \u0005קושיה חמורה]\u0006 ל\u0003ריש לקיש\u0004 הסבור שביאת מעוברת אינה ביאה אפילו כשהפילה לבסוף!","ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003ריש לקיש: הכי קתני\u0004 \u0005[כך שנה],\u0006 כך צריך לתקן בלשון ברייתא זו: \u0003הכונס יבמתו ונמצאת מעוברת — הרי זו לא תנשא צרתה, שמא לא יהא הולד בן קיימא, וחליצת מעוברת לא שמה חליצה וביאת מעוברת לא שמה ביאה.\u0004","\u0003ואם תאמר:\u0004 תיפטר הצרה משום ש\u0003הלך אחר רוב נשים, ו\u0004הלא \u0003רוב נשים ולד מעליא\u0004 \u0005[מעולה],\u0006 שלם ובר קיימא \u0003ילדן\u0004 \u0005[יולדות],\u0006 ונסמוך על כן להתיר את הצרה, על כך יש לומר שאינה נפטרת, כי \u0003ולד אין פוטר עד שיצא לאויר העולם.\u0004","\u0003אמר ר' אלעזר: אפשר איתא להא\u0004 \u0005[האם אפשר\u0006 ש\u0005יש\u0006 בסיס \u0005לזו]\u0006 שאמר \u0003ריש לקיש ולא תנן לה\u0004 \u0005[שנינו אותה]\u0006 \u0003במתניתין\u0004 \u0005[במשנתנו]?\u0006 \u0003נפק\u0004 \u0005[יצא]\u0006 מבית המדרש כדי לעיין בדבר, \u0003דק ואשכח\u0004 \u0005[דקדק ומצא],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003האשה שהלך בעלה וצרתה למדינת הים, ובאו ואמרו לה \"מת בעליך\" — הרי זו לא תנשא,\u0004 מפני שהיא חייבת בייבום, \u0003ו\u0004אף \u0003לא תתייבם, עד שתדע שמא מעוברת היא צרתה.\u0004","ומבררים: \u0003בשלמא יבומי\u0004 \u0005[נניח שייבום]\u0006 \u0003לא — שמא\u0004 מעוברת הצרה ו\u0003יהא ולד בן קיימא, ויפגע\u0004 איפוא היבם \u0003באיסור אשת אח דאורייתא\u0004 \u0005[שמן התורה],\u0006 ומחמת ספק זה אין מניחים לה להתייבם, \u0003אלא לא תחלוץ — אמאי\u0004 \u0005[מדוע]?\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 לגבי המקרה ש\u0003תחלוץ בתוך תשעה\u0004 חודשים למותו של בעלה \u0003ותנשא בתוך תשעה — לא\u0004 תעשה זאת, \u0003היינו\u0004 \u0005[זהו]\u0006 מטעם \u0003ספק\u0004 שאינה יודעת שמא תלד צרתה בן קיימא ואינה חליצה.","\u0003אלא\u0004 מדוע לא \u0003תחלוץ בתוך תשעה, ותנשא לאחר תשעה,\u0004 שמכל מקום יכולה להינשא. שאם ילדה צרתה בינתיים ולד בר קיימא — פטורה היא מייבום. ואם לאו — תצא משום החליצה. ומכאן ראיה שחליצה של יבמה מעוברת אינה חליצה, כריש לקיש.","ומקשים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 שחליצת מעוברת אינה חליצה, הלא גם לפי זה יש לה דרך אחרת: \u0003תחלוץ\u0004 האשה \u0003ו\u0004גם \u0003תנשא לאחר תשעה\u0004 ואז תיפטר לכל הדעות מזיקת הייבום!","\u0003אלא, בר מינה\u0004 \u0005[חוץ מזו]\u0006 מן המשנה \u0003ההיא\u0004 שיש לה טעם אחר. ש\u0003אביי בר אבא ורב חיננא בר אביי דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 שהטעם מדוע לא תינשא ולא תתייבם, הוא: לא תינשא לאחר חליצה מספק — \u0003שמא יהא ולד בן קיימא.\u0004 ואם תחלוץ — הרי נמצא שלא היתה כאן חליצה כלל, \u0003ונמצא אתה מצריכה כרוז לכהונה,\u0004 כלומר, יהא צריך להודיע לכל שאף שחלצו לה — היא כשרה לכהונה.","ושואלים: \u0003ולצרכה\u0004 \u0005[ונצריך אותה]\u0006 כרוז, ונתיר אותה! ומשיבים: \u0003דלמא איכא איניש דהוי\u0004 \u0005[שמא יש אדם שהיה\u0006 נוכח\u0005]\u0006 \u0003ב\u0004זמן ה\u0003חליצה ולא הוי\u0004 \u0005[היה]\u0006 \u0003ב\u0004זמן ה\u0003הכרזה ואתי למימר\u0004 \u0005[ויבוא לומר]:\u0006 \u0003קשרי חליצה\u0004 \u0005[מותרת חלוצה]\u0006 \u0003לכהן.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 אף מעצם הדברים אין ממשנה זו ראיה לריש לקיש: \u0003מידי\u0004 \u0005[וכי]\u0006 \u0003\"לא תחלוץ ולא תתייבם\" קתני\u0004 \u0005[שנה\u0006 במשנה\u0005]?\u0006 הלא רק \u0003\"לא תנשא ולא תתייבם\" קתני\u0004 \u0005[שנה]\u0006 ויש להבין ש\"לא \u0003תינשא\u0004\" הוא \u0003בלא חליצה, אבל אי חליץ\u0004 \u0005[אם יחלוץ]\u0006 \u0003לה — הכי נמי דשריא\u0004 \u0005[כך גם כן\u0006 יהיה שתהא \u0005מותרת],\u0006 ואין מכאן איפוא ראיה לריש לקיש.","מכל מקום \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ריש לקיש: החולץ למעוברת והפילה — צריכה חליצה מן האחין.\u0004 והרי זו הוכחה ברורה שהחליצה הראשונה חליצה פסולה היתה.","\u0003אמר רבא: הלכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003ריש לקיש\u0004 נגד ר' יוחנן \u0003בהני תלת\u0004 \u0005[בשלוש\u0006 מחלוקות \u0005אלו]:\u0006 \u0003חדא\u0004 \u0005[אחת] —\u0006 \u0003הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 בענין חליצה. \u0003אידך\u0004 \u0005[האחרת],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003המחלק נכסיו על פיו,\u0004 כלומר, מחלק בחייו את נכסיו בין צאצאיו, אם \u0003ריבה לאחד\u0004 מן הבנים \u0003ומיעט לאחד\u0004 מן הבנים \u0003ו\u0004כן אם \u0003השוה להם,\u0004 לשאר הבנים \u0003את הבכור\u0004 ולא נתן לו פי שניים — \u0003דבריו קיימין.\u0004 שכן בחייו יכול הוא לחלק את רכושו בכל אופן שירצה, שהוא כנותן מתנות.","\u0003ואם אמר\u0004 שהוא עושה זאת \u0003משום ירושה — לא אמר כלום.\u0004 שכן דבריו סותרים את דברי התורה בענין זה. ואם \u0003כתב\u0004 שטר צוואה, והיה כתוב בו \u0003בין בתחלה בין בסוף בין באמצע\u0004 ביטוי המתפרש שהוא מחלק את הנכסים הללו \u0003משום מתנה\u0004 (ולא בתור ירושה) — \u0003דבריו קיימין.\u0004 שהרי, כאמור, יכול הוא לתת בחייו מתנות כפי שירצה."],["\u0003ואמר ריש לקיש\u0004 בפירושה של משנה זו, שלא כדברי ר' יוחנן, שאם כתב בשטר צוואה נחלות שונות לאנשים אחדים, חלק במתנה וחלק בירושה — \u0003לעולם לא קנה\u0004 המקבל \u0003עד שיאמר \"פלוני ופלוני ירשו שדה פלונית ופלונית שנתתים להם במתנה וירשום\".\u0004 שלשון מתנה צריכה להיות צמודה לכל לשון ירושה שנאמרה בצוואה זו.","\u0003ואידך\u0004 \u0005[ו\u0006מחלוקת \u0005אחרת]\u0006 שנפסקה בה הלכה כריש לקיש, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הכותב כל נכסיו לבנו לאחר מותו.\u0004 כלומר, שנתן את כל נכסיו לבנו מהיום, על מנת שיינתנו לו הנכסים בפועל לאחר מיתה, ובינתיים האב נהנה מהם, אבל הכל יינתן לבן לאחר מותו. \u0003האב אינו יכול למכור\u0004 נכסים אלה לאחר — \u0003מפני שנתנן לבן, והבן אינו יכול למכור — מפני שהן\u0004 עדיין \u0003ברשות האב.\u0004 אם \u0003מכר האב\u0004 את הנכסים — \u0003מכורין\u0004 הם והלוקח נהנה מפירותיהם \u0003עד שימות הוא\u0004 (האב), אם \u0003מכר הבן\u0004 את הנכסים בחיי האב — \u0003אין ללוקח כלום\u0004 בהם \u0003עד שימות האב.\u0004","\u0003ואיתמר\u0004 \u0005[ונאמר]\u0006 שנחלקו אמוראים בשאלה זו: \u0003מכר הבן בחיי האב, ומת הבן בחיי האב,\u0004 ואחר כך מת האב. \u0003ר' יוחנן אמר: לא קנה לוקח\u0004 כלום, \u0003וריש לקיש אמר: קנה לוקח.\u0004","ומסבירים את טעמיהם: \u0003ר' יוחנן אמר: לא קנה לוקח,\u0004 כי \u0003קנין פירות\u0004 שיש לאב בשדה זה, זכות הנאה מן הפירות — \u0003כקנין הגוף דמי\u0004 \u0005[נחשב],\u0006 נמצא שגופו של השדה לא היה שייך לבן כל עוד האב חי, ומכירתו אינה מכירה.","\u0003וריש לקיש אמר: קנה לוקח,\u0004 כי \u0003קנין פירות לאו\u0004 \u0005[לא]\u0006 \u0003כקנין הגוף דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 אלא הוא קנין לעצמו. ולכן אף שלאב היה קנין פירות בשדה, כיון שגוף השדה היה קנוי לבן, לכך מה שמכר — מכר, והמכירה חלה במותו של האב.","שנינו במשנה שמי שכנס את אשת אחיו והיתה מעוברת, ונתברר כי \u0003אין הולד של קיימא כו' —\u0004 יקיים את האשה הזו כאשתו, על אף שתחילת קניינו לא היתה בהיתר. \u0003תנא\u0004 \u0005[שנה\u0006 החכם בברייתא\u0005]:\u0006 \u0003משום ר' אליעזר אמרו\u0004 שיטה אחרת, שאף על פי שנמצא לבסוף שהוולד אינו של קיימא והיתה איפוא מותרת לו — כיון שהיה לו לחשוש שמא יהיה הוולד של קיימא ולהמנע מלכונסה, לכך קנסוהו ש\u0003יוציא בגט.\u0004","\u0003אמר רבא: ר' מאיר ור' אליעזר אמרו דבר אחד,\u0004 כלומר: בשיטה אחת הם עומדים, שמי שנשא אשה באיסור, אף שאיסור זה בטל — עליו לגרשה משום קנס. שיטת \u0003ר' אליעזר — הא דאמרן\u0004 \u0005[זו שאמרנו].\u0006","שיטת \u0003ר' מאיר\u0004 מהי — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא ישא אדם מעוברת חבירו,\u0004 כלומר, אשה שהיא הרה לאדם אחר, או \u0003מינקת חבירו\u0004 שמניקה ילד שילדה לאחר. \u0003ואם נשא — יוציא ולא יחזיר עולמית,\u0004 מפני שעבר על דברי חכמים, אלו \u0003דברי ר' מאיר. וחכמים אומרים: יוציא\u0004 אותה לפי שעה, \u0003וכשיגיע זמנו לכנוס,\u0004 כלומר, לאחר שתגמול את בנה — \u0003יכנוס.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ממאי\u0004 \u0005[ממה]\u0006 אתה מסיק שיש פה שיטה אחת? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003לא היא\u0004 ויש הבדל ביניהם, כי \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' אליעזר הכא\u0004 \u0005[כאן]\u0006 \u0003אלא משום דקפגע\u0004 \u0005[שפוגע]\u0006 כשנושא אותה \u0003באיסור אשת אח\u0004 שהוא איסור \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 אם יהיה הולד בן קיימא, \u0003אבל התם\u0004 \u0005[שם]\u0006 במינקת שהאיסור \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 הוא, שמא \u0003כרבנן סבירא ליה\u0004 \u0005[כ\u0006דעת \u0005חכמים סבור הוא]\u0006 שאם עבר וכנסה איננו חייב לגרשה לעולם!","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לומר להיפך: \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' מאיר התם\u0004 \u0005[שם]\u0006 שיוציא ולא יחזיר עולמית \u0003אלא משום\u0004 שהדבר הוא \u0003דרבנן\u0004 \u0005[דברי סופרים],\u0006 \u0003וחכמים עשו חיזוק לדבריהם יותר משל תורה,\u0004 שאם לא יחזקו דבריהם — יבואו לזלזל בהם, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 כיון שהוא איסור \u0003מדאורייתא\u0004 \u0005[מן התורה]\u0006 — \u0003מפרש פרשי מינה\u0004 \u0005[פורשים\u0006 אנשים \u0005ממנה]\u0006 במקום שאסור, ואם עבר אדם עבירה זו בשגגה אין צורך לקנוס אותו.","\u0003אמר רבא: ולדברי חכמים\u0004 בענין הנושא מעוברת חבירו, כשאמרו שעליו להוציאה, כוונתם: \u0003יוציאה בגט.\u0004 כלומר, לא רק שיוציאה מביתו ואחר כך יחזור ויביאנה הביתה, אלא כוונתם שמגרש אותה בגט. \u0003אמר מר זוטרא: דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 דבר זה מלשון הברייתא, \u0003דקתני\u0004 \u0005[ששנה]\u0006 שם: \u0003\"יוציא\", ולא קתני\u0004 \u0005[שנה]\u0006 \u0003\"יפריש\".\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שזה פירוש הדברים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרב הושעיא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: התם תנן\u0004 \u0005[שם\u0006 במשנה \u0005שנינו]:\u0006 \u0003רבן שמעון בן גמליאל אומר: כל\u0004 וולד \u0003ששהא\u0004 לאחר לידתו, והוא וולד \u0003אדם,\u0004 והזמן ששהה הוא \u0003שלשים יום\u0004 ולא מת — הרי זה מוכיח ש\u0003אינו נפל.\u0004 ואפילו אם מת לאחר מכן — מחמת חולי מת, אבל ילד של קיימא היה. משמע \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא שהא\u0004 זמן זה — \u0003ספיקא הוי\u0004 \u0005[ספק הוא],\u0006 ולענין יבמה — חולצת ולא מתייבמת.","\u0003ואיתמר\u0004 \u0005[ונאמר]\u0006 שנחלקו אמוראים בבעיה הבאה: יבמה שנולד לה בן, ו\u0003מת\u0004 אותו בן \u0003בתוך שלשים יום\u0004 ללידתו, \u0003ועמדה ונתקדשה\u0004 לאדם אחר, משום שהיתה סבורה שהיא פטורה מן הייבום בגלל הבן, נחלקו בכך אמוראים,","\u0003רבינא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר: אם אשת ישראל היא — חולצת.\u0004 שאין מחייבים אותה לצאת מזה שנתקדשה לו, אלא אומרים ליבם לחלוץ לה, כדי להוציאה מכלל ספק. שאם ילד זה היה נפל, והאשה לא הותרה לשוק בעצם לידתו — תחלוץ ותיפטר, וחליצה זו לא אסרה אותה לבעלה החדש, שהוא ישראל. אבל \u0003אם אשת כהן היא,\u0004 שנתקדשה לכהן, ואם תחלוץ תיפסל לו — \u0003אינה חולצת,\u0004 שלא הקפידו חכמים באופן כזה שאינו אלא ספק.","ואילו \u0003רב משרשיא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר: אחת זו ואחת זו חולצת,\u0004 ואם אשת כהן היא — תיאסר לו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב משרשיא:\u0004"],["\u0003באורתא\u0004 \u0005[בערב]\u0006 אכן \u0003אמר רבא הכי\u0004 \u0005[כך]\u0006 כפי שאתה אומר, \u0003ו\u0004אולם \u0003בצפרא הדר ביה\u0004 \u0005[בבוקר חזר בו\u0006 מדבריו\u0005]\u0006 ואני שמעתי מפיו שאמר שאשת כהן אינה חולצת. כעס רב משרשיא ו\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שריתו\u0004 \u0005[התרתם]\u0006 את הדבר? \u0003יהא רעוא דתשתרו אף תרבא\u0004 \u0005[יהי רצון שתתירו גם חלב],\u0006 שלדעתו לא כך היה הדבר, ואם התיר דבר זה — יכול להתיר אפילו חלב האסור מן התורה.","ועל סמך דין זה יש לשאול: \u0003הכא\u0004 \u0005[כאן]\u0006 ל\u0003גבי מעוברת חבירו ומינקת חבירו הנשואה לכהן, מאי\u0004 \u0005[מה]\u0006 יהא הדין לענין הפרשתה? \u0003מי עבוד רבנן תקנתא\u0004 \u0005[האם עשו חכמים תקנה]\u0006 \u0003לכהן\u0004 שתספיק הפרשה מפני שאם יגרשנה בגט שוב לא יוכל להחזירה לעולם, \u0003או\u0004 שמא \u0003לא\u0004 התכוונו לתקנה זו ויוציאה בגט.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי השתא\u0004 \u0005[כך עכשיו,\u0006 כיצד אתה משווה\u0005]?\u0006 \u0003בשלמא התם\u0004 \u0005[נניח שם]\u0006 בענין ספק נפל, \u0003כיון דאיכא רבנן דפליגי עליה\u0004 \u0005[שיש חכמים שחולקים עליו]\u0006 על \u0003רבן שמעון בן גמליאל, דאמרי\u0004 \u0005[שאומרים]:\u0006 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא שהא\u0004 שלושים יום, מכל מקום \u0003ולד מעליא הוי\u0004 \u0005[מעולה\u0006 שלם \u0005הוא],\u0006 ועל כן, \u0003גבי אשת כהן כיון דלא\u0004 \u0005[שאי]\u0006 \u0003אפשר\u0004 על ידי חליצה בלא להוציאה לעולם, \u0003עבדינן כרבנן\u0004 \u0005[עושים אנו כחכמים]\u0006 וסומכים על דבריהם שהוולד בן קיימא, ואינה זקוקה לחליצה,","\u0003אבל הכא, כמאן נעביד\u0004 \u0005[כאן, כמו מי נעשה]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004שיטת \u0003ר' מאיר — הא\u0004 \u0005[הרי]\u0006 \u0003אמר\u0004 יותר מזה: \u0003יוציא ולא יחזיר עולמית, ואי כרבנן\u0004 \u0005[ואם\u0006 נעשה \u0005כ\u0006שיטת \u0005חכמים] —\u0006 \u0003האמרי\u0004 \u0005[הרי אומרים\u0006 הם\u0005]\u0006 שמוציאה \u0003בגט\u0004 עד שתגמול את בנה, ואם כן בעל כרחו עליו לתת גט גם אם הוא כהן והיא תיאסר עליו עולמית.","באותו ענין של הנושא אשה לפני הזמן שהתירו לו חכמים \u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003קדשה\u0004 אדם לאלמנה \u0003בתוך שלשה\u0004 חודשים למות בעלה \u0003וברח, פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003רב אחא ורפרם, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: משמתינן ליה\u0004 \u0005[מנדים אותו]\u0006 על שעבר על דברי חכמים שאסרו לשאת כל אשה בתוך שלושה חודשים מאז יצאה מבעלה, שמא היא מעוברת, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: עירוקיה מסתייה\u0004 \u0005[בריחתו דיה לו],\u0006 שבזה שברח מראה הוא שאיננו רוצה לכנוס אותה עד שיגיע הזמן, ולכן אין לקנוס אותו יותר. ומספרים: \u0003הוה עובדא\u0004 \u0005[היה מעשה]\u0006 כגון זה \u0003ואמר להו\u0004 \u0005[להם]\u0006 \u0003רפרם\u0004 לשואלים בענין זה: \u0003עירוקיה מסתייה\u0004 \u0005[בריחתו דיה לו]\u0006 ואין מנדים אותו.","שנינו במשנה שאם היה הולד \u0003ספק בן תשע\u0004 חודשים לבעל ראשון, ספק בן שבעה לאחרון — יוציא, והוולד כשר. וחייבים באשם תלוי מספק שמא עברו על איסור כרת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: לימא\u0004 \u0005[נאמר]\u0006 \u0003הלך אחר רוב נשים, ו\u0004הלא \u0003רוב נשים לתשעה\u0004 חודשים \u0003ילדן\u0004 \u0005[יולדות],\u0006 ואם כן אין כאן ספק אלא אפשר לסמוך על הרוב ולא די להם באשם תלוי, אלא צריכים להביא חטאת, שבודאי עבר עבירה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003נשי דידן\u0004 \u0005[הנשים שלנו,\u0006 במשפחתנו\u0005],\u0006 \u0003לשבעה\u0004 חדשים \u0003ילדן\u0004 \u0005[\u0006הן \u0005יולדות].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: וכי \u0003נשי דידכו הוו רובא דעלמא\u0004 \u0005[הנשים שלכם הן רוב העולם]?\u0006 ובכן, בודאי רוב הנשים יולדות לתשעה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003הכי קאמינא\u0004 \u0005[כך אני אומר],\u0006 זו היתה כוונתי: \u0003רוב נשים ילדן\u0004 \u0005[יולדות]\u0006 \u0003לתשעה\u0004 חודשים, \u0003ומיעוט\u0004 בכל אופן יולדות \u0003לשבעה, ו\u0004כלל הוא: \u0003כל היולדת לתשעה עוברה\u0004 (הוולד שבמעיה), כלומר, דבר היותה מעוברת \u0003ניכר לשליש ימיה,\u0004 בחודש השלישי להריונה. \u0003וזו,\u0004 אותה יבמה שאנחנו דנים בה, \u0003הואיל ולא הוכר עוברה לשליש ימיה\u0004 שהרי לא ידעו שהיא מעוברת, ומשום כך כנס אותה היבם — \u0003איתרע ליה רובא\u0004 \u0005[הורע לו הרוב]\u0006 ויש לפקפק אם אמנם היא מן הרוב, ומשום כך נוצר הספק.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 אמנם ודאי כי \u0003כל היולדת לתשעה עוברה ניכר לשליש ימיה\u0004, אם כן \u0003הא\u0004 \u0005[זו]\u0006 \u0003מדלא\u0004 \u0005[מ\u0006כיון \u0005שלא]\u0006 \u0003הוכר\u0004 עוברה \u0003לשליש ימיה, עוברה ודאי בר שבעה לבתראה\u0004 \u0005[בן שבעה לאחרון]\u0006 \u0003הוא\u0004 ושוב אין כאן ספק! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 תקן כך את הלשון: \u0003רוב היולדות לתשעה — עוברה ניכר לשליש ימיה, והאי\u0004 \u0005[וזו]\u0006 \u0003מדלא\u0004 \u0005[מ\u0006כיון \u0005שלא]\u0006 \u0003הוכר לשליש ימיה — איתרע ליה רובא\u0004 \u0005[הורע לו הרוב]\u0006 ולכן ספק אם הוא בן תשעה לראשון או בן שבעה לאחרון.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ראשון:\u0004 אותו ילד שנולד ליבמה והיה ספק אם הוא לראשון או לאחרון, כיון שאפשר לסמוך שבכל מקרה הוא כשר, בין אם הוא מהראשון בין אם הוא מהשני, ו\u0003ראוי\u0004 אף \u0003להיות כהן גדול. ו\u0004אם לא יוציא אותה היבם, ותלד לו ילד \u0003שני —\u0004 הרי הוא \u0003ממזר מספק.\u0004 שהרי יש ספק אם הראשון הוא בן המת, ואם כן הריהי אסורה על היבם כערוה, ובנה השני הוא ממזר, או אולי גם הילד הראשון הוא בן היבם, והילד השני אף הוא כשר. \u0003ר' אליעזר בן יעקב אומר: אין ממזר מספק,\u0004","משמעות דברי ר' אליעזר בן יעקב אינה ברורה, ושואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר],\u0006 מה היתה כוונת דבריו? \u0003אמר אביי: הכי קאמר\u0004 \u0005[כך אמר]\u0006 כך יש להבין את המשנה: \u0003ראשון — ראוי להיות\u0004 אפילו \u0003כהן גדול, ושני\u0004 הוא \u0003ספק ממזר, ו\u0004לכן אסור לשאת בת ישראל — שהרי ספק ממזר הוא, אבל \u0003אסור\u0004 גם \u0003בממזרת,\u0004 משום שאין ברור שהוא ממזר, ואולי ישראל כשר הוא, ואסור בממזרת. ואילו \u0003ר' אליעזר\u0004 בן יעקב \u0003אומר: אינו ספק ממזר, אלא ודאי ממזר, ומותר בממזרת.\u0004","\u0003רבא אמר: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך היתה כוונת הדברים: \u0003ראשון ראוי להיות כהן גדול, ושני\u0004 הוא כ\u0003ממזר ודאי, מ\u0004חמת ה\u0003ספק, ו\u0004לכן \u0003מותר בממזרת. ור' אליעזר בן יעקב אומר: אין ודאי ממזר מספק.\u0004 שכיון שיש ספק כלשהו, אי אפשר להחשיב ילד זה כממזר ודאי, \u0003אלא ספק ממזר\u0004 הוא, \u0003ו\u0004לכן \u0003אסור בממזרת\u0004.","ומעירים: \u0003וקמיפלגי\u0004 \u0005[וחלוקים]\u0006 אביי ורבא \u0003ב\u0004דבריו של \u0003ר' אלעזר. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 העוסקת בדיני המשפחות והיחוסים השונים בעם ישראל, שיש ביניהם שאסורים ודאי לבוא בקהל, ויש כאלה שהם אסורים לבוא בקהל רק מחמת שיש בהם ספק איסור, ו\u0003ר' אלעזר אומר: ודאן בודאן\u0004 \u0005[וודאים בוודאים],\u0006 אלה שודאי אסורים לבוא בקהל — \u0003מותר\u0004 להם להתחתן אלה עם אלה, אבל \u0003ודאן בספקן\u0004 \u0005[וודאים בספיקות]\u0006 שאסורים לבוא בקהל רק מחמת הספק, \u0003וספקן בודאן\u0004 \u0005[וספיקות בוודאים],\u0006 שמא הספק אכן כשר ואסור לשאת את זה שהוא ודאי פסול, \u0003ו\u0004אפילו \u0003ספקן בספקן\u0004 \u0005[וספיקות בספיקות]\u0006 — \u0003אסור,\u0004 שמא אחד מהם כשר והשני פסול.","\u0003ואלו הן ספקן\u0004 \u0005[ספיקות],\u0006 שהאסורים לבוא בקהל רק מחמת הספק: \u0003שתוקי,\u0004 שהוא ילד שלא ברור מי אביו, שאנחנו מכירים את אמו אבל לא יודעים מי היה אביו. \u0003ואסופי\u0004 ילד שנאסף מן השוק, ושמא ממזר הוא. \u0003ו\u0004כן \u0003כותי\u0004 (שומרוני), שכיון שלא נהגו לפי ההלכה בנישואין וקידושין יש בהם חשש ממזרות.","\u0003ואמר רב יהודה אמר רב: הלכה כר' אלעזר.\u0004 וסיפר רב יהודה: \u0003כי אמריתה קמיה\u0004 \u0005[כאשר אמרתי אותה,\u0006 את ההלכה של רב \u0005לפני]\u0006 \u0003שמואל, אמר לי: הלל שנה\u0004 באותה משנה: \u0003עשרה יוחסין עלו מבבל: כהני\u0004 \u0005[כהנים],\u0006 \u0003לויי\u0004 \u0005[לויים],\u0006 \u0003וישראלי\u0004 \u0005[וישראלים],\u0006 \u0003חללי\u0004 \u0005[חללים,\u0006 בני כהנים שנפסלו מכהונתם\u0005],\u0006 \u0003גירי\u0004 \u0005[גרים],\u0006 \u0003חרורי\u0004 \u0005[\u0006עבדים \u0005משוחררים],\u0006 \u0003ממזרי\u0004 \u0005[ממזרים],\u0006 \u0003נתיני\u0004 \u0005[נתינים,\u0006 צאצאי הגבעונים\u0005],\u0006 \u0003שתוקי ואסופי. וכולן מותרין לבא זה בזה.\u0004 כלומר, רשימה זו מסודרת כך שכל שניים המצויים זה ליד זה מותר להם להתחתן זה בזה, דהיינו: כהנים בלויים, או לויים בישראלים, וכן ישראלים בחללים, או גרים ומשוחררים בממזרים, או ממזרים בנתינים, ונתינים וממזרים בשתוקי.","\u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 \u0003הלכה כר' אלעזר\u0004 שספיקות בוודאים אסורים, ולפי זה אין הלכה כהלל!","ומכאן גם המחלוקת בין אביי ורבא בענייננו: \u0003אביי סבר לה\u0004 \u0005[סבור\u0006 בהלכה זו\u0005]\u0006 \u0003כשמואל\u0004 ש\u0003אמר: הלכה כהלל, ו\u0004משום כך \u0003מוקי לה\u0004 \u0005[מעמיד\u0006 הוא \u0005אותה]\u0006 את שיטת \u0003ר' אליעזר בן יעקב אליבא דהלכתא\u0004 \u0005[על פי ההלכה],\u0006 שלדעת שמואל ספק ממזר מותר בממזר ודאי, \u0003כי היכי דלא תקשי הלכתא אהלכתא\u0004 \u0005[כדי שלא תהיה קשה הלכה על הלכה]\u0006 שאם פסק כהלל, ואנחנו יודעים שכל מקום ששנה ר' אליעזר בן יעקב במשנתנו הלכה כמותו, מן ההכרח שההלכות תהיינה בשיטה אחת.","ואילו \u0003רבא סבר לה\u0004 \u0005[סבור\u0006 בהלכה זו\u0005]\u0006 \u0003כרב,\u0004 ש\u0003אמר: הלכה כר' אלעזר,\u0004 שספק ממזר אסור בממזר ודאי. \u0003ו\u0004על כן גם הוא \u0003מוקי לה\u0004 \u0005[מעמיד אותה]\u0006 \u0003ל\u0004הלכה זו של \u0003ר' אליעזר בן יעקב אליבא דהלכתא\u0004 \u0005[לפי ההלכה]\u0006 לשיטתו, \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא תקשי\u0004 \u0005[תהיה קשה]\u0006"],["\u0003הלכתא אהלכתא\u0004 \u0005[הלכה על הלכה].\u0006","\u0003אמר אביי: מנא אמינא לה\u0004 \u0005[מניין אומר אני אותה],\u0006 את ההלכה, ש\u0003כל ספיקא\u0004 \u0005[ספק]\u0006 של פסול נישואין \u0003לר' אליעזר בן יעקב כ\u0004פסול \u0003ודאי משוי ליה\u0004 \u0005[עושה\u0006 הוא \u0005אותו]\u0006 —","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר: הרי שבא\u0004 אדם \u0003על נשים הרבה ואין יודע על איזהו מהן בא, וכן היא, שבאו עליה אנשים הרבה ואינה יודעת מאיזה מהן קבלה\u0004 את הזרע שממנו הרתה — הרי לאחר זמן, כשגדלים ילדים אלה, \u0003נמצא\u0004 שעלול \u0003אב\u0004 להיות \u0003נושא את בתו\u0004 שהרי יתכן שאשה זו שנשא היא בתו, וכן \u0003אח נושא את אחותו, ונתמלא כל העולם כולו\u0004 על ידי כך \u0003ממזרין. ועל זה נאמר: \"ומלאה הארץ זמה\"\u0004 (ויקרא יט, כט). משמע שאף שאין כאן אלא ספק, מכל מקום רואה בהם ר' אליעזר בן יעקב ממזרים.","\u0003ורבא אמר לך\u0004 \u0005[\u0006יכול \u0005לומר לך]:\u0006 \u0003הכי קאמר\u0004 \u0005[כך אמר\u0006 הפסוק\u0005],\u0006 כך יש לפרש את המלה \"זימה\": \u0003זו מה היא.\u0004 כלומר, אין אתה יודע מי הם ילדים אלה, אם כשרים הם או פסולים, ולא התכוון לומר שהם ממזרים ודאי.","באותה ברייתא עצמה נאמר: \u0003יתר על כן אמר ר' אליעזר בן יעקב,\u0004 שלא רק בזנות נאמר הדבר, אלא אף בנישואין, כשידוע מי האב: \u0003לא ישא אדם אשה במדינה זו וילך וישא אשה במדינה אחרת, שמא\u0004 יזדמן ו\u0003יזדווגו\u0004 הילדים \u0003זה לזה\u0004 בלי לדעת שהם בני אב אחד, \u0003ונמצא אח נושא את אחותו.\u0004","ושואלים: \u0003איני\u0004 \u0005[\u0006וכי \u0005כן הוא]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב כי איקלע\u0004 \u0005[כאשר\u0006 היה \u0005מזדמן]\u0006 \u0003ל\u0004עיר \u0003דרדשיר\u0004 לבדו, והיה שוהה שם זמן מסויים, היה \u0003מכריז ואמר: מאן הויא ליומא\u0004 \u0005[מי,\u0006 איזו אשה, רוצה \u0005להיות\u0006 אשתי \u0005ליום]\u0006 לזמן הקצר שאתעכב כאן. \u0003ו\u0004כן \u0003רב נחמן כי איקלע\u0004 \u0005[כאשר\u0006 היה \u0005מזדמן]\u0006 \u0003ל\u0004עיר \u0003שכנציב,\u0004 היה \u0003מכריז ואמר: מאן הויא ליומא\u0004 \u0005[מי\u0006 רוצה \u0005להיות\u0006 אשתי \u0005ליום],\u0006 משמע שחכמים אלה היו נושאים נשים בכמה מקומות רחוקים!","ומשיבים: \u0003שאני רבנן דפקיע שמייהו\u0004 \u0005[שונים חכמים שידוע שמם],\u0006 ולכן גם אם יוולד להם ילד במדינה אחרת ייחסו אותו על שם אביו המפורסם, ובודאי יידעו ילדיו מיהו אביהם.","על מנהג זה שנהגו אותם חכמים שואלים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא:\u0004 אשה ש\u0003תבעוה לינשא ונתפייסה\u0004 (הסכימה) להינשא — \u0003צריכה לישב שבעה נקיים,\u0004 שמא ראתה דם נדה ולא שמה לב לכך, ואם כן, כיצד יכלו לשאת אשה לאותו יום? הרי ספק נדה היא!","ומשיבים: \u0003רבנן שלוחייהו הוו משדרי ומודעי להו\u0004 \u0005[חכמים אלה היו שולחים שליחים\u0006 קודם לבואם \u0005ומודיעים להן],\u0006 כך שהאשה שהסכימה להינשא ידעה על הדבר זמן מסויים קודם לכן, וספרה לה שבעה נקיים. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003לרבנן\u0004 \u0005[לחכמים\u0006 אלה\u0005]\u0006 לא היתה כוונה לבוא על נשים אלה, אלא \u0003יחודי בעלמא\u0004 \u0005[ייחוד בלבד]\u0006 \u0003הוא דמייחדי להו\u0004 \u0005[ש\u0006היו \u0005מייחדים אותן]\u0006 כדי שתהיה להם הרגשה שאשה מצויה להם, ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003אינו דומה מי שיש לו פת בסלו למי שאין לו פת בסלו.\u0004 שמי שאין לו פת בסלו מרגיש יותר שהוא רעב, ולכן דאגו שלא יביאו עצמם למצב של תחושת מחסור.","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם בברייתא: \u0003ר' אליעזר בן יעקב אומר: לא ישא אדם אשתו ו\u0004בזמן שהוא נושא אותה \u0003דעתו לגרשה, משום שנאמר: \"אל תחרש על רעך רעה והוא יושב לבטח אתך\"\u0004 (משלי ג, כט).","במשנתנו דובר על הילד הראשון שנולד ליבמה שיש בו ספק אם הוא בנו של האח שמת, או בנו של היבם החי. ספק זה עשוי להביא גם לבעיות בדיני ממונות. כיצד? \u0003ספק\u0004 (זה שספק עליו בנו של מי הוא) \u0003ויבם שבאו לחלוק בנכסי מיתנא\u0004 \u0005[\u0006האח \u0005המת],\u0006","\u0003ספק אמר: אנא בר מיתנא\u0004 \u0005[אני בן המת]\u0006 \u0003הוא, ונכסי דידי הוא\u0004 \u0005[והנכסים שלי הם],\u0006 משום שאני בנו היחיד. \u0003ויבם אמר: את בראי דידי את, ולית לך ולא מידי בנכסי\u0004 \u0005[אתה בני שלי אתה, ואין לך ולא כלום בנכסים],\u0006 שהרי האח הכונס את היבמה יורש את נכסי האח שמת — \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003ממון המוטל בספק,\u0004 שאין לנו דרך להכריע מי מהם צודק, \u0003ו\u0004כמו בכל \u0003ממון המוטל בספק\u0004 הדין הוא ש\u0003חולקין.\u0004","ומקרה נוסף: \u0003ספק ובני יבם שבאו לחלוק בנכסי מיתנא\u0004 \u0005[\u0006האח \u0005המת].\u0006 \u0003ספק אמר: ההוא גברא\u0004 \u0005[אותו אדם],\u0006 כלומר, אני, \u0003בר מיתנא\u0004 \u0005[בן של המת]\u0006 \u0003הוא ונכסי דידי הוא\u0004 \u0005[והנכסים\u0006 כולם \u0005שלי הם]\u0006 ו\u0003בני\u0004 ה\u0003יבם אמרי\u0004 \u0005[אומרים]:\u0006 \u0003את\u0004 \u0005[אתה]\u0006 — בנו של אבינו, היבם, אתה, וממילא \u0003אחינו את\u0004 \u0005[אתה]\u0006 \u0003ומנתא הוא דאית לך בהדן\u0004 \u0005[ו\u0006רק \u0005חלק יש לך אתנו]\u0006 כשאר האחים.","\u0003סבור רבנן קמיה\u0004 \u0005[חשבו חכמים\u0006 שהיו \u0005לפני]\u0006 \u0003רב משרשיא למימר\u0004 \u0005[לומר]:\u0006 דבר זה \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003היא, דתנן\u0004 \u0005[ששנינו]\u0006 לגבי ילד שנולד לאדם שנשא אשה תוך שלושה חדשים לפרידתה מבעלה ונולד בן זה ולא ברור אם הוא בן הבעל הראשון או השני, שכאשר יש דיני ירושה בינו ובין בני הבעלים של אמו הוודאיים, \u0003הוא אינו יורש אותם —\u0004 שהרי לספק יש רק טענת ספק לגבי כל אחת מהירושות האלה, ושאר האחים, כל אחד לגבי ירושת אביו, הוא ודאי. \u0003ו\u0004אם מת — \u0003הם יורשין אותו\u0004 וחולקים ביניהם את נכסיו.","\u0003והכא איפכא\u0004 \u0005[וכאן,\u0006 בענין טענות נכסי האח המת, הרי זה \u0005להיפך],\u0006 הוא ודאי והם ספק, שהרי \u0003התם אמרי ליה\u0004 \u0005[שם אומרים\u0006 הם \u0005לו]\u0006 \u0003אייתי\u0004 \u0005[הבא]\u0006 \u0003ראיה\u0004 שאחינו אתה \u0003ושקול\u0004 \u0005[וקח]\u0006 את חלקך, והרי אין לו ראיה שהוא אחיהם, ואילו","\u0003הכא אמר להו: אייתו\u0004 \u0005[הביאו]\u0006 \u0003ראיה ושקולו\u0004 \u0005[וקחו],\u0006 שהרי לי יש בודאי חלק בירושת המת, בין משום שהוא אבי ובין משום שהוא דודי, ולכם יש רק טענות ספק.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב משרשיא: מי דמי\u0004 \u0005[האם דומה]?\u0006 \u0003התם, אינהו\u0004 \u0005[שם, הם]\u0006 באים בטענת \u0003ודאי ואיהו\u0004 \u0005[והוא]\u0006 בא בטענת \u0003ספק,\u0004 ואילו \u0003הכא, אידי ואידי\u0004 \u0005[כאן, זה וזה]\u0006 \u0003ספק\u0004 הוא, שמכל מקום אינו יכול לטעון בודאות שהוא בן המת.","\u0003אלא, אי דמיא למתניתין\u0004 \u0005[אם דומה\u0006 הדבר \u0005למשנתנו] —\u0006 \u0003להא דמיא\u0004 \u0005[לזה\u0006 הוא \u0005דומה]:\u0006 \u0003לספק ובני יבם שבאו לחלוק בנכסי יבם גופיה\u0004 \u0005[עצמו],\u0006 \u0003דהתם אמרי ליה\u0004 \u0005[ששם אומרים\u0006 הם, הבנים \u0005לו]:\u0006 \u0003אייתי\u0004 \u0005[הבא]\u0006 \u0003ראיה דאחונא את\u0004 \u0005[שאחינו אתה]\u0006 \u0003ושקול\u0004 \u0005[וקח]\u0006 שהם ודאי בירושת אביהם והוא ספק.","ומקרה נוסף: \u0003ספק ובני יבם שבאו לחלוק בנכסי יבם, לבתר דפלג\u0004 \u0005[לאחר שחלק]\u0006 ה\u0003יבם בנכסי מיתנא\u0004 \u0005[המת]\u0006 ונטל מחצית רכוש האח המת ואת השאר נטל הספק,","\u0003בני יבם אמרי\u0004 \u0005[אומרים]:\u0006 \u0003אייתי\u0004 \u0005[הבא]\u0006 \u0003ראיה דאחונא את\u0004 \u0005[שאחינו אתה]\u0006 \u0003ושקול\u0004 \u0005[וקח]\u0006 חלק כמותנו בכל הרכוש שהותיר אבינו, ואם אינך מביא ראיה — אינך נוטל כלום. \u0003אמר להו\u0004 \u0005[אומר להם]\u0006 ה\u0003ספק: מה נפשייכו\u0004 \u0005[רצונכם],\u0006 הלא בכל מקרה יש לי טענה, כי \u0003אי אחוכון אנא\u0004 \u0005[אם אחיכם אני] —\u0006 \u0003הבו לי מנתא בהדייכו\u0004 \u0005[תנו לי חלק אתכם]\u0006 בכל הנכסים של אביכם, \u0003ואי בר מיתנא אנא\u0004 \u0005[ואם בן המת אני]\u0006 — \u0003הבו לי פלגא דפלג אבוכון בהדאי\u0004 \u0005[תנו לי\u0006 לפחות את \u0005החצי,\u0006 את אותו חלק \u0005שחלק אביכם אתי]\u0006 ונטל מנכסי אבי המת, שהרי לטענתכם אני בן האח שמת ואני הוא שהייתי צריך לירש את כל רכושו.","\u0003ר' אבא אמר רב: קם דינא\u0004 \u0005[עומד הדין],\u0006 כלומר, כיון שכבר נעשה דין והספק התחלק עם היבם — אין הוא יכול עכשיו לבא ולערער מצד אחר על החלוקה. ולכן, כל עוד שאינו יכול להביא ראיה שהוא בן המת או בן החי, איננו נוטל דבר. \u0003ר' ירמיה אמר: הדר דינא\u0004 \u0005[חוזר הדין],\u0006 כלומר, בעל כורחם חייבים הם לתת לו — או חלק בנכסי היבם, או את כל נכסי המת.","ומציעים: \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 כי \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003אדמון ורבנן קמיפלגי\u0004 \u0005[חלוקים הם\u0006 כאן\u0005],\u0006 ומה היא מחלוקת זו, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מי שהלך למדינת הים\u0004 והשאיר שדה שהדרך אליו עוברת אצל שדות סמוכים של אחרים \u0003ו\u0004במשך הזמן, כיון שלא היו משתמשים בשדה, \u0003אבדה לו\u0004 ה\u0003דרך\u0004 אל \u0003שדהו\u0004 — \u0003אדמון אמר: ילך בקצרה,\u0004 כלומר, יבחר כמעבר לשדהו, ובין השדות הסמוכים, את הדרך הקצרה ביותר ובמי שפגע — פגע. \u0003וחכמים אומרים: יקח\u0004 (יקנה) \u0003לו דרך\u0004 אפילו \u0003במאה מנה,\u0004 או בכל אחר סכום שישיתו עליו, \u0003או יפרח באויר.\u0004 כלומר, אין הוא יכול לכפות על אחד מהם שיתן לו דרך בתוך שדהו, שכן אין לו הוכחה שבמקום זה עברה פעם הדרך שלו.","\u0003והוינן בה\u0004 \u0005[והיינו\u0006 עסוקים בשאלה \u0005זו]:\u0006 \u0003לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 הלא \u0003שפיר קאמר\u0004 \u0005[יפה אמר]\u0006 \u0003אדמון,\u0004 שהרי ודאי היתה לו דרך באותו מקום, וכיצד אפשר לדחות אותו ממנה לגמרי? \u0003ואמר רב יהודה אמר רב: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים] —\u0006 \u0003כגון שהקיפוה ארבעה בני אדם מארבע רוחות.\u0004 ולכן, כאשר הוא בא לאדם אחד ואומר \"תן לי דרך\" עונה לו הלה: הבא לי הוכחה שהדרך שלך עברה בתוך השדה שלי, שמא היתה אצל איש אחר. וכיון שכל אחד יכול לדחות אותו בכך — אין לו מקום שהוא יכול לעבור דרכו.","ושואלים: \u0003אי הכי מאי טעמא\u0004 \u0005[אם כך, מה הטעם]\u0006 של \u0003אדמון,\u0004 ומדוע יבחר לו דרך כלל? הלא בעל אותו השדה יכול לדחות אותו לאחרים! \u0003ואמר רבא: ב\u0004מקרה שהיו שם \u0003ארבעה\u0004 אנשים שונים \u0003דאתו\u0004 \u0005[שבאו]\u0006 \u0003מכח ארבעה\u0004 שהיו מתחילה ארבעת השדות של בעלים שונים, או אם היו כאן \u0003ארבעה\u0004 אנשים \u0003דאתו\u0004 \u0005[שבאו]\u0006 \u0003מכח חד\u0004 \u0005[\u0006של אדם \u0005אחד],\u0006 שכולם קנו את השדות הסמוכים מאדם אחד — \u0003כולי עלמא לא פליגי דמצו מדחי ליה\u0004 \u0005[הכל אינם חלוקים\u0006 בכך \u0005שהם יכולים לדחות אותו]\u0006 וכל אחד יכול לומר לו: לא אצלי היא דרכך ולך לחברי.","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו],\u0006 הרי זה \u0003בחד דאתי\u0004 \u0005[ב\u0006אדם \u0005אחד שבא]\u0006 \u0003מכח ארבעה,\u0004 שעכשיו שייכים השדות לאדם אחד, אלא שהוא קנה אותם מארבעה אנשים שונים. ש\u0003אדמון סבר: מצי אמר ליה\u0004 \u0005[יכול\u0006 בעל השדה שבאמצע \u0005לומר לו]\u0006 לבעל השדות הסמוכים: \u0003מכל מקום\u0004 ובכל אופן \u0003דרכי גבך הוא\u0004 \u0005[אצלך היא],\u0006 שהרי ודאי עברה הדרך באחד משדותיך. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 \u0003דאמר ליה\u0004 \u0005[שאומר\u0006 הוא \u0005לו]\u0006 בעל השדות: \u0003אי שתקת\u0004 \u0005[אם אתה שותק]\u0006 ומנסה לעשות אתי פשרה \u0005—\u0006 \u0003שתקת\u0004 \u0005[שתוק]\u0006 ומוטב לך, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא — מהדרנא שטרא למרייהו\u0004 \u0005[אחזיר\u0006 את \u0005השטרות לבעליהם],\u0006 כלומר, הרי יכול אני להחזיר את השדות לבעליהם הראשונים \u0003ולא מצית\u0004 \u0005[תוכל]\u0006 \u0003לאשתעויי דינא בהדייהו\u0004 \u0005[לדבר בדין אתם]\u0006 שהרי הם יוכלו לדחות אותך מאיש לאיש, ומוטב שתתפשר, ועל כרחך צריך אתה לעשות אתי פשרה.","ואם כן \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 כי \u0003ר' אבא\u0004 ש\u0003אמר\u0004 בענין ירושת נכסי היבם שלאחר שפסקו לספק והיבם שיחלקו בנכסי המת שוב אי אפשר להחזיר את הדין — \u0003כרבנן\u0004 \u0005[כ\u0006דעת \u0005חכמים]\u0006 הוא סבור, וכיון שמתחילה (כשהיו ארבעה) לא יכול לכפותם לתת לו דרך קצרה — איבד זכותו בדרך.","\u0003ו\u0004אילו \u0003ר' ירמיה\u0004 ש\u0003אמר\u0004 שכיון שבודאי יש לו חלק בירושה על ידי שיחזירו את הדין, יש מקום לעמוד בדין ויקבל את חלקו — \u0003כאדמון\u0004 הוא סבור, שהרי במצב הדברים כעת הכל נמצא ברשות בעל שדה אחד וחוזר הדין.","ודוחים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003ר' אבא: אנא דאמרי\u0004 \u0005[אני שאומר אני\u0006 את דברי\u0005],\u0006 יכול להיות ש\u0003אפילו כ\u0004שיטת \u0003אדמון\u0004 נכונים הם, כי אין הדברים דומים: שכן \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003אדמון התם\u0004 \u0005[שם]\u0006 שהוא יכול לקחת דרך כלשהי, \u0003אלא משום דאמר ליה\u0004 \u0005[שאומר לו]\u0006 בעל השדה שבאמצע לבעלי השדות הסמוכים: \u0003ממה נפשך\u0004 \u0005[רצונך,\u0006 בכל אופן\u0005]\u0006"]]};
